const DATA = [

/* ============================ 1. АПОЛОГЕТИКА ============================ */
{
 id:"apologetika", title:"Апологетика",
 sub:"Разумность веры и доводы о бытии Божием",
 qa:[
  {q:"Что такое апологетика?",
   a:`<p>Апологетика — раздел богословия, который обосновывает разумность христианской веры, отвечает на возражения и защищает её от искажений. Слово происходит от греческого «апология» — «защита», «речь в оправдание на суде».</p>
   <p>Важно понимать её задачу верно: апологетика не заменяет веру доказательством и не «принуждает» к ней логикой. Вера остаётся свободным доверием сердца Богу. Но апологетика показывает, что это доверие не слепо: оно согласно с разумом и опирается на действительные основания — устройство мира, свидетельство совести, исторические события и опыт Церкви.</p>
   <p>Она исполняет прямое указание апостола Петра: быть всегда готовыми «всякому, требующему у вас отчёта в вашем уповании, дать ответ с кротостью и благоговением» ([[1 Пет 3:15]]). Уже во II веке христианские писатели-апологеты (Иустин Философ, Афинагор, Тертуллиан) обращались к языческому обществу и властям, защищая веру от клеветы и объясняя её разумность.</p>`, s:SRC.pis+" · "+SRC.ist},
  {q:"Можно ли строго доказать существование Бога?",
   a:`<p>Строгого доказательства, принуждающего разум так же неотвратимо, как теорема геометрии, нет — и Суинберн считает, что его и не должно быть: будь оно, вера перестала бы быть свободным нравственным выбором. Но отсутствие принудительного доказательства не значит, что вера безосновательна.</p>
   <p>Суинберн различает три силы доводов. <em>Дедуктивный</em> довод — из истинных посылок вывод следует с необходимостью. <em>«П-индуктивный»</em> — посылки делают вывод <em>более вероятным, чем неверно</em> (вероятность выше половины). <em>«C-индуктивный»</em> — посылки лишь <em>повышают</em> вероятность вывода, не доводя её сами по себе до перевеса.</p>
   <p>Его стратегия такова: каждый отдельный довод о бытии Божием — C-индуктивный (только повышает вероятность), но сложенные вместе, как накапливающиеся улики в суде, они образуют сильный П-индуктивный аргумент. Итог, к которому приходит Суинберн: с учётом всех данных существование Бога более вероятно, чем его отсутствие.</p>`, s:SRC.sw},
  {q:"На какие доводы опирается Суинберн — априорные или апостериорные?",
   a:`<p>Суинберн сознательно строит защиту веры на <em>апостериорных</em> доводах — тех, что исходят из опыта, из наблюдаемых черт мира и человека. В них утверждается, что нечто в человеческом опыте (существование вселенной, её порядок, сознание, чудеса, религиозный опыт) служит основанием для веры в Бога.</p>
   <p><em>Априорные</em> доводы — те, где посылки суть логически необходимые истины (математики и логики), не зависящие от существования мира. К ним относится онтологическое доказательство. Суинберн намеренно его не использует, считая, что бытие Бога нельзя вывести из одних определений; существование Бога — не логическая необходимость такого рода, а наилучшее объяснение реального мира.</p>`, s:SRC.sw},
  {q:"Что такое естественная теология?",
   a:`<p>Естественная теология — это познание Бога, доступное человеческому разуму из наблюдения над миром и над собой, без опоры на прямое сверхъестественное откровение. Она восходит от общедоступных фактов к их наилучшему объяснению — к Богу.</p>
   <p>Такой путь признаёт и само Писание: «невидимое Его, вечная сила Его и Божество, от создания мира через рассматривание творений видимы» ([[Рим 1:20]]); «небеса проповедуют славу Божию» ([[Пс 18:2]]). Естественная теология не даёт всей полноты богопознания (её открывает Христос), но показывает, что вера в Творца разумна. Именно её и разрабатывает Суинберн.</p>`, s:SRC.sw+" · "+SRC.pis},
  {q:"Чем «личностное» объяснение отличается от научного?",
   a:`<p>Суинберн различает два рода объяснения. <em>Научное</em> объясняет событие через предшествующие причины и законы природы («почему нагрелась вода» — через физику). <em>Личностное</em> объясняет событие через разумного деятеля (агента), его намерения и способности («почему на столе чай» — потому что человек намеренно его заварил).</p>
   <p>Бытие и устройство мира в целом наука объяснить не может: сами законы природы — это то, что нуждается в объяснении, а не то, чем объясняют всё остальное. Здесь уместно личностное объяснение: мир существует и упорядочен потому, что его намеренно создало разумное Существо — Бог. Так теизм объясняет то, перед чем наука останавливается.</p>`, s:SRC.sw},
  {q:"Почему простота гипотезы так важна?",
   a:`<p>По Суинберну, вероятность любой гипотезы зависит главным образом от двух вещей: насколько она <em>проста</em> и насколько хорошо согласуется с фоновым знанием. Из двух объяснений, равно покрывающих факты, разумно предпочесть более простое — постулирующее меньше сущностей и более единообразное. Этим правилом пользуется и наука.</p>
   <p>Теизм отвечает критерию простоты как никакая другая гипотеза о первопричине: он объясняет всё через <em>одно</em> Существо. Причём бесконечное свойство (всемогущество, всеведение) проще конечного, потому что не требует объяснять, «почему именно столько силы или знания», — бесконечность не имеет произвольной границы.</p>
   <p>Поэтому теизм обладает высокой <em>априорной вероятностью</em> — он вероятен ещё до рассмотрения конкретных свидетельств, как самое экономное возможное объяснение существования и порядка мира. Гипотеза же множества богов или бога ограниченного сложнее и потому менее вероятна.</p>`, s:SRC.sw},
  {q:"В чём суть космологического аргумента?",
   a:`<p>Космологический аргумент идёт от самого факта существования вселенной к её Причине. Мир не объясняет себя сам: он мог бы и не существовать вовсе, и наука, описывая, <em>как</em> он устроен, не отвечает, <em>почему</em> вообще есть нечто, а не ничто.</p>
   <p>Суинберн строит его как индуктивный вывод в рамках личностного объяснения: существование сложной, упорядоченной физической вселенной — то, чего мы не ожидали бы «просто так», но чего разумно ожидать, если её намеренно создал Бог. Следовательно, сам факт бытия мира повышает вероятность теизма (это C-индуктивный шаг).</p>
   <p>Это перекликается с исповеданием веры: «В начале сотворил Бог небо и землю» ([[Быт 1:1]]); «всё чрез Него начало быть» ([[Ин 1:3]]). Бог здесь — не первая причина <em>внутри</em> цепочки мировых причин, а Причина самого существования этой цепочки.</p>`, s:SRC.sw},
  {q:"В чём суть телеологического аргумента?",
   a:`<p>Телеологический аргумент (от греч. «телос» — цель) идёт от порядка в мире к разумному Устроителю. Суинберн придаёт особое значение не «пространственному» устройству отдельных вещей (что критиковал ещё Юм), а <em>временно́му</em> порядку — тому, что вся вселенная во всякое время и в каждой точке действует по одним и тем же простым, единообразным законам.</p>
   <p>Это всеохватное единообразие само требует объяснения. Оно естественно, если мир создан единым разумным Существом, желающим упорядоченного, познаваемого космоса, и крайне маловероятно как результат чистой случайности: случайность породила бы хаос, а не стройный закон. «Небеса проповедуют славу Божию, и о делах рук Его вещает твердь» ([[Пс 18:2]]).</p>`, s:SRC.sw},
  {q:"Что такое аргумент от «тонкой настройки» вселенной?",
   a:`<p>Это сильный современный вариант телеологического довода. Физика показывает, что фундаментальные постоянные и начальные условия вселенной «настроены» в чрезвычайно узких пределах: даже ничтожное их изменение исключило бы образование звёзд, химических элементов и жизни.</p>
   <p>Суинберн рассуждает так: без Бога столь точная настройка мира именно на возникновение телесных разумных существ была бы a priori крайне маловероятной случайностью. Но для благого Творца, желающего разумных существ, способных познавать мир и свободно действовать в нём, она вполне ожидаема. Человеческое тело в этой логике — не случайность, а средство, которым дух познаёт мир и осуществляет свои цели.</p>
   <p>Таким образом, факт «тонкой настройки» повышает вероятность того, что за миром стоит замысел, а не слепой случай.</p>`, s:SRC.sw},
  {q:"Как из существования сознания следует довод о Боге?",
   a:`<p>Материя, действующая по физическим законам, сама по себе не влечёт с необходимостью появления сознания — субъективного внутреннего опыта: переживания боли, цвета, мысли, «каково это» — быть кем-то. Физика описывает поведение материи, но само наличие внутренней, переживаемой жизни остаётся для неё загадкой.</p>
   <p>Суинберн доказывает: возникновение сознательных существ гораздо вероятнее, если есть Бог, желающий существ, способных мыслить, чувствовать и любить, чем если мир — лишь бесцельное движение частиц, у которого нет причины «зажигать» внутренний свет сознания. Поэтому сам факт сознания служит ещё одним доводом в пользу теизма.</p>`, s:SRC.sw},
  {q:"Что такое нравственный аргумент?",
   a:`<p>Люди сознают объективное различие добра и зла и чувствуют себя <em>обязанными</em> поступать хорошо, даже вопреки выгоде и инстинкту. Из одной материи и эволюционной пользы трудно вывести <em>подлинную</em> обязательность — не просто полезную привычку, а долг, который остаётся долгом, даже когда его нарушение выгодно и безнаказанно.</p>
   <p>Наличие такого объективного нравственного закона указывает на его Источник — благого Бога, вложившего в разумную тварь различение добра и зла. Апостол пишет о язычниках, не имевших писаного закона, но у которых «дело закона написано в сердцах» ([[Рим 2:15]]). Совесть — свидетель этого закона.</p>`, s:SRC.sw+" · "+SRC.pis},
  {q:"Что такое аргумент от Промысла?",
   a:`<p>Мир устроен так, что даёт разумным существам необычайно широкую возможность: познавать законы природы, свободно выбирать и реально влиять на себя, на других и на среду, в том числе заботиться друг о друге и нести ответственность. Это устройство особенно ценно именно для нравственного возрастания.</p>
   <p>Суинберн замечает: такой мир — не бездумный «рай наслаждений» и не хаос, а поприще ответственного действия, где выбор имеет вес, — естественно ожидать от благого Бога, дающего Своим созданиям высокое достоинство соучастия в добре и в устроении жизни. Господь говорит: «Отец Мой доныне делает, и Я делаю» ([[Ин 5:17]]).</p>`, s:SRC.sw},
  {q:"Если Бог благ и всемогущ, почему в мире есть зло?",
   a:`<p>Это главное возражение против веры, и Суинберн отвечает на него теодицеей — оправданием благости Бога перед лицом зла. Он различает зло <em>нравственное</em> (причиняемое злой волей людей) и <em>естественное</em> (болезни, стихийные бедствия, страдания животных), и объясняет их по-разному.</p>
   <p>Ключ — свобода и высшие блага. Целый ряд величайших благ — мужество, сострадание, самопожертвование, прощение, терпение, рост в добре — по самой своей природе возможны лишь там, где есть реальный выбор, трудность и даже страдание. Дать творению подлинную свободу творить добро — значит допустить и возможность зла; отнять эту возможность значило бы отнять и свободу, и высшие блага.</p>
   <p>Поэтому мир со свободой и риском зла может быть лучше «стерильного» мира, где зло невозможно, потому что там невозможно и настоящее добро. Вера добавляет к этому надежду: «нынешние временные страдания ничего не стоят в сравнении с той славою, которая откроется в нас» ([[Рим 8:18]]).</p>`, s:SRC.sw},
  {q:"Зачем в мире естественное зло — болезни и катастрофы?",
   a:`<p>Труднее всего объяснить не злодеяния людей (они — плата за свободу), а «естественное» зло — страдание, не зависящее от чьей-то злой воли. Суинберн предлагает несколько взаимодополняющих соображений.</p>
   <p>Во-первых, естественное зло создаёт саму возможность знания о последствиях и, значит, ответственного выбора: наблюдая, что причиняет вред, человек получает и знание, и власть предотвращать зло или помогать. Во-вторых, оно открывает простор для высших добродетелей — мужества перед бедой, терпения в болезни, сострадания и самоотвержения, — которых в мире без страдания просто не могло бы быть.</p>
   <p>Даже в мире животных, чья свобода ограничена, страдание связано с благом: способность беречь потомство, избегать опасности, сочувствовать. Страдание при этом не самоцель и не благо само по себе — это цена мира, в котором возможно подлинное, а не игрушечное добро. Бог, по вере, не остаётся вне этого страдания, но Сам входит в него на Кресте.</p>`, s:SRC.sw},
  {q:"Что такое аргумент от чудес и истории?",
   a:`<p>Если уже есть основания считать, что благой Бог существует и может действовать в мире, то исторические свидетельства о чудесах перестают быть заведомо невероятными, как их объявлял, например, Юм. Чудо Суинберн понимает как событие, вызванное особым действием Бога и выходящее за рамки естественного хода природы — ради блага людей и как знамение.</p>
   <p>Центральное для христианства историческое свидетельство — Воскресение Христово. Апостолы проповедовали его как очевидцы, преобразившиеся из напуганных беглецов в бесстрашных свидетелей, шедших ради этого на смерть. Такие исторически засвидетельствованные события служат дополнительным и сильным доводом в пользу теизма и истинности именно христианского откровения.</p>`, s:SRC.sw},
  {q:"Что такое аргумент от религиозного опыта?",
   a:`<p>Это довод от того, что огромному множеству людей всех эпох и культур «является» присутствие Бога — в молитве, в переживании священного, в озарении, а немногим — в мистическом видении. Суинберн систематизирует такой опыт и придаёт ему доказательную силу, а не отмахивается от него как от иллюзии.</p>
   <p>Опора здесь — «принцип доверия»: разумно принимать, что вещи таковы, какими они являются, пока нет особых причин думать иначе. Если этим принципом мы пользуемся во всяком познании (доверяя восприятию), то и массовое, устойчивое свидетельство о богоприсутствии следует принимать всерьёз: оно повышает вероятность бытия Божия. Господь обещал: «ищущий находит» ([[Мф 7:8]]).</p>`, s:SRC.sw},
  {q:"Что такое «принцип доверия» (credulity)?",
   a:`<p>Принцип доверия — введённое Суинберном правило рациональности: <em>если субъекту кажется, что нечто существует (и имеет такие-то признаки), то, при отсутствии особых опровергающих оснований, вероятно, оно действительно существует</em>. То же касается и явных воспоминаний.</p>
   <p>Без этого принципа рухнуло бы всякое познание: мы вынуждены доверять восприятию и памяти, иначе не смогли бы знать ничего вообще — даже результатов научных наблюдений. Суинберн распространяет это правило и на религиозный опыт, но с честными оговорками: сила доверия убывает, если известны искажающие обстоятельства (наркотическое воздействие, психическое расстройство) или есть весомые независимые основания сомневаться. При их отсутствии свидетельство опыта остаётся в силе.</p>`, s:SRC.sw},
  {q:"Какие виды религиозного опыта различает Суинберн?",
   a:`<p>Суинберн выделяет пять видов. Первый и второй — <em>общедоступные</em>: человек воспринимает Бога через обычный публичный объект (например, созерцая красоту звёздного неба) или через необычное общественное событие. Третий — восприятие Бога через частное явление, которое можно описать обычными словами (как ангел, обращающийся к человеку).</p>
   <p>Четвёртый — частный опыт, который субъект не в силах передать обычным языком (собственно мистический опыт). Пятый — опыт, в котором вообще нет чувственного восприятия, но человек непосредственно, «без образов», сознаёт присутствие Бога. Все пять видов, по принципу доверия, служат свидетельством; вместе они образуют внушительный корпус данных, с которым надо считаться.</p>`, s:SRC.sw},
  {q:"Как все доводы соединяются вместе?",
   a:`<p>Суинберн настойчиво подчёркивает: ни один аргумент не решает вопрос в одиночку — сила именно в их совокупности, как в суде вывод следует из совокупности улик, а не из одной. Он рассматривает их по «соотношению вероятностей»: складывает высокую априорную вероятность теизма (от его простоты) и вклад каждого свидетельства в отдельности.</p>
   <p>Существование упорядоченной вселенной, её тонкая настройка, сознание, объективная нравственность, промыслительное устройство мира, чудеса истории и религиозный опыт — каждый факт по отдельности лишь <em>повышает</em> вероятность (C-индуктивно). Но сложенные вместе, по итоговой оценке Суинберна, они делают существование Бога <em>более вероятным, чем его отсутствие</em> — то есть образуют убедительный П-индуктивный аргумент.</p>`, s:SRC.sw},
  {q:"Противоречат ли наука и вера?",
   a:`<p>Нет. Наука и вера отвечают на разные вопросы и работают на разных уровнях. Наука описывает, <em>как</em> устроен мир и по каким законам он действует; вера отвечает, <em>почему</em> вообще есть упорядоченный мир и сами эти законы и в чём его смысл и цель.</p>
   <p>Даже полное научное описание любого процесса не отменяет вопроса о причине самого бытия и порядка: законы природы объясняют события внутри мира, но не объясняют, откуда взялись сами законы. Поэтому объяснение «через законы природы» и объяснение «через замысел Бога» не конкурируют — второе глубже первого: Бог есть Причина того, что вообще существуют работающие законы. Многие крупные учёные были при этом людьми глубокой веры.</p>`, s:SRC.sw},
  {q:"Не объясняет ли теория эволюции сложность мира без Бога?",
   a:`<p>Эволюция может объяснять, как из простых форм жизни постепенно развились сложные, но она предполагает уже готовыми и саму жизнь, и точно настроенные законы природы, делающие такое развитие возможным. Откуда взялись эти законы и условия — вопрос, на который эволюция в принципе не отвечает.</p>
   <p>Суинберн указывает: механизм естественного отбора сам есть часть того упорядоченного, «тонко настроенного» мира, который и нуждается в объяснении. Поэтому верующий может спокойно принимать научную картину развития жизни, видя в ней <em>способ</em>, которым Бог осуществляет Свой замысел, а не замену Творцу. Эволюция описывает механизм; она не устраняет вопроса о его Устроителе.</p>`, s:SRC.sw},
  {q:"Разве множество разных религий не опровергает веру?",
   a:`<p>Разнообразие религий скорее показывает, что человек по самой своей природе религиозен — ищет Бога и смысла, — чем то, что все они ложны. Разнообразие мнений в науке или философии ведь не означает, что истины нет; оно означает, что к ней идут разными путями и с разным успехом.</p>
   <p>Христианство утверждает, что во Христе Бог открыл Себя полнее и окончательнее всего, но признаёт и то, что отблески истины и подлинного богоискания были и вне его. Апостол говорит, что Бог «не переставал свидетельствовать о Себе благодеяниями» всем народам ([[Деян 14:17]]), а полноту истины даровал во Христе. Различие религий требует не отчаяния, а различения.</p>`, s:SRC.sw+" · "+SRC.pis},
  {q:"Почему Бог не сделает Своё существование очевидным для всех?",
   a:`<p>Слишком явное, принудительное знание о Боге лишило бы человека свободы в самом главном — в свободном обращении к Богу любовью и доверием. Вера возможна только там, где остаётся место и для сомнения; иначе не было бы ни личного выбора, ни нравственной заслуги, а лишь вынужденное признание очевидного, как признают силу тяготения.</p>
   <p>Поэтому Бог оставляет достаточно свидетельств для искренне ищущего сердца, но не «подавляет» волю неотразимой очевидностью. Господь ублажает «не видевших и уверовавших» ([[Ин 20:29]]); пророк говорит о «Боге сокровенном» ([[Ис 45:15]]), Который открывается смиренным и взыскующим Его. Сокрытость Бога — не равнодушие, а условие свободной любви.</p>`, s:SRC.sw+" · "+SRC.pis},
  {q:"Разве вера — это не просто субъективное чувство?",
   a:`<p>Христианская вера включает доверие сердца, но не сводится к настроению или эмоции. Она опирается на исторические события — жизнь, смерть и Воскресение Христа, засвидетельствованные очевидцами, — на разумные доводы естественной теологии и на многовековой опыт Церкви и святых.</p>
   <p>Само библейское слово «вера» (греч. «пистис») ближе к «верности» и «доверию», чем к «мнению без оснований»: это разумное доверие Тому, Кого есть весомые основания считать благим и истинным, а не слепой прыжок в темноту. «Вера же есть осуществление ожидаемого и уверенность в невидимом» ([[Евр 11:1]]) — то есть твёрдая опора, а не зыбкое чувство.</p>`, s:SRC.sw+" · "+SRC.pis}
 ]
},

/* ============================ 2. БИБЛИОЛОГИЯ ============================ */
{
 id:"bibliologiya", title:"Учение о Священном Писании",
 sub:"Библиология: канон, богодухновенность, толкование",
 qa:[
  {q:"Что такое Священное Писание?",
   a:`<p>Священное Писание, или Библия (греч. «книги»), — это собрание книг, написанных святыми людьми по вдохновению Святого Духа и признанных Церковью богооткровенными. В них Бог открывает людям Себя, Свою волю и путь спасения.</p>
   <p>Догматическое богословие подчёркивает, что Писание не «упало с неба» готовым, а слагалось в течение веков внутри народа Божия и Церкви: пророки, апостолы и евангелисты записывали то, что открывал Бог. Поэтому Писание — не единственный, но важнейший письменный источник вероучения, и вместе со Священным Преданием составляет единое слово Божие.</p>
   <p>О его назначении говорит сам апостол: «всё Писание богодухновенно и полезно для научения, для обличения, для исправления, для наставления в праведности, да будет совершен Божий человек» ([[2 Тим 3:16]]). Цель Писания — не удовлетворить любопытство, а привести человека ко спасению.</p>`, s:SRC.dog},
  {q:"Что такое богодухновенность?",
   a:`<p>Богодухновенность — это особое действие Святого Духа на священных писателей, под которым они излагали истину Божию верно и без заблуждения в том, что касается веры и спасения. Дух был подлинным Виновником Писания, но действовал не как через безвольные орудия.</p>
   <p>Важнейшая черта церковного понимания: Дух не подавлял личности писателя. Каждый писал своим языком, в своём стиле, в своих исторических обстоятельствах — оттого книги Библии так различны по образу изложения, оставаясь едиными по духу. Писание потому есть вполне слово Божие и вместе слово человеческое — подобно тому как Христос есть истинный Бог и истинный человек.</p>
   <p>«Никогда пророчество не было произносимо по воле человеческой, но изрекали его святые Божии человеки, будучи движимы Духом Святым» ([[2 Пет 1:21]]).</p>`, s:SRC.dog},
  {q:"Из скольких частей состоит Библия?",
   a:`<p>Библия делится на две большие части — Ветхий и Новый Завет. Слово «завет» означает союз, договор Бога с людьми. Ветхий Завет — книги, написанные до пришествия Христа: о сотворении мира, о союзе Бога с народом Израиля, о законе и об ожидании Спасителя. Новый Завет — книги о пришедшем Христе и о рождённой Им Церкви.</p>
   <p>Оба Завета говорят об одном едином деле спасения, но на разных его ступенях: Ветхий приготовляет и прообразует, Новый исполняет обещанное. Блаженный Августин выразил их связь так: Новый Завет в Ветхом скрывается, а Ветхий в Новом открывается.</p>
   <p>Что весь Ветхий Завет ведёт ко Христу, засвидетельствовал Сам воскресший Господь, когда «начав от Моисея, из всех пророков изъяснял им сказанное о Нём во всём Писании» ([[Лк 24:27]]).</p>`, s:SRC.dog},
  {q:"Что такое канон Писания?",
   a:`<p>Канон (греч. «правило», «мерило») — это список книг, которые Церковь признала подлинно богодухновенными и включила в состав Писания, отличив их от книг лишь назидательных или от подложных сочинений, ходивших под именами апостолов.</p>
   <p>Новый Завет содержит 27 книг: четыре Евангелия, Деяния апостолов, семь соборных посланий, четырнадцать посланий апостола Павла и Апокалипсис. Их состав не был установлен единовластным решением, а постепенно узнан Церковью по всеобщему употреблению в богослужении и утвердился к IV веку. Ветхозаветный канон Церковь приняла в его греческом (Септуагинтовом) объёме, более широком, чем позднейший еврейский.</p>`, s:SRC.pis+" · "+SRC.dog},
  {q:"Что такое Евангелие?",
   a:`<p>Слово «Евангелие» значит «благая весть» — весть о спасении, дарованном во Христе. В узком смысле так называют четыре книги, повествующие о жизни, учении, крестной смерти и Воскресении Господа: от Матфея, Марка, Луки и Иоанна.</p>
   <p>Первые три Евангелия называют синоптическими (от греч. «общий взгляд»), потому что они близки по содержанию, порядку событий и даже словам, и их можно рассматривать «в одном обзоре». Евангелие от Иоанна отличается более созерцательным, богословским изложением, раскрывая тайну Божества Христа.</p>
   <p>Церковь принимает не «евангелия вообще», а именно эти четыре как единое четвероевангелие — одно благовестие в четырёх изложениях; многочисленные позднейшие апокрифические «евангелия» она отвергла как неподлинные.</p>`, s:SRC.pis},
  {q:"Что такое Пятикнижие?",
   a:`<p>Пятикнижие — первые пять книг Библии: Бытие, Исход, Левит, Числа и Второзаконие, по преданию написанные пророком Моисеем. По-еврейски они называются «Тора» — «Закон», «Наставление», и составляют основание всего Ветхого Завета.</p>
   <p>Бытие повествует о сотворении мира, о грехопадении и о патриархах; Исход — об избавлении народа из египетского рабства и о даровании закона на Синае; Левит, Числа и Второзаконие излагают богослужебный и нравственный закон и историю странствия к обетованной земле.</p>
   <p>Авторитет Пятикнижия для веры высок: Сам Господь ссылается на слова, сказанные Богом Моисею при купине, как на довод о воскресении ([[Исх 3:6]]).</p>`, s:SRC.pis},
  {q:"Кто такие пророки?",
   a:`<p>Пророки — избранные Богом мужи, которых Дух Святой призывал возвещать народу волю Божию. Пророчество — не столько предсказание будущего, сколько «изречение от лица Божия»: обличение греха, призыв к покаянию, утешение и возвещение грядущего спасения.</p>
   <p>Различают великих пророков (Исаия, Иеремия, Иезекииль, Даниил) и двенадцать малых — по объёму их книг, а не по значению. Через Иеремию Бог обещал «новый завет» ([[Иер 31:31]]); Исаия за столетия до события описал страдания Мессии — «Он изъязвлён был за грехи наши» ([[Ис 53:5]]).</p>
   <p>Исполнение пророчеств во Христе — одно из важнейших свидетельств истины веры: слишком многое было предсказано слишком точно, чтобы счесть это совпадением.</p>`, s:SRC.pis},
  {q:"Что такое Псалтирь?",
   a:`<p>Псалтирь — ветхозаветная книга из 150 псалмов, священных песней, большая часть которых надписана именем царя Давида. Это молитвенник, вобравший весь строй отношений человека с Богом: покаяние, славословие, благодарение, вопль из глубины скорби, упование и пророчество.</p>
   <p>Именно поэтому Псалтирь чаще всех других книг употребляется в церковном богослужении и в домашней молитве: в ней всякая душа находит слова для своего состояния. Отцы называли её «малой Библией», кратко вмещающей всё Писание.</p>
   <p>Многие псалмы прямо указывают на Христа: о Его крестном вопле — «Боже Мой, Боже Мой! для чего Ты Меня оставил?» ([[Пс 21:2]]), о Его вечном царстве и священстве ([[Пс 109:1]]).</p>`, s:SRC.pis},
  {q:"Что такое Септуагинта и почему она важна?",
   a:`<p>Септуагинта — древнейший перевод Ветхого Завета с еврейского на греческий язык, сделанный в Александрии в III–II веках до Рождества Христова. Название (лат. «семьдесят») связано с преданием о семидесяти (точнее, семидесяти двух) переводчиках.</p>
   <p>Её значение для Церкви велико по двум причинам. Во-первых, именно этим переводом пользовались апостолы и грекоязычная ранняя Церковь: большинство ветхозаветных цитат в Новом Завете приведены по Септуагинте. Во-вторых, её текст в ряде мест яснее указывает на Христа. Церковь принимает Септуагинту как авторитетный текст Ветхого Завета, и её объём лёг в основу православного канона.</p>`, s:SRC.pis},
  {q:"Как правильно толковать Писание?",
   a:`<p>Писание должно толковаться в согласии с верой и Преданием Церкви, а не по частному произволу, ибо «никакого пророчества в Писании нельзя разрешить самому собою» ([[2 Пет 1:20]]). Церковь, в которой Писание родилось и которой оно вручено, и есть его верная истолковательница.</p>
   <p>Отеческие правила толкования таковы: тёмные, неясные места изъясняются ясными; всякое отдельное место понимается в согласии со всем Писанием и с полнотой веры; всё читается в свете Христа, к Которому ведёт весь текст. Толкование не должно противоречить согласному учению отцов и определениям Вселенских соборов.</p>
   <p>Такой соборный, церковный подход оберегает от двух крайностей — от сухого буквализма, теряющего дух, и от произвольного вымысла, вычитывающего в тексте что угодно.</p>`, s:SRC.dog},
  {q:"Есть ли в Писании разные смыслы?",
   a:`<p>Да. Отцы различали прежде всего <em>буквальный</em> (исторический) смысл — то, о чём прямо повествует текст, — и <em>духовный</em> смысл, надстроенный над ним. Духовный смысл бывает прообразовательным (когда событие или лицо указывает на новозаветную реальность), нравственным (урок для души) и таинственным (указание на будущий век).</p>
   <p>Так, апостол Павел видит в переходе Израиля через Чермное море прообраз крещения ([[1 Кор 10:2]]); Сам Господь усматривает в медном змии, вознесённом Моисеем в пустыне, образ Своего распятия ([[Ин 3:14]]). При этом духовное толкование не отменяет и не подменяет буквального, а вырастает из него; оторванное же от буквального смысла и от веры Церкви, оно вырождается в произвол.</p>`, s:SRC.dog},
  {q:"Не противоречит ли Библия сама себе?",
   a:`<p>Мнимые противоречия обычно снимаются, если учитывать жанр, цель, адресата и обстоятельства книги, а также образный язык древности. Евангелисты, например, описывают одни события с разных сторон и с разной подробностью — как несколько честных свидетелей одного происшествия; их несовпадения в частностях скорее подтверждают независимость и подлинность свидетельства, чем опровергают его.</p>
   <p>Кроме того, Писание не есть учебник естествознания и говорит о сотворении и мире языком, доступным своему времени и служащим цели спасения, а не научному описанию. В главном же — в вести о Боге, о грехе и о спасении — оно едино и согласно, ибо имеет единого Автора, Духа Святого, действовавшего через многих людей на протяжении веков.</p>`, s:SRC.dog},
  {q:"Достаточно ли одного Писания без Церкви?",
   a:`<p>Писание рождено внутри Церкви, ею собрано в канон и ею же верно истолковывается; Писание и Предание неразделимы, как две стороны единого слова Божия. Само Писание сначала жило как устная апостольская проповедь и лишь затем было записано; Церковь древнее новозаветного текста и есть его родина.</p>
   <p>Отделённое от Церкви и её соборного разума, Писание становится предметом произвольных и взаимно противоречивых толкований — что наглядно показала история множества разделений, ссылающихся на одну и ту же Библию. Апостол велит держаться «преданий, которым вы научены или словом, или посланием нашим» ([[2 Фес 2:15]]), а саму Церковь называет «столпом и утверждением истины» ([[1 Тим 3:15]]). Поэтому Писание читается в Церкви и по вере Церкви.</p>`, s:SRC.dog}
 ]
},

/* ==================== 3. УЧЕНИЕ О БОГЕ (БОГОПОЗНАНИЕ) ==================== */
{
 id:"o-boge", title:"Учение о Боге",
 sub:"Богопознание, существо и свойства Божии",
 qa:[
  {q:"Кто есть Бог?",
   a:`<p>Бог есть вечный, всесовершенный и всеблаженный Дух, Творец и Промыслитель мира, единый по существу и троичный в Лицах — Отец, Сын и Святой Дух. Он — источник и полнота бытия, блага, жизни и любви, не имеющий ни начала, ни причины Своего существования.</p>
   <p>Догматическое богословие начинает с того, что Бог самобытен: Он существует Сам по Себе, тогда как всё прочее получает бытие от Него. На вопрос Моисея об имени Бог ответил: «Я есмь Сущий» ([[Исх 3:14]]) — то есть Тот, Кто есть в полном и безусловном смысле и даёт бытие всему остальному.</p>
   <p>В отличие от языческих богов — олицетворённых стихий и страстей — Бог Писания не часть мира, а его свободная Первопричина. А самое сокровенное о Нём открыл Новый Завет: «Бог есть любовь» ([[1 Ин 4:8]]).</p>`, s:SRC.dog},
  {q:"Можно ли постичь Бога разумом до конца?",
   a:`<p>Нет. Существо Божие непостижимо и превосходит всякое тварное разумение: «Бога не видел никто никогда» ([[Ин 1:18]]); Он «обитает в неприступном свете, Которого никто из человеков не видел и видеть не может» ([[1 Тим 6:16]]). Постигнуть Бога вполне значило бы стать выше и больше Бога, что невозможно для твари.</p>
   <p>Поэтому отцы различали два пути богословия. <em>Апофатический</em> (отрицательный) говорит о Боге, что́ Он <em>не есть</em>: не ограничен, не сложен, не изменяем, невеществен, — ограждая тайну от наших грубых понятий. <em>Катафатический</em> (положительный) говорит, что́ можно утверждать о Боге по Его действиям: благ, премудр, всемогущ.</p>
   <p>Итог: мы познаём Бога не по недоступному Его существу, а по Его действиям (энергиям) и свойствам, как они открыты в творении и в Откровении, — знание истинное, хотя и не исчерпывающее.</p>`, s:SRC.dog},
  {q:"Как человек познаёт Бога?",
   a:`<p>Двумя путями, которые дополняют друг друга. <em>Естественное</em> откровение — свидетельство о Творце в устройстве и красоте мира и в голосе совести: «невидимое Его… через рассматривание творений видимо» ([[Рим 1:20]]). Оно доступно всем народам, но даёт лишь общее знание о бытии, силе и премудрости Творца, не открывая тайн спасения.</p>
   <p><em>Сверхъестественное</em> откровение — то, что Сам Бог возвестил через избранных: патриархов, Моисея, пророков, — и, наконец, полнее всего через воплотившегося Сына. «Бог, многократно и многообразно говоривший издревле отцам в пророках, в последние дни сии говорил нам в Сыне» ([[Евр 1:1]]).</p>
   <p>Полнота богопознания дана во Христе и усваивается в жизни Церкви — в вере, таинствах и молитве, а не одним отвлечённым размышлением. «Видевший Меня видел Отца» ([[Ин 14:9]]).</p>`, s:SRC.dog},
  {q:"Что такое свойства Божии?",
   a:`<p>Свойства — это то, что открывает нам совершенства Божественного существа, насколько они доступны нашему разумению и выразимы на нашем языке. Их обычно делят на две группы. Одни показывают независимость Бога от условий тварного бытия: самобытность, вечность, неизменяемость, вездесущие, — Бог не подчинён ни времени, ни пространству, ни изменению.</p>
   <p>Другие относятся к Богу как к совершенному Уму и Воле: всеведение, премудрость, всемогущество, святость, правда, благость. Через них Бог являет Себя как живую Личность, а не безличную силу.</p>
   <p>При этом Бог прост и не состоит из частей или свойств: свойства не «складываются» в Нём, как качества в вещи. Каждое из них есть Сам Бог, рассматриваемый с определённой стороны; Бог не «имеет» благость — Он <em>есть</em> Благость.</p>`, s:SRC.dog},
  {q:"Что значит, что Бог — Дух?",
   a:`<p>Это значит, что Бог невеществен, невидим, бестелесен и прост, не связан ни формой, ни местом, ни составом. Сам Господь сказал: «Бог есть дух, и поклоняющиеся Ему должны поклоняться в духе и истине» ([[Ин 4:24]]); Писание называет Его «Богом невидимым» ([[Кол 1:15]]).</p>
   <p>Телесные образы Библии — «рука», «око», «уста», «гнев» Божий — не следует понимать буквально; это <em>антропоморфизмы</em>, снисхождение к нашему языку, выражающие действия и отношения Бога понятным нам образом. Говоря о «руке» Божией, Писание разумеет Его силу, о «оке» — Его всеведение.</p>
   <p>Как чистый Дух, Бог не ограничен ничем вещественным и присутствует везде всецело.</p>`, s:SRC.dog},
  {q:"Что значит вечность Божия?",
   a:`<p>Вечность означает, что Бог не имеет ни начала, ни конца и вообще не подчинён времени. Само время сотворено вместе с изменчивым миром, а Бог пребывает выше него: «прежде нежели родились горы, и Ты образовал землю и вселенную, и от века и до века Ты — Бог» ([[Пс 89:3]]).</p>
   <p>Для Бога нет «прежде» и «после» в нашем смысле последовательности: Он всё содержит в едином, неизменном, присносущном «ныне». Отсюда Его имя: «Я есмь Альфа и Омега, начало и конец… Который есть и был и грядёт, Вседержитель» ([[Откр 1:8]]).</p>`, s:SRC.dog},
  {q:"Что значит неизменяемость Божия?",
   a:`<p>Бог всесовершен, а потому не может изменяться: улучшение предполагало бы прежнее несовершенство, а ухудшение — утрату совершенства; и то и другое несовместимо с полнотой Божества. «Я — Господь, Я не изменяюсь» ([[Мал 3:6]]); у Него «нет изменения и ни тени перемены» ([[Иак 1:17]]).</p>
   <p>Когда же Писание говорит, что Бог «раскаялся» или «умилостивился», это описывает не перемену в Боге, а перемену в отношениях, происходящую от перемены самих людей: неизменный Бог по-разному относится к грешнику и к покаявшемуся, оставаясь при этом одним и тем же. Неизменны и Его существо, и Его благой замысел о мире.</p>`, s:SRC.dog},
  {q:"Что такое вездесущие Божие?",
   a:`<p>Вездесущие означает, что Бог не ограничен пространством и присутствует везде — не частями, а всем Своим существом. «Куда пойду от Духа Твоего, и от лица Твоего куда убегу? Взойду ли на небо — Ты там; сойду ли в преисподнюю — и там Ты» ([[Пс 138:7]]); Он наполняет небо и землю ([[Иер 23:24]]).</p>
   <p>При этом Бог присутствует в мире, не сливаясь с ним и не растворяясь в нём, — этим вера отличается от пантеизма: мир пребывает в Боге, но Бог бесконечно больше мира. Кроме этого вездесущия по существу, Бог являет особое, благодатное присутствие — в храме, в таинствах, в сердцах святых.</p>`, s:SRC.dog},
  {q:"Что такое всеведение Божие?",
   a:`<p>Всеведение — совершенное знание Богом всего: прошедшего, настоящего и будущего, действительного и лишь возможного, явного и самого сокровенного, вплоть до тайных помышлений сердца. «Всё обнажено и открыто перед очами Его» ([[Евр 4:13]]); «Господь испытует все сердца и знает все движения мыслей» ([[1 Пар 28:9]]).</p>
   <p>Знание Божие не приобретается постепенно, не есть вывод или догадка: Бог знает всё сразу, вечно и совершенно. Это ведение — основание и Его правды (Он судит по истине, а не по видимости) и Его Промысла (Он всё предусматривает и направляет ко благу).</p>`, s:SRC.dog},
  {q:"Что такое всемогущество Божие?",
   a:`<p>Всемогущество означает, что Бог может совершить всё, что хочет и что согласно с Его совершенством: «Богу всё возможно» ([[Мф 19:26]]); «Он сказал — и сделалось; Он повелел — и явилось» ([[Пс 32:9]]).</p>
   <p>Но всемогущество не есть способность к бессмыслице или ко злу. Бог не может лгать ([[Тит 1:2]]), не может отречься Себя ([[2 Тим 2:13]]), не может сотворить логическое противоречие (например, «квадратный круг»). Это не ограничение силы, а её совершенство: ложь, зло и противоречие суть не проявления мощи, а недостаток и распад бытия.</p>
   <p>Иными словами, всемогущество — это полнота власти <em>благой</em> и разумной воли, а не произвол, способный на что угодно, включая нелепость.</p>`, s:SRC.dog},
  {q:"Что такое премудрость Божия?",
   a:`<p>Премудрость — совершенство Божественного разума, которым Бог знает наилучшие цели и наилучшие пути к ним и устрояет всё сообразно с ними. Она явлена уже в устройстве творения: «Как многочисленны дела Твои, Господи! Всё соделал Ты премудро» ([[Пс 103:24]]).</p>
   <p>Высшее же откровение премудрости — в деле спасения через Крест, который для внешнего взгляда кажется бессилием и безумием, а на деле есть «Божия сила и Божия премудрость» ([[1 Кор 1:24]]), победившая зло не силой, а любовью. Премудрость Божия часто превосходит наш расчёт, и вера доверяет ей там, где не видит её путей: «непостижимы судьбы Его» ([[Рим 11:33]]).</p>`, s:SRC.dog},
  {q:"Что такое святость Божия?",
   a:`<p>Святость — совершенная чистота и превознесённость Бога, Его полная непричастность злу и совершенство блага. Это одно из самых глубоких свойств: серафимы непрестанно взывают пред престолом Божиим: «Свят, Свят, Свят Господь Саваоф! вся земля полна славы Его» ([[Ис 6:3]]).</p>
   <p>Святость означает не только нравственную чистоту, но и «отделённость», недосягаемую возвышенность Бога над всем тварным, так что приближение к Святому требует благоговения и очищения. И эта же святость есть образец и призвание для человека: «будьте святы, потому что Я свят» ([[1 Пет 1:16]]).</p>`, s:SRC.dog},
  {q:"Что такое благость и любовь Божия?",
   a:`<p>Благость — это любовь Бога, по которой Он изливает на творение бытие и всякое благо, не имея в том никакой нужды и не ожидая корысти. Из благости Бог сотворил мир, из благости промышляет о нём и спасает падшего человека.</p>
   <p>«Бог есть любовь» ([[1 Ин 4:8]]); Он «благ ко всем, и щедроты Его на всех делах Его» ([[Пс 144:9]]), «повелевает солнцу Своему восходить над злыми и добрыми» ([[Мф 5:45]]) — то есть благ даже к неблагодарным.</p>
   <p>Высшее и окончательное выражение благости — что Бог «Сына Своего единородного отдал, дабы всякий верующий в Него не погиб, но имел жизнь вечную» ([[Ин 3:16]]). Любовь Божия открылась не в словах только, а в Кресте.</p>`, s:SRC.dog},
  {q:"Что такое правда (правосудие) Божие?",
   a:`<p>Правда Божия — совершенная справедливость, по которой Бог требует от разумных существ добра, воздаёт каждому по делам его и хранит нравственный порядок мира. «Праведен Господь во всех путях Своих» ([[Пс 144:17]]); «Он воздаст каждому по делам его» ([[Рим 2:6]]).</p>
   <p>Правда не противоречит благости — обе соединяются в деле спасения, где Бог одновременно и грех осуждает (правда), и грешника милует (любовь), приняв на Себя во Христе последствия греха. Долготерпение Божие даёт время на покаяние ([[2 Пет 3:9]]), но не отменяет суда: «нельзя издеваться над Богом» ([[Гал 6:7]]).</p>`, s:SRC.dog},
  {q:"Как согласуются свобода человека и всеведение Бога?",
   a:`<p>Бог от вечности предвидит все свободные поступки людей, но предвидение не есть принуждение. Знать заранее, как человек свободно поступит, — не то же самое, что заставить его так поступить: знание не является причиной события, а лишь его верным отражением.</p>
   <p>Как очевидец, наблюдающий за поступком, не отнимает у действующего свободы, так и всеведение Божие, объемлющее и наш свободный выбор, оставляет его подлинно свободным. Более того, для вечного Бога наш «завтрашний» выбор не «ещё не сделан» — Он видит его в Своём вечном «ныне», не предопределяя.</p>
   <p>Поэтому человек несёт полную ответственность за свои дела, а Бог праведно судит их.</p>`, s:SRC.dog},
  {q:"Почему Бог именуется Творцом?",
   a:`<p>Творцом Бог именуется потому, что Он привёл весь мир — духовный и вещественный — из небытия в бытие одной Своей волей: не из готового вещества, не из Своего существа и не по внешней необходимости, а свободно, по благости. «В начале сотворил Бог небо и землю» ([[Быт 1:1]]); «всё чрез Него начало быть, и без Него ничто не начало быть, что начало быть» ([[Ин 1:3]]).</p>
   <p>Это учение о творении «из ничего» отличает библейскую веру и от языческих мифов о вечной, несотворённой материи, и от учений об истечении (эманации) мира из Бога, и от пантеизма. Мир не есть ни Бог, ни часть Бога, ни вечный совечник Бога, но Его свободное создание, всецело и в каждый миг от Него зависящее.</p>`, s:SRC.dog},
  {q:"Существует ли только один Бог?",
   a:`<p>Да, Бог един по существу — это первое и основное исповедание всего Откровения. «Слушай, Израиль: Господь, Бог наш, Господь един есть» ([[Втор 6:4]]) — эти слова были и остаются сердцем веры народа Божия; «нет иного Бога, кроме Единого» ([[1 Кор 8:4]]).</p>
   <p>Многобожие есть заблуждение, обожествляющее творение — стихии, светила, страсти — вместо Творца. Единство же Божие не противоречит троичности Лиц: Отец, Сын и Дух — не три бога, а единое, нераздельное Божественное существо в трёх Лицах. Об этом подробнее — в разделе о Святой Троице.</p>`, s:SRC.dog}
 ]
},

/* ============================ 4. ТРИАДОЛОГИЯ ============================ */
{
 id:"triadologiya", title:"Учение о Святой Троице",
 sub:"Триадология: три Лица единого Бога",
 qa:[
  {q:"Что значит, что Бог — Троица?",
   a:`<p>Христиане исповедуют единого Бога в трёх Лицах: Отец, Сын и Святой Дух. Это не три бога и не три имени или «маски» одного Лица, а единое, нераздельное Божественное существо, в котором три Лица (Ипостаси) действительно различны, но совершенно единосущны, равны и вечны.</p>
   <p>Троичность — не измышление богословов, а тайна, открытая Самим Богом в Новом Завете. Господь заповедал крестить «во имя Отца и Сына и Святаго Духа» ([[Мф 28:19]]) — заметим: во единое <em>имя</em> трёх Лиц. Апостол благословляет верующих: «благодать Господа нашего Иисуса Христа, и любовь Бога Отца, и общение Святаго Духа со всеми вами» ([[2 Кор 13:13]]).</p>
   <p>Учение о Троице — не отвлечённая арифметика, а исповедание того, что Сам Бог в Своей глубине есть общение любви трёх Лиц.</p>`, s:SRC.dog},
  {q:"Троица — это три Бога?",
   a:`<p>Нет. Лица Троицы единосущны — Они обладают одним и тем же, единым и неделимым Божественным существом, одной волей, одной силой и действием. Поэтому Бог один, а не три. Учение о трёх богах (тритеизм) Церковь решительно отвергает как язычество.</p>
   <p>Точная формула, выработанная отцами: троичность относится к <em>Лицам</em>, а единство — к <em>существу</em>; три «Кто» при одном «что». Три Лица не суть три отдельных «экземпляра» божества (как три человека суть три экземпляра человечества) и не делят Божество на части, но каждое всецело и нераздельно обладает единым Божеством.</p>`, s:SRC.dog},
  {q:"Чем различаются Лица Троицы?",
   a:`<p>Лица различаются не существом (оно у Них общее) и не Божественными свойствами (они у Них равны), а только <em>личными свойствами</em> — то есть образом бытия и вечными взаимными отношениями. Отец безначален: не рождён и ни от кого не происходит. Сын предвечно рождается от Отца. Дух Святой предвечно исходит от Отца.</p>
   <p>Эти отношения (нерождённость, рождение, исхождение) вечны, неизменны и не вносят в Бога ни разделения, ни «раньше» и «позже», ни степеней старшинства. Всё в Троице — общее у Трёх, кроме этих личных свойств. Так Церковь хранит одновременно и полное равенство Лиц, и их подлинное различие.</p>`, s:SRC.dog},
  {q:"Почему Сын Божий — истинный Бог?",
   a:`<p>Писание ясно усваивает Сыну всё Божественное. Он вечен и есть Творец всего: «В начале было Слово, и Слово было у Бога, и Слово было Бог… всё чрез Него начало быть» ([[Ин 1:1]]). Апостол Фома, осязав раны воскресшего Христа, исповедал Его: «Господь мой и Бог мой» ([[Ин 20:28]]), и Господь принял это исповедание.</p>
   <p>Сыну приписываются Божественные свойства и дела — прощение грехов, воскрешение мёртвых, суд над миром — и воздаётся Божеское поклонение, которое подобает одному Богу. Всё это было бы кощунством, не будь Он Богом.</p>
   <p>Отрицание Божества Сына (арианство) разрушило бы и самое спасение: спасти, исцелить и обожить человеческую природу мог только Бог, а не высшее творение.</p>`, s:SRC.dog},
  {q:"Что значит «рождение» Сына от Отца?",
   a:`<p>Рождение Сына — вечное, духовное и бесстрастное, а не во времени и не телесное, как у людей. Сын рождается от самого <em>существа</em> Отца, а не творится из ничего, — поэтому Он единосущен Отцу и так же вечен: не было такого «когда», чтобы Отец был без Сына, как не бывает солнца без сияния.</p>
   <p>Сын — «сияние славы и образ ипостаси» Отца ([[Евр 1:3]]). Отцы поясняли эту тайну подобиями: как свет неотделим от солнца и вечно им рождается, как мысль рождается умом, — но тут же оговаривались, что всякое подобие несовершенно и лишь отчасти приоткрывает непостижимое.</p>`, s:SRC.dog},
  {q:"Почему Святой Дух — Бог?",
   a:`<p>Святому Духу Писание также усваивает Божественное. Апостол называет верующих храмом Божиим, «ибо Дух Божий живёт в вас» ([[1 Кор 3:16]]), — значит, Дух есть Бог, ибо Его храм есть храм Божий. Апостол Пётр говорит солгавшему Духу Святому: «ты солгал не человекам, а Богу» ([[Деян 5:4]]) — прямо отождествляя Духа и Бога.</p>
   <p>Слова, сказанные, по пророку Исаии, Самим Господом ([[Ис 6:9]]), апостол Павел приписывает Духу Святому ([[Деян 28:25]]) — то есть Дух есть тот же Господь. Дух животворит, освящает, наставляет на всякую истину, раздаёт дары «как Ему угодно» — совершает дела, свойственные одному Богу, и действует как Личность, а не безличная сила.</p>`, s:SRC.dog},
  {q:"От кого исходит Святой Дух и что такое filioque?",
   a:`<p>По прямому слову Самого Господа, Дух истины «от Отца исходит» ([[Ин 15:26]]). Поэтому Православная Церковь исповедует исхождение Святого Духа от Отца, как это навсегда закреплено в Никео-Цареградском Символе веры.</p>
   <p>Позднее на Западе в Символ была внесена прибавка «и от Сына» (лат. <em>filioque</em>). Восточная Церковь не приняла её по двум причинам. Во-первых, Символ веры установлен Вселенскими соборами, и никакая поместная Церковь не вправе в одностороннем порядке изменять его. Во-вторых, по существу: единственным началом (источником) в Троице является Отец, и учение об исхождении Духа «и от Сына» затемняет это единоначалие.</p>
   <p>Спор о filioque стал одной из главных причин разделения Церквей 1054 года.</p>`, s:SRC.dog+" · "+SRC.ist},
  {q:"Что означает слово «единосущный»?",
   a:`<p>«Единосущный» (греч. <em>homoousios</em>) означает, что Сын — <em>того же самого</em> Божественного существа, что и Отец, а не только подобен Ему или причастен низшему божеству. Одним этим словом отсекается всякая мысль, будто Сын — иное, отдельное, низшее или сотворённое существо.</p>
   <p>Слово внесли отцы Первого Вселенского собора в Никее (325 г.), чтобы точно оградить веру от учения Ария, который был готов называть Сына «подобным» Отцу, но не «единосущным». История показала мудрость этого выбора: именно на слове «единосущный» вера устояла.</p>
   <p>Хотя самого этого слова нет в Библии, оно верно и незаменимо выражает библейскую истину — и служит примером того, как Церковь на соборе даёт точные определения там, где ересь искажает Писание.</p>`, s:SRC.ist},
  {q:"Кто такой Арий и в чём его заблуждение?",
   a:`<p>Арий — александрийский пресвитер начала IV века. Он учил, что Сын не вечен и не единосущен Отцу, а есть первое и высшее творение, через которое Бог создал прочий мир; отсюда его формула: «было (время), когда Его не было». Тем самым Арий, сохраняя имя «Сын Божий», по сути отвергал истинное Божество Христа.</p>
   <p>Против него встал святитель Афанасий Александрийский. Первый Вселенский собор (325 г.) осудил арианство и исповедал Сына «рождённым, несотворённым, единосущным Отцу». Однако спор на этом не кончился: арианство, поддержанное и частью власти, волновало Церковь ещё несколько десятилетий, и понадобились труды многих отцов, чтобы никейская вера утвердилась окончательно.</p>`, s:SRC.ist},
  {q:"Кто такие Каппадокийские отцы?",
   a:`<p>Так называют трёх великих богословов второй половины IV века — святителей Василия Великого, Григория Богослова и Григория Нисского (первые двое — из Каппадокии, области в Малой Азии). Они завершили выработку точного языка троичного богословия.</p>
   <p>Их заслуга — ясно различить понятия: одно <em>существо</em> (греч. усия) и три <em>Лица</em> (ипостаси). Эта формула позволила исповедать и единство Бога, и подлинное различие Лиц, не впадая ни в тритеизм, ни в слияние Лиц. Их трудами Второй Вселенский собор (381 г.) утвердил и Божество Святого Духа против духоборцев.</p>
   <p>Святителя Григория за глубину и высоту его богословия Церковь именует Богословом — имя, которое она дала лишь троим.</p>`, s:SRC.ist},
  {q:"Проявляется ли Троица в Ветхом Завете?",
   a:`<p>Прикровенно — да, хотя ясное и полное откровение о Троице дано лишь в Новом Завете. Отцы видели предуказания на неё в словах Бога «сотворим человека по образу Нашему» ([[Быт 1:26]]) — не «сотворю», а «сотворим»; в троекратном серафимском «Свят, Свят, Свят» ([[Ис 6:3]]); в явлении Аврааму трёх мужей у дуба Мамврийского ([[Быт 18:2]]), которых он встречает поклонением.</p>
   <p>Почему же не яснее? Догматическое богословие объясняет: Ветхий Завет прежде всего утверждал единобожие среди окружающего язычества, и открытая проповедь троичности могла быть понята народом как многобожие. Поэтому тайна открывалась постепенно и в полноте возвещена, когда пришёл Сын и был послан Дух.</p>`, s:SRC.dog},
  {q:"Как понять тайну Троицы?",
   a:`<p>Тайна Троицы превосходит тварный разум и не может быть исчерпана никаким образом или сравнением. Отеческие подобия — солнце, луч и тепло; корень, ствол и плод; ум, слово и дух в одном человеке — каждое чем-то помогает, но каждое в чём-то неточно (одни клонят к слиянию Лиц, другие — к разделению).</p>
   <p>Поэтому Троица не столько постигается, сколько исповедуется верой и созерцается в молитве, в богослужении и в жизни Церкви. Она — не «задача для ума», а тайна общения любви, в которое призван войти человек.</p>
   <p>Само назначение человека выражено в молитве Христа к Отцу: «да будут все едино, как Ты, Отче, во Мне, и Я в Тебе, так и они да будут в Нас едино» ([[Ин 17:21]]).</p>`, s:SRC.dog},
  {q:"Что означают слова «нерождённость», «рождённость» и «исхождение»?",
   a:`<p>Это <em>личные</em> (ипостасные) свойства Лиц Пресвятой Троицы — то единственное, чем Лица различаются между Собою. Всё остальное — существо, сила, воля, слава — у Них одно и то же. Святитель Григорий Богослов выразил это так: всё, что имеет Отец, имеет и Сын, кроме нерождённости; и всё, что имеет Сын, принадлежит Духу, кроме рождённости.</p>
<p>Отсюда точные наименования: собственное Отцу — <em>нерождённость</em> (греч. ἀγεννησία), собственное Сыну — <em>рождённость</em> (γέννησις), собственное Духу — <em>исхождение</em> (ἐκπόρευσις). Эти три слова не описывают трёх разных сущностей и не вводят степеней достоинства: они лишь указывают образ бытия каждого Лица по отношению к другим.</p>
<p>Важно, что различие здесь именно личное, а не природное. Поэтому Церковь исповедует Троицу единосущную и нераздельную: три Лица различаются только тем, как Они друг от друга, и ничем более.</p>`, s:SRC.dog+" · §67"},
  {q:"Почему только Отец называется «безначальным» и «безвиновным»?",
   a:`<p>Отцы Церкви прилагали к Отцу слова ἄναρχος (безначальный) и ἀναίτιος (безвиновный), потому что Отец ни от кого не получил бытия и Сам есть верховное начало (ἀρχή) в Троице. Сын рождается от Отца, Дух исходит от Отца — Отец же не от кого.</p>
<p>Святитель Василий Великий поясняет это через противопоставление: Сын не безначален, безначален Отец. Тем же различением пользовались Афанасий Великий, Григорий Богослов (называвший Отца ἀναίτιος), Ефрем Сирин, Кирилл Александрийский, Иоанн Дамаскин, Григорий Нисский.</p>
<p>Здесь важно не ошибиться. «Начало» и «вина» означают не то, что Отец древнее или выше по достоинству — в Троице нет ни прежде, ни после, ни большего, ни меньшего. Речь только об образе бытия: Сын и Дух вечно имеют бытие от Отца, и вечно — то есть никогда не было, чтобы Их не было ([[Ин 1:1]]).</p>`, s:SRC.dog+" · §67"},
  {q:"Можно ли исследовать, как именно рождается Сын и исходит Дух?",
   a:`<p>Нет — и отцы Церкви предупреждали об этом настойчиво. Василий Великий, Григорий Богослов и блаженный Августин прямо советовали не любопытствовать об образе рождения Сына и исхождения Духа Святого.</p>
<p>Августин выразил это почти как правило ума: знай, что Он рождён; ты не знаешь, каким образом Он рождён; и вот именно это — не суметь узнать образ — и есть здесь подлинное знание. Иными словами, признание границы собственного разума в данном случае не поражение мысли, а её честность.</p>
<p>Причина проста: рождение и исхождение суть образы вечного бытия Божия, а всякое наше представление о рождении и происхождении взято из мира временного и телесного. Перенося его на Бога, мы неизбежно исказим то, что хотим объяснить. Поэтому Церковь удерживает сами слова Откровения ([[Ин 1:14]]; [[Ин 15:26]]), не пытаясь их «расшифровать».</p>`, s:SRC.dog+" · §67"},
  {q:"Почему Дух именуется «собственным Сыну», если исходит от Отца?",
   a:`<p>Это выражение стало предметом важного спора V века. Святитель Кирилл Александрийский в своих анафематизмах против Нестория назвал Святого Духа «собственным» Сыну (ἴδιον). Блаженный Феодорит возразил: если разуметь, что Дух единосущен Сыну и исходит от Отца — мы согласны и признаём это православным; если же разуметь, будто Дух получил бытие от Сына или через Сына — это отвергаем как богохульство, ибо веруем Господу, сказавшему: «Дух истины, Иже от Отца исходит» ([[Ин 15:26]]).</p>
<p>Кирилл объяснил себя именно в первом смысле: Дух Святой, по слову Спасителя, происходит от Бога Отца, но не чужд Сыну, ибо Он есть Дух Христа так же, как и Дух Отца ([[Рим 8:9]]).</p>
<p>Итоговая формулировка, принятая при примирении сторон, звучит так: в послании Кирилла проповедуется Дух Святой, имеющий бытие <em>не из Сына и не через Сына</em> (οὐκ ἐκ τοῦ Υἱοῦ ἢ δι᾽ Υἱοῦ), но исходящий от Отца и собственный Сыну. Таким образом, «собственный Сыну» говорит о единосущии и нераздельности, а не об источнике бытия.</p>`, s:SRC.dog+" · §68"},
  {q:"Можно ли изменить хотя бы одно слово в Символе веры?",
   a:`<p>Церковь ответила на это ещё до того, как вопрос стал предметом разделения. Святитель Кирилл Александрийский в письме к Иоанну Антиохийскому писал: мы не позволяем ни себе, ни кому-либо другому изменить даже одно речение в Символе веры или опустить хотя бы один слог, — ибо изрекали его не они (отцы собора), но Сам Дух Бога и Отца.</p>
<p>Основание такой строгости не в обрядовом буквализме. Символ есть краткое исповедание того, во что Церковь крестит; изменение его слов означает изменение самого исповедания, которое даётся каждому крещаемому.</p>
<p>Именно поэтому позднейшая вставка «и от Сына» (filioque), сделанная на Западе без согласия всей Церкви, воспринята на Востоке не как частная богословская тонкость, а как нарушение общего для всех правила. Спор шёл не только о содержании, но и о самом праве одной части Церкви менять то, что принято Вселенскими соборами.</p>`, s:SRC.dog+" · §68"}
 ]
},

/* ==================== 5. КОСМОЛОГИЯ И АНГЕЛОЛОГИЯ ==================== */
{
 id:"kosmologiya", title:"Творение, ангелы и Промысл",
 sub:"Космология, ангелология, учение о Промысле",
 qa:[
  {q:"Сотворил ли Бог мир из ничего?",
   a:`<p>Да. Мир не вечен, не самобытен и не возник сам собою: «В начале сотворил Бог небо и землю» ([[Быт 1:1]]). Словами «небо и земля» Писание охватывает весь состав созданного — и мир духовный (ангельский), и вещественный.</p>
   <p>Бог творит не из готового вещества, не из Своего существа и не по необходимости, а свободной волей приводит бытие из небытия одним Своим словом: «Он сказал — и сделалось; Он повелел — и явилось» ([[Пс 32:9]]). Это учение (лат. <em>creatio ex nihilo</em>, творение «из ничего») — граница, отделяющая веру и от языческих мифов о вечной материи, и от пантеизма, растворяющего мир в Боге.</p>
   <p>Следствие важно: раз мир сотворён и всецело зависит от Бога, он не божественен (нельзя обожествлять природу), но и не зол (всё сотворённое «хорошо весьма» — [[Быт 1:31]]).</p>`, s:SRC.dog},
  {q:"Зачем Бог сотворил мир?",
   a:`<p>Не по нужде и не для восполнения чего-то в Себе, ибо Бог всесовершен, всеблажен и самодостаточен и до творения. Мир сотворён по одной благости — чтобы даром разделить бытие и блаженство с творением, вызвать к жизни существа, способные познавать Бога, любить Его и участвовать в Его благе.</p>
   <p>Поэтому конечная цель мира двойственна и едина: слава Божия, являемая в творении, и блаженство разумных существ в общении с Богом. «Достоин Ты, Господи, приять славу и честь и силу: ибо Ты сотворил всё, и всё по Твоей воле существует и сотворено» ([[Откр 4:11]]).</p>`, s:SRC.dog},
  {q:"Что означают «шесть дней» творения?",
   a:`<p>Шестоднев ([[Быт 1:1]]) изображает разумный, восходящий порядок творения — от простого к сложному, от неодушевлённого к живому и до человека как венца. Главное, что он утверждает: мир создан не случайно и не хаотично, а единым Богом, по премудрому замыслу и в стройном порядке.</p>
   <p>«Дни» отцы толковали по-разному: одни — как обычные сутки, другие (например, блаженный Августин) — как ступени творения, не сводимые прямо к нашему счёту времени, тем более что солнце, мерило суток, по повествованию явилось не в первый день. Церковь не связывает веру с одним толкованием их длительности.</p>
   <p>Незыблемо же в шестодневе то, что Творец всего — Бог, что мир произошёл по Его слову, и что человек создан Им особо, как венец и владыка видимого мира.</p>`, s:SRC.dog},
  {q:"Совместима ли вера с научными данными о возрасте мира?",
   a:`<p>Да. Писание учит не тому, «как» и «когда» в естественнонаучном смысле возник мир, а тому, <em>Кто</em> и <em>зачем</em> его сотворил. Оно говорит о творении образным языком, доступным древнему читателю и служащим цели спасения, и не является учебником физики, геологии или биологии.</p>
   <p>Поэтому научные данные о возрасте вселенной и о развитии жизни сами по себе не противоречат вере в Бога-Творца. Верующий видит в естественных законах и процессах <em>способ</em>, которым осуществляется Божий замысел; наука описывает механизм, вера открывает Причину и смысл. Спор возникает лишь там, где науку или Писание вынуждают отвечать на чужие им вопросы.</p>
   <p>Незыблемым для веры остаётся немногое, но главное: мир не самобытен, а сотворён Богом, и человек — не случайность, а особое Его создание, носящее образ Божий.</p>`, s:SRC.dog},
  {q:"Кто такие ангелы?",
   a:`<p>Ангелы — сотворённый Богом мир чистых, бесплотных, разумных и свободных духов, превосходящих человека силою и ведением, но, как и всё, получивших бытие от Творца. Они не самобытны и не вечны по природе: Бог создал «всё… видимое и невидимое» ([[Кол 1:16]]), и «невидимое» — это прежде всего ангельский мир.</p>
   <p>Само слово «ангел» значит «вестник» и указывает не столько на природу, сколько на служение: возвещать волю Божию. Ангелы сотворены прежде вещественного мира и с самого начала предназначены к славословию Бога и к участию в Его Промысле о творении.</p>`, s:SRC.dog},
  {q:"Каково служение ангелов?",
   a:`<p>Ангелы непрестанно предстоят Богу, славословят Его и мгновенно исполняют Его волю, а также посылаются на служение людям ради их спасения. Апостол прямо спрашивает: «не все ли они суть служебные духи, посылаемые на служение для тех, которые имеют наследовать спасение?» ([[Евр 1:14]]).</p>
   <p>В священной истории они возвещали волю Божию (Гавриил — Деве Марии), служили Христу, укрепляли апостолов, изводили из темниц. По слову Господа, каждому верующему дан ангел-хранитель: «Ангелы их на небесах всегда видят лице Отца Моего Небесного» ([[Мф 18:10]]). Ангелы — не «умершие люди», а особый, изначально духовный чин творения.</p>`, s:SRC.dog},
  {q:"Есть ли у ангелов чины?",
   a:`<p>Да, ангельский мир не однороден, а стройно иерархичен. Писание называет разные чины: херувимов и серафимов ([[Ис 6:2]]), престолы, господства, начала, власти, силы, а также архангелов и ангелов ([[Кол 1:16]]).</p>
   <p>Церковное Предание, следуя творению святого Дионисия Ареопагита «О небесной иерархии», различает девять ангельских чинов, объединённых в три степени (иерархии). Эта стройность — образ порядка и в самом Царстве Божием. Из архангелов Писание называет по имени Михаила ([[Иуд 1:9]]), поборника народа Божия, и Гавриила ([[Лк 1:26]]), вестника воплощения.</p>`, s:SRC.pred},
  {q:"Откуда произошли злые духи?",
   a:`<p>Диавол и бесы — не изначальное зло и не «второе божество», противостоящее Богу: такое учение (дуализм) Церковь отвергает. Они сотворены Богом добрыми ангелами, но добровольно отпали от Него по гордости и злоупотреблению свободой. Зло не имеет собственной природы и не сотворено Богом; оно есть повреждение и извращение доброго.</p>
   <p>Господь сказал: «Я видел сатану, спадшего с неба, как молнию» ([[Лк 10:18]]); апостол пишет об ангелах, которые «не сохранили своего достоинства, но оставили своё жилище» ([[Иуд 1:6]]). Падшие духи ожесточились во зле окончательно и стали врагами Бога и людей, но их сила ограничена и подвластна Богу.</p>`, s:SRC.dog},
  {q:"Может ли диавол принудить человека ко греху?",
   a:`<p>Нет. Власть диавола ограничена: он может искушать, соблазнять, внушать помыслы, устрашать, но не может принудить свободную волю человека без его собственного согласия. Грех совершается лишь тогда, когда человек сам склоняется на искушение и принимает его.</p>
   <p>Поэтому Писание призывает не к страху, а к трезвению и сопротивлению: «Противостаньте диаволу, и убежит от вас» ([[Иак 4:7]]); «облекитесь во всеоружие Божие, чтобы вам можно было стать против козней диавольских» ([[Еф 6:11]]). Оружие против искушений — вера, молитва, смирение, крестное знамение и благодать таинств; ими немощный человек становится сильнее падших духов.</p>`, s:SRC.dog},
  {q:"Что такое Промысл Божий?",
   a:`<p>Промысл — это непрестанное действие Божие, которым Бог сохраняет бытие мира, содействует всему доброму и премудро направляет всё ко благой цели. Бог не сотворил мир, чтобы затем оставить его на произвол (как учили деисты): «Отец Мой доныне делает, и Я делаю» ([[Ин 5:17]]).</p>
   <p>Промысл объемлет и великое, и самое малое: без воли Отца «и волос с головы не упадёт» ([[Лк 21:18]]), и малая птица не забыта у Бога ([[Мф 10:29]]). Богословие различает в Промысле <em>сохранение</em> (Бог поддерживает бытие и силы творения) и <em>управление</em> (Бог ведёт мир и историю к их цели).</p>`, s:SRC.dog},
  {q:"Не отменяет ли Промысл свободу человека?",
   a:`<p>Нет. Промысл действует, не насилуя свободы разумных существ. По отношению к добру Бог содействует ему; по отношению ко злу — попускает его (не производя), но так, что и злое обращает ко благим последствиям, не снимая с человека ответственности за его выбор.</p>
   <p>Ярчайший пример — история Иосифа, проданного братьями в рабство: он говорит им впоследствии: «вы умышляли против меня зло; но Бог обратил это в добро» ([[Быт 50:20]]). Так свободная воля человека и премудрый Промысл Божий соединяются, не упраздняя друг друга: человек свободно делает выбор, а Бог свободно вплетает его в Свой благой замысел.</p>`, s:SRC.dog},
  {q:"Почему праведные страдают, а нечестивые благоденствуют?",
   a:`<p>Этот вопрос волновал ещё псалмопевца и праведного Иова, и вера не отмахивается от него. Ответ её в том, что видимое не есть окончательное: пути Промысла глубоки и не всегда открыты нам здесь и сейчас. Страдание праведных бывает очищением, испытанием и возрастанием, а благополучие злых — временно и обманчиво.</p>
   <p>Псалмопевец, смущавшийся счастьем нечестивых, обрёл мир, «когда вошёл во святилище Божие и уразумел конец их» ([[Пс 72:17]]): в свете вечности всё видится иначе. Полная правда откроется на суде, где каждому воздастся по делам.</p>
   <p>Доверие благому Промыслу — не отказ от вопросов и не бесчувствие, а мир среди вопросов, основанный на уверенности, что «любящим Бога… всё содействует ко благу» ([[Рим 8:28]]).</p>`, s:SRC.dog},
  {q:"Есть ли у каждого человека ангел-хранитель?",
   a:`<p>Да. Спаситель сказал о малых: «ангелы их на небесах всегда видят лице Отца Моего Небесного» ([[Мф 18:10]]) — то есть даже самый малый член общества верующих имеет своего ангела, готового ходатайствовать пред Богом. Апостол учит об ангелах: «не все ли они суть служебные духи, посылаемые на служение для тех, которые имеют наследовать спасение?» ([[Евр 1:14]]).</p>
<p>Из этих слов следуют две мысли. Первая: поскольку каждый крещаемый присоединяется к обществу верующих, чтобы наследовать спасение, а силы человека слабы, — каждому назначается ангел-хранитель для охранения на пути. Вторая, более тонкая: раз назначение ангела относится к <em>хотящим</em> наследовать спасение, то от ослабления или угасания этого желания зависит и близость хранителя к человеку.</p>
<p>Эту же веру знала и ветхозаветная Церковь: Товит, отпуская сына в путь, желает, чтобы ангел Божий сопутствовал ему (Тов 5:17,22); о том же говорят [[Пс 90:11]] и [[Деян 12:15]]. Святитель Василий Великий писал, что у каждого из верных есть свой ангел как наставник и пастырь, — но прибавлял: хранитель с нами, пока не отгоним его худыми делами.</p>`, s:SRC.dog+" · §107"},
  {q:"Может ли добрый ангел ещё пасть?",
   a:`<p>Нет. Церковь признаёт блаженное состояние добрых ангелов неизменным — как следствие уже совершённого ими подвига. Слова Спасителя о том, что ангелы всегда видят лице Отца Небесного ([[Мф 18:10]]), означают, что ничто сотворённое не отвлекает их любви от Бога и блаженство их неизменно.</p>
<p>Блаженный Августин объясняет это так: они свободною волею устояли в истине и заслужили быть вполне уверенными, что падения с ними никогда не будет; а на вопрос, почему они блаженны, правильный ответ один — потому что они привержены Богу. Той же неизменностью, замечает он, они победили в себе самую изменяемость свою.</p>
<p>Важно, что речь идёт не об отнятии свободы, а о её увенчании: добро, свободно избранное и утверждённое, перестаёт быть шатким. Писание сравнивает с положением ангелов состояние праведных по воскресении ([[Лк 20:36]]; [[Мф 22:30]]) — то есть и человеку обещано такое же непоколебимое утверждение в добре.</p>`, s:SRC.dog+" · §108–109"},
  {q:"Сохранили ли падшие духи разделение на чины?",
   a:`<p>Да, злые духи удержали за собою по падении и разделение на чины. Откровение представляет одного из числа падших духов главным и называет его сатаною и диаволом (греч. διάβολος — клеветник, противник), а прочих — ангелами его ([[Мф 25:41]]; [[Откр 12:7]]). Главный дух именуется также веельзевулом и князем бесовским ([[Мф 12:24]]), велиаром ([[2 Кор 6:15]]).</p>
<p>Апостол Павел говорит о «началах и властях» тьмы как о различных между собою по силе и власти ([[Еф 6:12]]; [[Кол 2:15]]). Спаситель отличает среди духов особый «род» (τοῦτο τὸ γένος), который не иначе может быть изгоняем, как постом и молитвою, — без чего не могли изгнать его даже апостолы ([[Мф 17:21]]). В другом месте различаются духи «злейшие» ([[Мф 12:45]]; [[Лк 11:26]]).</p>
<p>Из этого видно, что падение не уничтожило самой природы ангельской с её порядком и различием сил, но извратило направление воли. Тот же порядок, который у добрых духов служит стройности служения Богу, у падших обратился в организованность вражды.</p>`, s:SRC.dog+" · §110"},
  {q:"Каков нравственный характер диавола по Евангелию?",
   a:`<p>Спаситель дал ему самое краткое и точное определение: «он был человекоубийца от начала и не устоял в истине, ибо нет в нём истины; когда говорит он ложь, говорит своё, ибо он лжец и отец лжи» ([[Ин 8:44]]).</p>
<p>Здесь два полустишия, и в обоих нравственные действия диавола объясняются из его нравственного характера. Сначала показано его отношение к людям — он человекоубийца; затем причина: истины совсем нет в его расположениях, весь нравственный характер его сделался враждебным истине. Употреблённая форма глагола означает не единичный поступок, а продолжающийся образ действия.</p>
<p>При этом «истина» у евангелиста означает не одну теоретическую правильность, но и нравственную верность, а «ложь» смыкается с нечестием ([[Ин 3:19]]). Отсюда вывод: диавол делает только злое, потому что он зол по самому своему нравственному характеру. Соответственно Писание называет его «лукавым» ([[Мф 13:19]]), «врагом» ([[Мф 13:39]]), а падших духов — «духами злобы» ([[Еф 6:12]]) и «духами нечистыми» ([[Лк 8:29]]).</p>`, s:SRC.dog+" · §111"},
  {q:"На что простирается действие злых духов — только ли на душу?",
   a:`<p>Писание различает три области. <b>На душу</b>: по учению апостолов сатана может производить в уме человека помрачение ([[2 Кор 4:4]]), возбуждать в сердце ощущения душевредные и ослаблять добрые впечатления ([[1 Кор 7:5]]), располагать волю ко злу ([[2 Тим 2:26]]; [[Деян 5:3]]). Спаситель говорит, что диавол уносит слово из сердец слушающих, чтобы они не уверовали и не спаслись ([[Лк 8:12]]).</p>
<p><b>На тело</b>: Писание представляет это действие несомненным и жестоким — когда злые духи, вселяясь в тело, начинают управлять им по злобному произволу. Считать бесноватых, о которых так часто говорится в истории Христа и апостолов, за лунатиков, эпилептиков или меланхоликов означало бы допускать очевидную несправедливость: евангелисты ясно отличали бесноватых от обыкновенных больных и даже от самих лунатиков ([[Мф 4:24]]).</p>
<p><b>На внешнее благосостояние</b>: наиболее ясный пример — история Иова, где бедствия постигают имущество, семью и здоровье праведника. Но именно там же показано и главное ограничение: диавол не смеет назвать своим даже то, что сам хочет сделать, и испрашивает дозволение у Мироправителя ([[Иов 1:11]]; [[Иов 2:5]]).</p>`, s:SRC.dog+" · §112–114"},
  {q:"Ограничена ли свобода злых духов и могут ли они покаяться?",
   a:`<p>Свобода их не отнята, но и не безгранична. Апостол Пётр пишет, что Бог связал согрешивших ангелов узами адского мрака для сохранения на суд ([[2 Пет 2:4]]), апостол Иуда — что Бог соблюдает отпадших духов в вечных узах под мраком на суд великого дня ([[Иуд 1:6]]). Значит, состояние их неизбежно-бедственно, но окончательное решение участи ещё впереди — и они это знают: «пришёл еси прежде времене мучити нас», кричал бес Христу ([[Мф 8:29]]), а легион бесов умолял не приказывать им идти в бездну ([[Лк 8:31]]).</p>
<p>История Иова показывает и предел их действий: Мироправитель, попуская диаволу действовать, Сам назначает границу — «только на него не простирай руки твоей» ([[Иов 1:12]]), «только душу его сбереги» ([[Иов 2:6]]). А исход той истории, где участь Иова переменилась к лучшему, показывает, что Бог, попуская зло, не только восстанавливает нарушенный порядок, но и устрояет большее благо.</p>
<p>О покаянии Филарет высказывается осторожно и не так резко, как многие: по понятию о благости Божией такая возможность, без сомнения, есть; но так как они упорно-злы, то едва ли захотят каяться. Препятствие, таким образом, не в недостатке милосердия Божия, а в закоснелости самой воли.</p>`, s:SRC.dog+" · §115–116"}
 ]
},

/* ============================ 6. АНТРОПОЛОГИЯ ============================ */
{
 id:"antropologiya", title:"Учение о человеке",
 sub:"Антропология: образ Божий, душа, назначение",
 qa:[
  {q:"Каким сотворён человек?",
   a:`<p>Человек создан особым советом и действием Божиим как венец видимого творения. В отличие от прочих тварей, вызванных к бытию простым словом («да будет»), о человеке сказано с особым намерением: «сотворим человека по образу Нашему и по подобию Нашему» ([[Быт 1:26]]).</p>
   <p>Он сотворён из двух начал: тело образовано из «праха земного», а душа — вдунута Богом ([[Быт 2:7]]). Оттого человек соединяет в себе оба мира — вещественный и духовный — и служит как бы связью всего творения. Ему дано владычество над землёй и, главное, призвание жить в общении с Богом.</p>
   <p>Первоначально человек был чист, безгрешен, наделён свободой и предназначен к бессмертию и возрастанию в богоподобии — состояние, утраченное в грехопадении и восстанавливаемое во Христе.</p>`, s:SRC.dog},
  {q:"Что такое образ Божий в человеке?",
   a:`<p>Образ Божий — это богоподобное устроение человеческой души: разум, свободная воля, способность любить и творить, совесть, бессмертие духа, дар владычества над тварью. Этими чертами человек отражает своего Создателя и превосходит прочий видимый мир, будучи как бы «Богом малым» среди творения.</p>
   <p>Образ дан всем людям без исключения и не утрачивается вполне даже во грехе, хотя и помрачается им, как загрязняется, но не уничтожается царское изображение на монете. Именно ради этого образа священна и неприкосновенна всякая человеческая жизнь; потому апостол запрещает злословить людей, «сотворённых по подобию Божию» ([[Иак 3:9]]).</p>`, s:SRC.dog},
  {q:"Чем различаются образ и подобие?",
   a:`<p>Многие отцы Церкви различали эти слова так: <em>образ</em> — это данное человеку от сотворения богоподобное устроение (разум, свобода, бессмертие), а <em>подобие</em> — это задача и цель: уподобляться Богу в святости, любви и добродетели, осуществляемая свободным произволением и содействием благодати.</p>
   <p>Иначе говоря, образ есть у каждого как готовый дар, а подобие достигается всей жизнью по Богу как плод свободного труда и благодати. Человек призван из «образа» вырасти в «подобие». Предел этого возрастания указал Сам Христос: «Будьте совершенны, как совершен Отец ваш Небесный» ([[Мф 5:48]]).</p>`, s:SRC.dog},
  {q:"Что такое душа?",
   a:`<p>Душа — разумное, свободное, бессмертное духовное начало человека, которое оживляет тело, познаёт, чувствует, желает и стремится к Богу. Она сотворена Богом и не происходит из вещества и не есть «тонкое тело»; именно в душе прежде всего запечатлён образ Божий.</p>
   <p>По разлучении с телом в смерти душа не уничтожается, но продолжает жить, сознавать и помнить. Господь ставит душу выше всего мира: «какая польза человеку, если он приобретёт весь мир, а душе своей повредит? или какой выкуп даст человек за душу свою?» ([[Мф 16:26]]).</p>`, s:SRC.dog},
  {q:"Из чего состоит человек — из двух частей или трёх?",
   a:`<p>Основное деление — <em>двухчастное</em> (дихотомия): человек есть единство души и тела. Вместе с тем апостол Павел говорит о «духе, душе и теле» ([[1 Фес 5:23]]), и некоторые отцы, следуя ему, различают в человеке три стороны, понимая «дух» не как особую субстанцию, а как высшую часть души — ту, что обращена к Богу.</p>
   <p>Оба способа выражения согласны в главном: человек — не только тело и не только душа, а их живое, целостное единство, и высшее в нём — способность к богообщению. При этом тело не есть темница или зло (как учили некоторые языческие философы), а храм Духа ([[1 Кор 6:19]]), предназначенный к воскресению и прославлению.</p>`, s:SRC.dog},
  {q:"Бессмертна ли душа?",
   a:`<p>Да, душа бессмертна — но не по собственной природе, как нечто самобожественное, а по дару и воле Божией, сотворившей её для вечности. По смерти тела она продолжает жить, сознавать, мыслить и помнить, ожидая всеобщего воскресения.</p>
   <p>Господь есть «Бог не мёртвых, но живых» ([[Мф 22:32]]) — эти слова Он сказал о давно умерших патриархах, которые, стало быть, живы у Бога. Благоразумному разбойнику на кресте Он обещал: «ныне же будешь со Мною в раю» ([[Лк 23:43]]) — то есть в тот же день, ещё до всеобщего воскресения.</p>
   <p>При этом полнота человека восстановится лишь в последний день, когда с душою воссоединится воскресшее и преображённое тело: христианская надежда — не в бесплотном бессмертии души, а в воскресении всего человека.</p>`, s:SRC.dog},
  {q:"В чём назначение человека?",
   a:`<p>Назначение человека — знать, любить и прославлять Бога, возрастать в уподоблении Ему и в общении с Ним достигать вечного блаженства. Человек создан не ради себя самого и не ради мира, а ради Бога, и лишь в Нём находит полноту и покой.</p>
   <p>Блаженный Августин выразил это словами: «Ты создал нас для Себя, и не знает покоя сердце наше, пока не успокоится в Тебе». Высшая цель, к которой ведёт спасение, — обожение, приобщение Божественной жизни по благодати, о чём говорит апостол: мы призваны стать «причастниками Божеского естества» ([[2 Пет 1:4]]).</p>`, s:SRC.dog},
  {q:"Что такое совесть?",
   a:`<p>Совесть — вложенный Богом внутренний закон, которым человек различает добро и зло, судит свои поступки и понуждается к добру. Она есть и у не знавших писаного закона: апостол говорит о язычниках, у которых «дело закона написано в сердцах, о чём свидетельствует совесть их» ([[Рим 2:15]]).</p>
   <p>Совесть можно заглушить, ожесточить и исказить привычкой ко греху, поэтому её нужно хранить чистой и просвещать словом Божиим и жизнью в Церкви, чтобы она судила по правде Божией, а не по искажённым понятиям. Чистая совесть — великое благо и залог дерзновения пред Богом; апостол дорожил тем, чтобы «всегда иметь непорочную совесть пред Богом и людьми» ([[Деян 24:16]]).</p>`, s:SRC.dog},
  {q:"Что такое свобода воли?",
   a:`<p>Свобода воли — данная человеку от сотворения способность самоопределения, выбора между добром и злом. Без неё не было бы ни нравственности, ни заслуги, ни вины, ни ответственности; она — часть образа Божия и необходимое условие любви, ибо любовь возможна только свободная, а не вынужденная.</p>
   <p>Писание постоянно предполагает и утверждает эту свободу: «Бог от начала… оставил его в руке произволения его» ([[Сир 15:14]]); Моисей ставит перед народом выбор: «жизнь и смерть предложил я тебе… избери жизнь» ([[Втор 30:19]]).</p>
   <p>Грех повредил свободу, склонив её ко злу и ослабив, но не уничтожил; благодать же исцеляет её и возвращает ей силу свободно избирать добро.</p>`, s:SRC.dog},
  {q:"Едины ли все люди по происхождению?",
   a:`<p>Да, всё человечество происходит от одной четы прародителей и составляет единый род. Апостол прямо возвестил это язычникам-афинянам: Бог «от одной крови произвёл весь род человеческий для обитания по всему лицу земли» ([[Деян 17:26]]).</p>
   <p>Это единство рода — не второстепенная подробность, а основание сразу нескольких истин: всеобщего братства и равного достоинства всех народов; всеобщности повреждения грехом (как в Адаме все умирают); и всеобщности спасения (так во Христе, новом Адаме, все оживут — [[1 Кор 15:22]]). Родство языков и народов лишь подтверждает это первоначальное единство.</p>`, s:SRC.dog},
  {q:"Какие мнения о происхождении души существовали в Церкви?",
   a:`<p>На вопрос, откуда берётся душа в каждом человеке, в христианской Церкви предлагали три разных ответа.</p>
<p><b>1. Предсуществование.</b> Одни полагали, что души человеческие существовали ещё прежде этого мира. Это мнение разделял Ориген вместе с Филоном и последователями Платона, присоединив к нему мысль, что души посылаются в тела за грехи предвременной жизни. Синезий и немногие другие верили в предсуществование душ, не разделяя оригеновой мысли о предвременном падении.</p>
<p><b>2. Творение каждой души.</b> Святитель Иларий писал, что души каждый день появляются сокровенною и неведомою силою Божией; так же думали Феодорит, Кирилл Александрийский, Иероним.</p>
<p><b>3. Рождение души вместе с телом.</b> «Мы утверждаем, — писал Тертуллиан, — что обе субстанции, и душа и тело, вместе и зачинаются, и совершенствуются». Это мнение разделяли Григорий Нисский, Макарий Великий, Анастасий пресвитер и многие другие. Сам Ориген признавал, что церковным учением вопрос не определён вполне ясно; Григорий Богослов и Августин остались безразличны ко второму и третьему мнениям.</p>`, s:SRC.dog+" · §126"},
  {q:"Почему Церковь отвергла мнение о предсуществовании душ?",
   a:`<p>Филарет приводит целый ряд возражений. Непонятно, как душа ничего не помнит из происшествий своей прежней жизни: забыть целую жизнь с её действиями неестественно, а допускать здесь чудо нет никакой нужды. Ещё непонятнее, как душа будет каяться целую жизнь в грехах, которых вовсе не помнит и не знает.</p>
<p>Далее, Писание ясно учит, что грех вошёл в человеческий мир вместе с преступлением Адама ([[Рим 5:12]]), а не прежде того. Если же вместе с мнением о предвременном существовании не принимать оригеновой мысли о предвременном падении, то непонятно, как невинная душа, входя в тело, становится испорченной, — одним общением с телом порчу объяснить нельзя; и за что невинная душа страдает в испорченном теле?</p>
<p>Наконец, это мнение не может быть подкреплено ни одним изречением Писания, даже отдалённым. Григорий Богослов называл его «нелепым и нецерковным», Григорий Нисский и Феодорит — баснословным, Августин — еретическим; торжественно же оно было осуждено на Константинопольском соборе 543 года.</p>`, s:SRC.dog+" · §126"},
  {q:"Какие возражения делаются против мнения о творении каждой души?",
   a:`<p>Филарет перечисляет их так. Во-первых, это мнение не может быть примирено с покоем Творца, закончившим всякое новое создание ([[Быт 2:2]]). Во-вторых, им не объясняется, как переходит наследственная порча Адама к его потомкам. В-третьих, при нём вина наследственного бедствия людей возлагается на Творца — ибо выходит, что Бог творит душу и тотчас помещает её в повреждённое состояние.</p>
<p>В-четвёртых, непонятно тогда, как вочеловечение Слова не будет только принятием одного тела: если душа творится отдельно, связь Спасителя с родом человеческим по душе оказывается иной, чем у прочих людей.</p>
<p>В-пятых, самые изречения Писания, на которые указывают в подтверждение, этой мысли не заключают. Екклезиаст ([[Еккл 12:7]]) говорит не о происхождении души в каждом человеке, а вообще о происхождении её от Бога как виновника всего существующего; пророк Иеремия ([[Иер 1:5]]) говорит о своём предназначении к званию пророка; [[Лк 1:41]] показывает лишь то, что душа жива бывает и во чреве матери.</p>`, s:SRC.dog+" · §126"},
  {q:"Почему предпочтительнее мнение о рождении души вместе с телом?",
   a:`<p>Филарет склоняется к третьему мнению и приводит его основания. Возражение, будто им оскорбляется духовность души, он отводит: если пребыванием души в теле при жизни духовность её не оскорбляется, то столь же мало оскорбляется она и образованием души во чреве матери.</p>
<p>Положительные доводы таковы: этим мнением лучшим образом объясняется переход порчи Адамовой к потомкам; оно подкрепляется сходством детей с родителями даже по душевным качествам; им поддерживается мысль об общем начале всех людей. Наконец, в его пользу говорят изречения Писания: первоначальное благословение о размножении людей ([[Быт 1:28]]) выражено теми же словами, какими выражено и благословение о размножении животных ([[Быт 1:22]]); об Адаме сказано, что он родил сына по подобию своему ([[Быт 5:3]]), подобно тому как сам он сотворён по подобию Божию; Спаситель говорит: «рождённое от плоти есть плоть» ([[Ин 3:6]]) — то есть с рождением человека рождается вместе и душа; апостол учит, что Бог «от одной крови произвёл весь род человеческий» ([[Деян 17:26]]).</p>
<p>При этом сила чадорождения остаётся за волею Промыслителя и за первоначальным благословением Божиим, так что остаются в силе и те места Писания, где Бог представляется виновником нашей жизни ([[Зах 12:1]]; [[Деян 17:25]]).</p>`, s:SRC.dog+" · §126"},
  {q:"Заключается ли образ Божий и в теле человека?",
   a:`<p>Общим мнением отцов было, что образ Божий должно искать не в теле, а в душе. К принадлежностям образа Божия относили высшие духовные силы — или, по выражению блаженного Августина, то, что понимает истину, различает правду от неправды, может разуметь и хвалить Творца своего, — а равно и совершенства духовных сил.</p>
<p>Правда, некоторые ранние писатели — Иустин, Ириней, Тертуллиан, — имея дело с гностиками-дуалистами, которые презирали тело, переносили образ Божий и на телесный организм. Но этим они говорили лишь то, что <em>весь</em> человек есть совершенное создание Божие; преимущество же человека, собственно образ Божий, полагали и они в уме и свободе. Телесный организм в их понятии — только отпечаток совершенного духовного устроения.</p>
<p>Мысль же о том, будто Бог имеет руки, ноги и тело, строго порицал уже святой Иустин; так думали лишь авдиане, не умевшие представить себе Бога иначе как в образе человека, и такое понятие решительно отвергали Климент Александрийский, Ориген, Кирилл Александрийский (написавший особое сочинение против антропоморфитов), Августин и Григорий Нисский.</p>`, s:SRC.dog+" · §131"},
  {q:"Было ли тело первого человека бессмертным по природе?",
   a:`<p>По телесному составу первозданный был свободен от болезней и бессмертен, но не сам по себе: расстройство могло проникнуть в его организм только вместе с грехом. Определение Божие «в оньже аще день снесте от него, смертию умрете» ([[Быт 2:17]]) показывает, что если бы прародители не вкусили запрещённого плода, они бы не умерли; приговор «земля еси и в землю отыдеши» ([[Быт 3:19]]) произнесён именно за преступление.</p>
<p>Апостол подтверждает: смерть — от человека ([[1 Кор 15:21]]), «грехом смерть вниде в мир» ([[Рим 5:12]]). Равно утомление и болезни назначены человеку в наказание за преступление заповеди, и следовательно, им не подлежало тело невинного человека.</p>
<p>При этом тело первозданного было взято от земли и, как земное, должно было испытать перемену при переходе на небо, — но это изменение при крепости духа не могло быть болезненным. Апостол называет невинного Адама «перстным» и не усвояет ему тела духовного ([[1 Кор 15:46]]). А слова «жало же смерти грех» ([[1 Кор 15:56]]) означают, что причина, по которой смерть действует ядовито и разрушительно, состоит именно в грехе; без греха организм потерпел бы только лёгкое изменение.</p>`, s:SRC.dog+" · §130"}
 ]
},

/* ============================ 7. АМАРТОЛОГИЯ ============================ */
{
 id:"amartologiya", title:"Учение о грехе",
 sub:"Амартология: грехопадение и его следствия",
 qa:[
  {q:"Что такое грех?",
   a:`<p>Грех — это нарушение воли Божией, свободное уклонение разумного существа от добра и от Бога. Апостол даёт точное определение: «всякий, делающий грех, делает и беззаконие; и грех есть беззаконие» ([[1 Ин 3:4]]) — то есть преступление закона, вложенного Богом.</p>
   <p>При этом грех — не самостоятельная сущность и не сотворён Богом; это порча, лишение и искажение блага, подобно тому как тьма есть отсутствие света, а болезнь — расстройство здоровья. Зло не имеет собственного бытия, а паразитирует на добром, извращая его.</p>
   <p>Корень греха — в злоупотреблении свободой: в предпочтении себя и твари Богу, в желании быть источником блага помимо Него.</p>`, s:SRC.dog},
  {q:"В чём состояло грехопадение прародителей?",
   a:`<p>Первые люди преступили единственную данную им заповедь, вкусив по внушению искусителя от древа познания добра и зла ([[Быт 3:6]]). Внешне малый поступок был по сути тяжким, ибо в нём выразилось внутреннее отпадение: недоверие Богу, своеволие, желание самим определять добро и зло.</p>
   <p>Существо падения — в гордости: человек поверил обещанию «будете, как боги» ([[Быт 3:5]]) и захотел стать самому себе законом и источником блага помимо Бога. Так тварь поставила себя на место Творца.</p>
   <p>Заповедь же о древе не была произволом: она была условием свободного послушания и любви, испытанием, в котором человек мог бы утвердиться в добре. Пав, он утвердился в противоположном.</p>`, s:SRC.dog},
  {q:"Каковы следствия грехопадения?",
   a:`<p>Через грех расстроилась вся жизнь человека и мира. Помрачился ум, ослабела и склонилась ко злу воля, взбунтовались против разума страсти, разрушилось согласие человека с Богом, с ближними и с самим собою. В мир вошли тление, болезнь и смерть: «возмездие за грех — смерть» ([[Рим 6:23]]).</p>
   <p>Человек был изгнан из рая — из состояния близости к Богу; земля стала произращать «терния и волчцы» ([[Быт 3:18]]), труд стал тяжким, а жизнь — смертной. Повреждение коснулось и всей природы, которая «покорилась суете» ([[Рим 8:20]]) и вместе с человеком ожидает избавления.</p>
   <p>Так грех одного человека имел вселенские последствия — потому и спасение должно было прийти через нового Человека, Христа.</p>`, s:SRC.dog},
  {q:"Что такое первородный грех?",
   a:`<p>Первородный грех — это унаследованная всеми потомками Адама повреждённость человеческой природы: удобопреклонность ко злу, страстность, смертность. Переходит на весь род не личная вина Адама как поступок (её он совершил сам), а её <em>последствия</em> — испорченная, смертная природа, которую мы получаем при рождении.</p>
   <p>«Как одним человеком грех вошёл в мир, и грехом смерть, так и смерть перешла во всех человеков, потому что в нём все согрешили» ([[Рим 5:12]]). От этой прирождённой повреждённости никто не свободен собственными силами.</p>
   <p>Исцеляет её только Христос, «новый Адам»: как от первого Адама мы наследуем смерть, так от Христа получаем жизнь. Начало этого исцеления подаётся в крещении.</p>`, s:SRC.dog},
  {q:"Виновен ли младенец в первородном грехе?",
   a:`<p>Младенец не несёт личной вины за грех Адама — он его не совершал и вообще ещё не делал сознательного выбора. Но он рождается с повреждённой, смертной природой, унаследованной от прародителей, и потому нуждается в возрождении крещением, вводящим его в новую жизнь во Христе.</p>
   <p>О детях Господь говорит с особой любовью и ставит их в пример: «пустите детей приходить ко Мне и не препятствуйте им, ибо таковых есть Царствие Божие» ([[Мк 10:14]]). Крещение младенцев и есть исполнение этого призыва — приведение их ко Христу и в Церковь, не откладывая до «сознательного возраста».</p>`, s:SRC.dog},
  {q:"Чем различаются грехи по тяжести?",
   a:`<p>Грехи различаются и по способу (делом, словом, мыслью), и по произволению (вольные и невольные, по немощи или по злому умыслу), и по тяжести. Апостол Иоанн прямо различает грех «к смерти» и грех «не к смерти» ([[1 Ин 5:16]]) — по мере ожесточения воли и удаления от Бога.</p>
   <p>Тяжкими (смертными) называют грехи, которые, если в них коснеть без покаяния, отлучают человека от благодати и духовно умерщвляют душу, — в отличие от повседневных немощей, неизбежных для всякого. Различие это важно не для того, чтобы «мелкие» грехи считать безопасными, а чтобы верно судить о состоянии души.</p>
   <p>При этом никакая тяжесть греха не превышает милости Божией к искренне кающемуся: нет греха, побеждающего человеколюбие Божие, кроме нераскаянности.</p>`, s:SRC.dog},
  {q:"Что такое страсть?",
   a:`<p>Страсть — это укоренившаяся, ставшая как бы второй природой греховная склонность, порабощающая волю и разум. Аскетическая традиция называет восемь главных страстей, из которых вырастают прочие: чревоугодие, блуд, сребролюбие, гнев, печаль, уныние, тщеславие и гордость.</p>
   <p>Отцы описали и то, как страсть овладевает человеком: она начинается с <em>помысла</em> (прилога), через сочувствие и согласие переходит в <em>решение</em>, затем в <em>дело</em>, а через повторение — в <em>навык</em> и наконец в рабство: «кто кем побеждён, тот тому и раб» ([[2 Пет 2:19]]).</p>
   <p>Врачуются страсти не одним усилием воли, а покаянием, воздержанием, молитвой и насаждением противоположных добродетелей при действии благодати: гордость исцеляется смирением, сребролюбие — милостыней, гнев — кротостью.</p>`, s:SRC.dog},
  {q:"Есть ли непростительный грех?",
   a:`<p>Непростителен, по слову Господа, не какой-либо отдельный грех сам по себе, а «хула на Духа Святого» ([[Мф 12:31]]). Отцы понимают под нею не случайное дурное слово, а сознательное, упорное и ожесточённое противление явной истине и отвержение самой спасающей благодати — состояние, в котором человек называет добро злом и не желает каяться.</p>
   <p>Такой грех «не прощается» не потому, что превышает милость Божию, а потому, что сам грешник добровольно и до конца отвергает прощение и не хочет его принять. Прощение всегда предлагается, но не может быть навязано против воли.</p>
   <p>Всякому же, кто кается, прощается любой грех, как бы тяжёл он ни был: «приходящего ко Мне не изгоню вон» ([[Ин 6:37]]).</p>`, s:SRC.dog},
  {q:"Может ли человек сам, без Бога, победить грех?",
   a:`<p>Нет. Повреждённая грехом природа не исцеляется одними человеческими усилиями: воля ослаблена, ум помрачён, и даже зная добро, человек часто не находит сил его исполнить — об этой раздвоенности говорит апостол: «желание добра есть во мне, но чтобы сделать оное, того не нахожу» ([[Рим 7:18]]). Для победы над грехом необходима благодать, подаваемая во Христе и в таинствах Церкви.</p>
   <p>Господь прямо сказал: «без Меня не можете делать ничего» ([[Ин 15:5]]); и апостол, познав немощь, исповедал силу: «всё могу в укрепляющем меня Иисусе Христе» ([[Флп 4:13]]).</p>
   <p>При этом благодать не действует помимо человека: спасение — дело <em>синергии</em>, соработничества Божией благодати и свободного человеческого произволения.</p>`, s:SRC.dog},
  {q:"Если грех так силён, есть ли надежда?",
   a:`<p>Да, и вся весть Евангелия — именно об этой надежде. Как ни глубоко повреждение человека, милость Божия и сила Христова несравненно больше: «когда умножился грех, стала преизобиловать благодать» ([[Рим 5:20]]).</p>
   <p>Христос пришёл в мир не для того, чтобы осудить уже осуждённых грехом, а чтобы спасти: «Христос Иисус пришёл в мир спасти грешников, из которых я первый» ([[1 Тим 1:15]]), — говорит апостол Павел, бывший гонитель; «Сын Человеческий пришёл взыскать и спасти погибшее» ([[Лк 19:10]]).</p>
   <p>Поэтому христианское учение о грехе не ведёт к унынию и не подавляет человека виной, а обращает его к Спасителю и к покаянию, которое остаётся открытым до последнего вздоха.</p>`, s:SRC.dog}
 ]
},

/* ============================ 8. ХРИСТОЛОГИЯ ============================ */
{
 id:"hristologiya", title:"Учение о Христе",
 sub:"Христология: воплощение и две природы",
 qa:[
  {q:"Кто такой Иисус Христос?",
   a:`<p>Иисус Христос — воплотившийся Сын Божий, второе Лицо Святой Троицы, ставший человеком ради нашего спасения. Он есть истинный Бог и истинный человек в одном Лице — Богочеловек, не «полубог» и не «обожествлённый человек», а Бог, воспринявший полное человечество.</p>
   <p>«Слово стало плотию и обитало с нами, полное благодати и истины» ([[Ин 1:14]]). В Нём «обитает вся полнота Божества телесно» ([[Кол 2:9]]). Он — обещанный от века Мессия, Спаситель мира, Глава Церкви и грядущий Судия живых и мёртвых.</p>
   <p>Христология — сердцевина всего вероучения: от того, как мы понимаем Христа, зависит и понимание спасения, ибо спасает нас именно то, что Спаситель есть вместе и Бог, и человек.</p>`, s:SRC.dog},
  {q:"Что означает имя «Иисус Христос»?",
   a:`<p>«Иисус» — личное имя, означающее по-еврейски «Господь спасает». Ангел объяснил его смысл Иосифу: «наречёшь Ему имя Иисус, ибо Он спасёт людей Своих от грехов их» ([[Мф 1:21]]) — то есть само имя уже возвещает дело спасения.</p>
   <p>«Христос» — не фамилия, а звание (греческий перевод еврейского «Мессия»), означающее «Помазанник». В Ветхом Завете через помазание елеем поставляли на служение царей, первосвященников и пророков. Христос совмещает в Себе все три служения: Он — вечный Царь, Первосвященник, принёсший Себя в жертву, и Пророк, возвестивший волю Отца, — помазанный не елеем, а Самим Духом Святым ([[Лк 4:18]]).</p>`, s:SRC.dog},
  {q:"Как в Христе соединены две природы?",
   a:`<p>В едином Лице Христа Божественная и человеческая природы соединены, по определению IV Вселенского собора (Халкидон, 451 г.), четырьмя словами: <em>неслитно, неизменно, нераздельно, неразлучно</em>. Первые два слова направлены против слияния природ, вторые два — против их разделения.</p>
   <p>Это значит: природы не смешиваются в некую третью, «средню́ю» природу и не изменяются одна в другую (Божество не превращается в человечество и наоборот); но при этом они и не разделяются на два отдельных лица, а пребывают в неразрывном единстве единого Лица Сына Божия.</p>
   <p>Поэтому Христос — не Бог, лишь «вселившийся» в человека, и не человек, «ставший» со временем Богом, а единое Лицо Сына, вечно сущего Богом и во времени воспринявшего полное человечество. По слову отцов, Он «не переставая быть тем, чем был, стал тем, чем не был».</p>`, s:SRC.dog+" · "+SRC.ist},
  {q:"Истинный ли человек Христос?",
   a:`<p>Да, Христос воспринял полную и подлинную человеческую природу — тело и разумную душу, — во всём подобную нашей, кроме греха. Он рос и укреплялся, алкал и жаждал, утруждался, скорбел, плакал у гроба Лазаря ([[Ин 11:35]]), испытывал страх пред страданием в Гефсимании.</p>
   <p>Это не второстепенная подробность, а условие спасения. Отцы выразили правило: «невоспринятое не уврачёвано» — Христос должен был воспринять всё подлинно человеческое, чтобы всё в человеке исцелить. Потому Он «подобно нам искушён во всём, кроме греха» ([[Евр 4:15]]).</p>
   <p>Тех, кто отрицал реальность плоти Христа, считая её лишь видимостью (докеты), Церковь осудила: если Христос не был истинным человеком, то и не страдал истинно, и не спас нас истинно.</p>`, s:SRC.dog},
  {q:"Сколько во Христе воль и действий?",
   a:`<p>Две — Божественная и человеческая, ибо каждая совершенная природа имеет свою природную волю и своё действие; воля принадлежит природе, а не лицу. Но человеческая воля Христа не противится Божественной, а свободно и всецело с нею согласуется.</p>
   <p>Это ясно видно в Гефсиманском молении: «Отче Мой! если возможно, да минует Меня чаша сия; впрочем не как Я хочу, но как Ты» ([[Мф 26:39]]); «не Моя воля, но Твоя да будет» ([[Лк 22:42]]). Здесь человеческая воля Христа, естественно отвращаясь от смерти, свободно предаёт себя воле Отца.</p>
   <p>Учение о двух волях исповедал VI Вселенский собор (680–681 гг.) против монофелитства — учения об одной воле, которое, умаляя человеческую волю Христа, умаляло и полноту Его человечества.</p>`, s:SRC.ist},
  {q:"Зачем Сын Божий стал человеком?",
   a:`<p>Чтобы спасти человека изнутри — не извне, одним повелением, а войдя в самую человеческую природу, исцелив её и соединив с Богом. Пал человек — и Спаситель стал человеком; поражена была смертью человеческая природа — и Бог воспринял её, чтобы победить смерть в ней самой.</p>
   <p>Отцы кратко выразили цель воплочения: «Бог стал человеком, чтобы человек стал богом» — то есть чтобы человек по благодати приобщился Божественной жизни, для которой и был создан.</p>
   <p>В воплощении открылась и мера любви Божией, и способ спасения: Христос пришёл «взыскать и спасти погибшее» ([[Лк 19:10]]), а движущая причина — любовь: «так возлюбил Бог мир, что отдал Сына Своего единородного» ([[Ин 3:16]]).</p>`, s:SRC.dog},
  {q:"Что такое Благовещение и бессеменное зачатие?",
   a:`<p>Благовещение — весть архангела Гавриила Деве Марии о том, что Она станет Матерью Сына Божия. На Её недоумение — «как будет это, когда Я мужа не знаю?» — ангел ответил: «Дух Святый найдёт на Тебя, и сила Всевышнего осенит Тебя; посему и рождаемое Святое наречётся Сыном Божиим» ([[Лк 1:35]]).</p>
   <p>Христос зачат не от мужа, а наитием Святого Духа — потому Он рождён и как истинный человек (от Девы), и как безгрешный, свободный от наследственного повреждения, передающегося обычным рождением. Бессеменное зачатие — знак того, что спасение есть новое творческое действие Бога, а не продолжение падшего рода.</p>
   <p>Дева свободно приняла волю Божию: «се, Раба Господня; да будет Мне по слову твоему» ([[Лк 1:38]]) — Её согласие вошло в тайну воплощения.</p>`, s:SRC.dog},
  {q:"Кто такая Дева Мария по отношению ко Христу?",
   a:`<p>Пресвятая Дева Мария — Матерь воплотившегося Сына Божия, а потому именуется <em>Богородицей</em>. Наименование это относится не к тому, будто Она родила Само вечное Божество, а к тому, что Рождённый от Неё по плоти есть единое Лицо Богочеловека, истинный Бог.</p>
   <p>Наименование «Богородица» (греч. <em>Феотокос</em>) утвердил III Вселенский собор (Ефес, 431 г.) против Нестория, который хотел называть Её лишь «Христородицей», разделяя во Христе Бога и человека. Церковь отвергла это как разрушение единства Христа.</p>
   <p>Ещё прежде собора праведная Елисавета, исполнившись Духа, назвала Марию «Матерью Господа моего» ([[Лк 1:43]]) — то есть уже в Евангелии дано основание этого именования.</p>`, s:SRC.ist},
  {q:"Был ли Христос предсказан в Ветхом Завете?",
   a:`<p>Да, весь Ветхий Завет — приготовление к Мессии и полон пророчеств о Нём, порой поразительно точных. Предсказаны рождение от Девы ([[Ис 7:14]]) и в Вифлееме ([[Мих 5:2]]), происхождение от рода Давидова, страдания и смерть за грехи народа ([[Ис 53:5]]), новый и вечный завет ([[Иер 31:31]]).</p>
   <p>Исполнение множества независимых пророчеств в одном Лице — сильное свидетельство истины веры: слишком многое сошлось, чтобы счесть это случайностью. Поэтому апостолы, проповедуя, постоянно опирались на Ветхий Завет.</p>
   <p>Сам воскресший Господь, идя с учениками в Эммаус, «начав от Моисея, из всех пророков изъяснял им сказанное о Нём во всём Писании» ([[Лк 24:27]]).</p>`, s:SRC.dog},
  {q:"Что такое кенозис (умаление) Христа?",
   a:`<p>Кенозис (греч. «истощание», «умаление») — добровольное самоумаление Сына Божия в воплощении. Апостол описывает его так: Христос, «будучи образом Божиим, не почитал хищением быть равным Богу; но уничижил Себя Самого, приняв образ раба… смирил Себя, быв послушным даже до смерти, и смерти крестной» ([[Флп 2:6]]).</p>
   <p>Это не значит, что Сын перестал быть Богом или утратил Божественные свойства: Он скрыл славу под смирением, добровольно принял немощи человеческой природы (голод, усталость, страдание, самую смерть), чтобы разделить нашу участь и спасти нас изнутри.</p>
   <p>Кенозис — образ и мера христианской любви: она являет себя не в возвышении, а в снисхождении и служении, и потому апостол ставит его в пример: «в вас должны быть те же чувствования, какие и во Христе Иисусе» ([[Флп 2:5]]).</p>`, s:SRC.dog},
  {q:"Почему монофизитство и несторианство — заблуждения?",
   a:`<p>Это две противоположные крайности, между которыми Церковь исповедала истину. <em>Несторианство</em> так разделяло природы, что во Христе получались как бы два отдельных лица — Бог и человек, лишь тесно соединённые. Тогда Дева была бы Матерью человека, а не Бога, а на Кресте страдал бы человек «сам по себе» — и нас спасал бы человек, а не Бог.</p>
   <p><em>Монофизитство</em>, напротив, сливало природы, признавая во Христе после соединения одну, Божественную природу, поглотившую человеческую. Тогда человечество Христа было бы неполным или призрачным, — а «невоспринятое неисцелимо», и человек оказался бы не спасён.</p>
   <p>Церковь, отвергнув обе крайности (на III и IV Вселенских соборах), исповедала срединную истину: одно Лицо Христа в двух полных, совершенных природах — неслитных и нераздельных.</p>`, s:SRC.ist},
  {q:"Что означает сошествие Христа во ад?",
   a:`<p>После смерти на Кресте Христос телом пребывал во гробе, а душою (соединённой с Божеством) сошёл в ад — в область умерших — и там разрушил державу смерти, изведя ветхозаветных праведников, которые от века ожидали Спасителя.</p>
   <p>Апостол пишет, что Христос, «быв умерщвлён по плоти, но ожив духом, … находящимся в темнице духам, сойдя, проповедал» ([[1 Пет 3:18]]). Так спасение простёрлось и на живших до пришествия Христова, которые не могли уверовать в ещё не пришедшего.</p>
   <p>Именно это событие изображает православная икона Воскресения: Христос, попирающий врата ада, изводит за руку Адама и Еву. Сошествие во ад — это уже начало победы, торжество жизни в самой области смерти.</p>`, s:SRC.dog},
  {q:"Почему Воскресение Христово так важно?",
   a:`<p>Воскресение — сердцевина христианской веры и залог нашего собственного воскресения. Им подтверждается, что Христос — истинный Сын Божий, что Его крестная жертва принята Отцом и что смерть побеждена не в переносном, а в подлинном смысле.</p>
   <p>Апостол Павел прямо ставит на нём всё: «если Христос не воскрес, то и проповедь наша тщетна, тщетна и вера ваша… вы ещё во грехах ваших» ([[1 Кор 15:14]]). Но тут же исповедует: «Христос воскрес из мёртвых, первенец из умерших» ([[1 Кор 15:20]]) — первый из людей, восставший в прославленном теле, за Которым последуем и мы.</p>
   <p>Важна и историчность: апостолы были очевидцами Воскресшего, преобразились из напуганных беглецов в бесстрашных свидетелей и запечатлели свидетельство мученической смертью — что трудно объяснить, будь Воскресение вымыслом.</p>`, s:SRC.dog},
  {q:"Что такое Вознесение Господне?",
   a:`<p>По Воскресении, в сороковой день, Христос в прославленном человеческом теле вознёсся на небо и «воссел одесную Бога» ([[Мк 16:19]]). «Одесную» (по правую руку) — образ высшей славы и власти. Этим человеческая природа введена в самую славу Божию — залог того, что и человек призван к небесному прославлению.</p>
   <p>Вознесясь, Христос не оставил учеников: Он обещал пребывать с ними «во все дни до скончания века» ([[Мф 28:20]]) и послать взамен Своего видимого присутствия Духа Утешителя. Так Вознесение открывает путь Пятидесятнице.</p>
   <p>Ангелы возвестили апостолам, что этот же Иисус «придёт таким же образом, как вы видели Его восходящим на небо» ([[Деян 1:11]]), — Вознесение указывает и на будущее славное пришествие.</p>`, s:SRC.dog},
  {q:"Придёт ли Христос снова?",
   a:`<p>Да, Церковь исповедует в Символе веры, что Христос «паки грядущаго со славою судити живым и мёртвым». Второе пришествие будет не в уничижении, как первое, а в славе и силе, видимо для всех и внезапно: «как молния исходит от востока и видна бывает даже до запада, так будет пришествие Сына Человеческого» ([[Мф 24:27]]).</p>
   <p>Тогда совершится всеобщее воскресение мёртвых и последний суд, и настанет вечное Царство, которому «не будет конца». О времени же пришествия «никто не знает, ни Ангелы небесные, а только Отец» ([[Мф 24:36]]), и потому Господь заповедал не вычислять сроки, а бодрствовать и быть готовыми во всякий час.</p>`, s:SRC.pred},
  {q:"Чем человечество Христа отличается от прочих людей?",
   a:`<p>Откровение, изображая Иисуса Христа истинным человеком, вместе с тем показывает в Нём преимущества, отличающие Его человечество от прочих сынов Адамовых. Первое из них — самый образ рождения: Он родился от Девы Марии, без отца, по действию Духа Святого.</p>
<p>Архангел благовествует Марии, что она зачнёт Сына Вышнего ([[Лк 1:31]]); удивлённая Мария говорит о таком своём состоянии, в котором она совсем не может быть рождающею, то есть о девстве; архангел открывает: «Дух Святый найдет на Тя» ([[Лк 1:35]]) — то есть этим действием заменится участие мужа. Здесь показывается такое же действие Духа, какое было тогда, когда Он носился животворно над первоначальным веществом мира.</p>
<p>То же подтверждает и повествование о Иосифе: «рождшееся бо в Ней от Духа есть Свята» ([[Мф 1:20]]), и евангелист прямо указывает на исполнение пророчества: «се, Дева во чреве приимет» ([[Мф 1:23]]; [[Ис 7:14]]). Таким образом, человечество Христа истинно и полно, но принято Им не путём обыкновенного рождения, — и потому свободно от наследственной порчи.</p>`, s:SRC.dog+" · §179"},
  {q:"Что значит, что Богочеловек — единое Лицо?",
   a:`<p>Когда Откровение показало, что Иисус Христос есть истинный человек и истинный Бог, остаётся ещё определить: соединены ли в Нём человечество и Божество как в единой ипостаси? То есть — всё происходившее в Богочеловеке происходило ли в сознании единого сознающего, или человечество и Божество были под управлением двух лиц?</p>
<p>Ответ Писания ясен. Евангелист говорит: «Слово плоть бысть» ([[Ин 1:14]]). «Плоть» здесь означает преимущественно видимую сторону человеческой природы, но не исключает невидимой и употребляется в значении целой немощной природы человеческой. Значит, «Слово плоть бысть» означает: Слово, Которое есть Бог, стало человеком, — а этого нельзя понять иначе, как так, что Бог и человек во Христе суть единое Лицо.</p>
<p>Ещё яснее у апостола Павла ([[Флп 2:6]]): если бы во Христе были две отдельные ипостаси, апостол не сказал бы, что <em>тот же</em>, Кто находится во образе Божием, принял зрак раба; <em>тот же</em>, Кто не считает хищением быть равным Богу, умалил Себя, став человеком. Полная мысль апостола такова: во Иисусе Христе не два лица, а одно, — Божество приняло человеческую природу в единую Свою личность.</p>`, s:SRC.dog+" · §181"},
  {q:"Что такое общение свойств во Христе?",
   a:`<p>Поскольку человеческое и Божеское естества соединены в едином Лице Богочеловека, Откровение признаёт взаимное общение свойств того и другого естества во Христе.</p>
<p>Так, Писание усвояет Христу свойства совершенно различные и даже противоположные: Он «богат сый обнища» ([[2 Кор 8:9]]), Он есть Слово, ставшее видимою плотью ([[Ин 1:14]]); Его называют Начальником жизни — и говорят, что Его убили ([[Деян 3:15]]). Искупление рода человеческого приписывается и Иисусу Богу ([[Кол 1:14]]; [[1 Ин 3:8]]), и Иисусу человеку ([[1 Тим 2:5]]).</p>
<p>Более того, само Откровение усвояет Божеской природе Христа свойства человеческие. Божество само по себе страдать не может, не может чувствовать нужд и немощей; но, соединившись лично с человечеством, оно, по изображению Откровения, претерпело все наши немощи: «аще и Сын бяше, обаче навыче от сих, яже пострада, послушанию» ([[Евр 5:8]]); «Господь и Бог стяжа Церковь Кровию Своею» ([[Деян 20:28]]). И наоборот, суд над миром предан Сыну Человеческому ([[Ин 5:27]]).</p>`, s:SRC.dog+" · §182"},
  {q:"Стало ли человечество Христа вездесущим?",
   a:`<p>Нет. Общение свойств не означает их слияния: если соединение Божества с человечеством не означает пременения одного естества в другое, то и общение свойств не означает, будто существенные свойства человечества стали существенными свойствами Божества или наоборот.</p>
<p>Человечество Иисусово, по теснейшему общению с Ним Божества, облечено славою вечного; но человечество приобрело вместе с тем только то, что могло принять. Отсюда вездеприсутствие не принадлежит человечеству Иисусову — вопреки мнению лютеран, которые вывели из общения свойств вездесущие плоти Христовой.</p>
<p>Само Евангелие свидетельствует об этом самым простым образом: «Лазарь умре, и радуюся вас ради, да веруете, яко не бех тамо» ([[Ин 11:14]]); ангел говорит жёнам: «несть зде, воста бо» ([[Мф 28:6]]; [[Мк 16:6]]). Эти слова были бы невозможны, если бы человечество Христово было повсюду.</p>`, s:SRC.dog+" · §182"},
  {q:"Страдало ли Божество и кому воздаётся поклонение во Христе?",
   a:`<p>Оба вопроса решаются одним и тем же правилом: и страдание, и поклонение относятся к Лицу, а не к отвлечённо взятому естеству.</p>
<p>О Божестве нельзя сказать в строгом смысле, что оно страдало, — страдал Богочеловек. Соединение двух естеств не исключает действий, свойственных тому и другому естеству, но поставляет действия человечества в подчинение Божеским. Откровение показывает, что страдания, которые понёс Сын Человеческий, были понесены не без участия силы Сына Божия ([[Деян 20:28]]), и что до смерти крестной смирил Себя Сын Божий ([[Флп 2:8]]).</p>
<p>Точно так же богопоклонение воздаётся прославленному Богочеловеку, а не человечеству самому по себе ([[Флп 2:10]]). Мы поклоняемся не плоти как таковой и не Божеству отдельно от воспринятого им человечества, но единому Лицу Господа Иисуса Христа. Это различение и защищает от двух противоположных крайностей — от разделения Христа надвое и от смешения естеств.</p>`, s:SRC.dog+" · §182"},
  {q:"Почему Церковь исповедует Марию Приснодевой?",
   a:`<p>Из соединения человечества с Божеством в одну Личность вытекают особые следствия и в отношении к Матери Христовой. Первое из них — приснодевство.</p>
<p>Что Она была Девою <em>до</em> рождества, видно из Её собственных слов и ответа архангела: рождение Ею Сына есть рождение без участия мужа ([[Лк 1:34]]). Что девство не нарушено и <em>в самом</em> рождестве, показывает пророчество: «се, Дева во чреве приимет и родит Сына» ([[Ис 7:14]]; [[Мф 1:23]]). Еврейское слово, переданное у Семидесяти как παρθένος, означает деву в строгом смысле — не по одному возрасту, но и по состоянию девства; в остальных местах Писания оно употреблено так же. Притом пророк возвещает царю и народу о величайшем <em>знамении</em>: если рождающая не Дева, то в чём было бы знамение и где чудо?</p>
<p>Что до девства <em>по</em> рождестве, Филарет рассуждает так: если обручник Иосиф вполне знал, как чудно Мария осталась Девою и тогда, как сделалась Материю, то надобно предположить в нём не праведного, а слишком дерзкого человека, чтобы он осмелился нарушить Её девство. Цель обручения состояла не в рождении детей, а в охранении святой Девы. Молчание Нового Завета о родных братьях и сёстрах Иисусовых — при ясном упоминании о двоюродных — служит подтверждением той же веры.</p>`, s:SRC.dog+" · §183"},
  {q:"Почему имя «Богородица» есть необходимое следствие догмата о Христе?",
   a:`<p>Потому что оно вытекает из учения о единстве Лица Богочеловека с логической неизбежностью. Если Сын Божий, Бог истинный, в вочеловечении Своём принял человеческое естество в единство Божеской Своей личности, — то преблагословенная Дева, родившая Лицо Божественное, или Бога воплотившегося, по всему праву есть Богородица (греч. Θεοτόκος).</p>
<p>Филарет называет эту мысль самым строгим и самым верным последствием первой. И заключает: отрицать справедливость именования Матери Христа Богородицею может лишь тот, кто заражён еретическими мыслями о Лице Христа Иисуса и не признаёт в Нём Бога истинного.</p>
<p>Именно поэтому спор с Несторием шёл не о почитании Девы Марии как таковом, а о Христе: отказ от слова «Богородица» означал бы, что Рождённый от Неё — не одно Лицо с Сыном Божиим. Церковь защищала здесь прежде всего догмат о воплощении ([[Мф 1:23]]; [[Лк 1:43]]; [[Гал 4:4]]).</p>`, s:SRC.dog+" · §184"}
 ]
},

/* ============================ 9. СОТЕРИОЛОГИЯ ============================ */
{
 id:"soteriologiya", title:"Учение о спасении",
 sub:"Сотериология: искупление, благодать, оправдание",
 qa:[
  {q:"Что такое спасение?",
   a:`<p>Спасение — это избавление человека от греха, проклятия и смерти и восстановление разрушенного грехом общения с Богом, ведущее к вечной жизни и блаженству. Оно шире, чем прощение вины: это исцеление самой повреждённой природы и её приобщение Богу.</p>
   <p>Спасение совершено Христом объективно, раз и навсегда, и усваивается каждым человеком лично — верой, покаянием, участием в таинствах и жизнью в Церкви. Одно без другого недостаточно: без Христа спастись нельзя, но и совершённое Христом надо свободно принять.</p>
   <p>Источник спасения один: «нет другого имени под небом, данного человекам, которым надлежало бы нам спастись» ([[Деян 4:12]]).</p>`, s:SRC.dog},
  {q:"Что такое искупление?",
   a:`<p>Искупление — совершённое Христом дело избавления людей от рабства греху, от проклятия закона и от власти смерти ценою Его крестной жертвы. Само слово указывает на освобождение как бы через «выкуп»: «Сын Человеческий… пришёл… чтобы отдать душу Свою для искупления многих» ([[Мф 20:28]]).</p>
   <p>«Христос искупил нас от клятвы закона, сделавшись за нас клятвою» ([[Гал 3:13]]): безгрешный принял на Себя последствия греха, чтобы освободить виновных.</p>
   <p>Важно понимать искупление не грубо. Это не «сделка» с диаволом и не умилостивление гневного, мстительного Бога в языческом смысле, а дело любви Самого Бога, врачующее грех и примиряющее человека с Богом: «Бог во Христе примирил с Собою мир» ([[2 Кор 5:19]]).</p>`, s:SRC.dog},
  {q:"Почему для спасения нужен был Крест?",
   a:`<p>Крест — добровольная жертва совершенной любви и послушания, которой Христос понёс на Себе последствия греха всего человечества: «Он грехи наши Сам вознёс телом Своим на древо» ([[1 Пет 2:24]]). В Кресте таинственно соединились правда Божия (грех осуждён и не оставлен «как ни в чём не бывало») и любовь Божия (грешник помилован и спасён).</p>
   <p>Крест не был внешней необходимостью, навязанной Богу; это путь, свободно избранный любовью, чтобы победить зло не силой, а самоотдачей — изнутри, приняв на Себя всю его тяжесть. «Нет больше той любви, как если кто положит душу свою за друзей своих» ([[Ин 15:13]]).</p>
   <p>Через смерть Христос упразднил смерть: приняв её, безгрешный разрушил её власть изнутри, «смертью смерть поправ».</p>`, s:SRC.dog},
  {q:"Что такое благодать?",
   a:`<p>Благодать — это нетварная спасительная сила и дар Божий, действием Святого Духа возрождающий, освящающий и укрепляющий человека. Она даётся не за заслуги и не как плата, а по любви Божией, даром: «благодатью вы спасены через веру, и сие не от вас, Божий дар» ([[Еф 2:8]]).</p>
   <p>Благодать не есть сотворённая «вещь» и не действует магически, помимо человека; в православном понимании она — Сам Бог в Своих действиях (энергиях), реально исцеляющий природу и подающий силы к добру.</p>
   <p>Без благодати человек не может ни начать, ни продолжить, ни завершить спасения; но и благодать не спасает человека без его свободного согласия и труда.</p>`, s:SRC.dog},
  {q:"Как соотносятся благодать и свобода человека?",
   a:`<p>Спасение совершается как <em>синергия</em> — соработничество Божией благодати и свободного произволения человека. Это средний путь между двумя крайностями: между учением, будто человек спасается сам, своими силами (пелагианство), и учением, будто всё совершает одна благодать, а человек пассивен и предопределён.</p>
   <p>Благодать всегда предваряет, зовёт и даёт силы, но не насилует воли; человек же должен свободно ответить и трудиться: «мы соработники у Бога» ([[1 Кор 3:9]]). Образ этого — виноградная лоза и ветви: жизнь идёт от лозы (Христа), но ветвь должна пребывать на ней и приносить плод ([[Ин 15:5]]).</p>
   <p>Итог: ни благодать без свободы, ни свобода без благодати не спасают — спасает их живое согласие.</p>`, s:SRC.dog},
  {q:"Спасаемся ли мы верой или делами?",
   a:`<p>Спасает вера — но живая, действующая любовью ([[Гал 5:6]]) и приносящая плоды. Дела не «покупают» спасение и не заслуживают его как плату за труд, но необходимы как проявление и свидетельство подлинной веры; вера без них оказывается мёртвой и недействительной.</p>
   <p>Кажущееся противоречие между апостолами на деле — единство. Апостол Павел учит, что человек оправдывается верой, а не делами <em>закона</em> ([[Рим 3:28]]), — то есть спасение не заработать обрядовой праведностью. Апостол Иаков дополняет: «вера без дел мертва» ([[Иак 2:26]]), — то есть истинная вера непременно проявляется в делах любви.</p>
   <p>Итог: спасает благодать, принимаемая живой верой, а живая вера неотделима от добрых дел, как огонь от тепла.</p>`, s:SRC.dog},
  {q:"Что такое оправдание?",
   a:`<p>Оправдание — это дарованное Богом во Христе прощение грехов и принятие человека в милость, соединённое с внутренним обновлением и началом новой жизни. В православном понимании оправдание неотделимо от освящения: Бог не только «объявляет» грешника праведным юридически, но и реально претворяет, исцеляет и обновляет его.</p>
   <p>«Оправдавшись верою, мы имеем мир с Богом через Господа нашего Иисуса Христа» ([[Рим 5:1]]). Начало оправдания подаётся в крещении, где человек омывается от грехов и облекается во Христа, а возрастает оно во всей последующей христианской жизни.</p>`, s:SRC.dog},
  {q:"Что такое освящение?",
   a:`<p>Освящение — это постепенное преображение верующего благодатью Святого Духа: возрастание в святости, очищение от страстей, укрепление в добродетелях и всё большее уподобление Христу. Если оправдание — начало новой жизни, то освящение — её возрастание.</p>
   <p>Это — цель и главное содержание всей христианской жизни: «воля Божия есть освящение ваше» ([[1 Фес 4:3]]); «старайтесь… иметь святость, без которой никто не увидит Господа» ([[Евр 12:14]]).</p>
   <p>Совершается освящение через таинства, молитву, борьбу со грехом и дела любви — при непрестанном действии благодати. Оно начинается в крещении и не завершается в этой жизни, устремляясь к совершенству, которое раскроется в вечности.</p>`, s:SRC.dog},
  {q:"Что такое обо́жение (теосис)?",
   a:`<p>Обожение — высшая цель спасения: приобщение человека к Божественной жизни, когда он по благодати становится «причастником Божеского естества» ([[2 Пет 1:4]]). Это не превращение человека в Бога по существу (что невозможно — тварь не может стать Творцом), а всецелое приобщение нетварной благодати, силе и любви Божией.</p>
   <p>Отцы выразили это дерзновенно, но точно: «Бог стал человеком, чтобы человек стал богом» — по благодати, а не по природе. Классический образ: обоженный человек весь пронизан благодатью, как раскалённое железо — огнём; железо остаётся железом, но всё светится и жжёт, как огонь.</p>
   <p>К обожению призван каждый, а не только святые подвижники: «будьте совершенны, как совершен Отец ваш Небесный» ([[Мф 5:48]]).</p>`, s:SRC.pred},
  {q:"Спасение уже совершилось или ещё продолжается?",
   a:`<p>И то и другое, и это не противоречие, а разные стороны одного дела. Объективно спасение <em>уже совершено</em> Христом раз навсегда: искупление, победа над смертью, открытие пути к Богу — это совершившаяся данность, не зависящая от нас.</p>
   <p>Но каждому человеку это спасение ещё предстоит <em>усвоить</em> лично и в нём <em>пребыть</em> до конца. Поэтому Писание говорит о спасении в трёх временах: мы спасены (в крещении), спасаемся (в течение жизни) и будем спасены (в вечности).</p>
   <p>Оттого апостол пишет уже верующим, крещёным людям: «со страхом и трепетом совершайте своё спасение» ([[Флп 2:12]]) — не потому что оно под сомнением, а потому что его надо свободно и деятельно принимать всю жизнь.</p>`, s:SRC.dog},
  {q:"Может ли спасённый снова погибнуть?",
   a:`<p>Да — спасение не есть безусловная «гарантия», действующая помимо свободы человека. Приобщившийся благодати может отпасть от неё нерадением, тяжким и нераскаянным грехом, отречением от веры. Именно поэтому Писание постоянно предостерегает и призывает к бодрствованию, а не к самоуверенности.</p>
   <p>«Кто думает, что он стоит, берегись, чтобы не упасть» ([[1 Кор 10:12]]); «будь верен до смерти, и дам тебе венец жизни» ([[Откр 2:10]]). Отсюда и трезвение, и отсутствие ложной уверенности в своей «безусловной избранности».</p>
   <p>Но и отпавший не отвергнут навсегда: он может восстать покаянием, ибо двери милосердия Божия открыты до конца жизни. Пример — апостол Пётр, отрёкшийся и восстановленный.</p>`, s:SRC.dog},
  {q:"Спасутся ли те, кто не слышал о Христе?",
   a:`<p>Окончательный суд принадлежит одному Богу, «Который хочет, чтобы все люди спаслись и достигли познания истины» ([[1 Тим 2:4]]). Церковь твёрдо возвещает, что спасение дано во Христе и через Него, но не берётся ни ограничивать милость Божию, ни выносить приговоры о вечной участи неведавших.</p>
   <p>Апостол говорит, что язычники, не имевшие писаного закона, будут судимы по совести и по тому свету истины, который они имели: они «сами себе закон… дело закона у них написано в сердцах» ([[Рим 2:14]]).</p>
   <p>Наше дело — не гадать о чужой участи и не отчаиваться в милосердии Божием, а возвещать Евангелие всем и вверять всех благости и правде Того, Кто «нелицеприятен» ([[Деян 10:34]]).</p>`, s:SRC.dog}
 ]
},

/* ============================ 10. ПНЕВМАТОЛОГИЯ ============================ */
{
 id:"pnevmatologiya", title:"Учение о Святом Духе",
 sub:"Пневматология: Дух Святой и Его действие",
 qa:[
  {q:"Кто такой Святой Дух?",
   a:`<p>Святой Дух — третье Лицо Пресвятой Троицы, истинный Бог, единосущный Отцу и Сыну, предвечно исходящий от Отца. Символ веры именует Его «Господом Животворящим» — Тем, Кто подаёт, поддерживает и обновляет всякую жизнь, тварную и духовную.</p>
   <p>Важно: Дух не безличная «сила», «энергия» или «влияние», а Личность, наравне с Отцом и Сыном. Он говорит, посылает, наставляет, ходатайствует, скорбит, раздаёт дары «каждому особо, как Ему угодно» ([[1 Кор 12:11]]) — всё это свойственно лицу, а не безличной силе.</p>
   <p>Его дело в домостроительстве спасения — освящать: совершать таинства, оживотворять Церковь, наставлять её «на всякую истину» ([[Ин 16:13]]) и вести каждого верующего к святости.</p>`, s:SRC.dog},
  {q:"Что такое Пятидесятница?",
   a:`<p>Пятидесятница — сошествие Святого Духа на апостолов в пятидесятый день по Воскресении Христовом, в виде огненных языков ([[Деян 2:3]]). Исполнившись Духа, прежде боязливые апостолы стали безбоязненно проповедовать воскресшего Христа, и в тот день по проповеди Петра крестилось около трёх тысяч человек.</p>
   <p>С этого события начинается открытая, видимая жизнь Церкви в мире, потому Пятидесятницу и называют днём её рождения: приготовленная Христом и приобретённая Его Кровью, Церковь оживотворяется теперь Духом.</p>
   <p>Праздник этот, называемый также Троицыным днём, прославляет полноту откровения Святой Троицы: Отец послал Сына, а по Вознесении Сына от Отца сошёл Дух.</p>`, s:SRC.ist},
  {q:"Как Дух Святой действует в Церкви?",
   a:`<p>Дух Святой — как бы душа Церкви: Он пребывает в ней постоянно, совершает таинства, поставляет через рукоположение служителей, подаёт дары, наставляет в истине и освящает верующих. Всё живое, святое и спасительное в Церкви — действие Духа, а не человеческие силы.</p>
   <p>Церковь есть храм, в котором «Дух Божий живёт» ([[1 Кор 3:16]]). Дух действует и в соборном разуме Церкви: определение Апостольского собора выражено словами «угодно Святому Духу и нам» ([[Деян 15:28]]) — сначала Духу, затем людям.</p>
   <p>Поэтому вне Церкви и её таинств полнота благодатной жизни в Духе неполна: Дух и Церковь неразделимы.</p>`, s:SRC.dog},
  {q:"Что такое дары Святого Духа?",
   a:`<p>Дары Духа — благодатные способности и силы, подаваемые верующим «на пользу» — для служения и созидания Церкви ([[1 Кор 12:7]]). Апостол подчёркивает: дары различны, служения различны, но Дух один, и Он разделяет их «каждому особо, как Ему угодно».</p>
   <p>Пророк Исаия перечисляет семь даров Духа, почивших на Мессии: премудрости, разума, совета, крепости, ведения, благочестия и страха Божия ([[Ис 11:2]]) — их же подаёт Дух и верующим в миропомазании.</p>
   <p>Дары даются не для превозношения и не в награду за достоинство, а для служения ближним; и высший путь, без которого все дары ничто, — любовь: «если имею дар пророчества… а не имею любви, — то я ничто» ([[1 Кор 13:2]]).</p>`, s:SRC.dog},
  {q:"Что такое плоды Духа?",
   a:`<p>Плоды Духа — это черты и свойства обновлённой Им жизни, признаки Его действия в человеке, которые вырастают в душе, как плод на здоровом дереве. Апостол перечисляет их: «плод же духа: любовь, радость, мир, долготерпение, благость, милосердие, вера, кротость, воздержание» ([[Гал 5:22]]).</p>
   <p>В отличие от даров, которые различны у разных людей и даются не всем, плоды Духа призваны возрастать в каждом христианине без исключения. И именно по ним, а не по внешним, ярким знамениям, вернее всего распознаётся подлинное действие Духа — как дерево познаётся по плодам ([[Мф 7:16]]).</p>`, s:SRC.pis},
  {q:"Когда христианин получает дар Святого Духа?",
   a:`<p>Личная печать дара Духа Святого подаётся каждому верующему в таинстве миропомазания, совершаемом сразу по крещении. В апостольское время Дух низводился через возложение рук апостолов ([[Деян 8:17]]); поскольку они не могли лично возложить руки на всех новокрещёных по всей вселенной, установилось помазание освящённым миром, которое совершает священник.</p>
   <p>С этого дара начинается личная духовная жизнь христианина. Но полученный дар нужно возгревать и приносить его плоды всю жизнь, а не «получить и забыть»: «Духа не угашайте» ([[1 Фес 5:19]]); «напоминаю тебе возгревать дар Божий, который в тебе» ([[2 Тим 1:6]]).</p>`, s:SRC.dog},
  {q:"Чем отличается действие Духа от ложных «духовных» состояний?",
   a:`<p>Не всякое яркое «духовное» переживание — от Бога; апостол прямо предостерегает: «не всякому духу верьте, но испытывайте духов, от Бога ли они» ([[1 Ин 4:1]]). Есть опасность принять за благодать разгорячённое воображение, действие страстей или даже обольщение от духов лжи.</p>
   <p>Верные признаки действия Святого Духа — согласие с верой Церкви и её Преданием, а также смирение, мир, трезвение и любовь, которые оно рождает. Ложная же духовность обычно узнаётся по противоположному: по гордости, превозношению над другими, смущению, разгорячённости и разделению.</p>
   <p>Мерило дано апостолом: плоды Духа — «любовь, радость, мир» ([[Гал 5:22]]); где вместо них тщеславие, осуждение и мятеж, там действует не Дух Божий. Верное различение подаётся смирением, участием в таинствах и советом опытных в духовной жизни, а не доверием к самому себе.</p>`, s:SRC.dog}
 ]
},

/* ============================ 11. ЭККЛЕЗИОЛОГИЯ ============================ */
{
 id:"ekklesiologiya", title:"Учение о Церкви",
 sub:"Экклезиология: природа, признаки, устройство Церкви",
 qa:[
  {q:"Что такое Церковь?",
   a:`<p>Церковь — это установленное Богом общество верующих, соединённых единой православной верой, законным священноначалием и таинствами, Глава которого — Сам Христос. Это не просто человеческая организация единомышленников, а живой богочеловеческий организм — Тело Христово.</p>
   <p>«Вы — тело Христово, а порознь — члены» ([[1 Кор 12:27]]), — пишет апостол. В этом образе всё существенно: Христос — Глава ([[Еф 1:22]]), верующие — члены, живущие Его жизнью, а Дух Святой — как бы душа, оживляющая это Тело и связующая члены воедино.</p>
   <p>Церковь одновременно земна и небесна: она включает и подвизающихся на земле, и святых на небесах, и составляет единое общение — потому мы и обращаемся к святым как к живым.</p>`, s:SRC.sim},
  {q:"Кто основал Церковь?",
   a:`<p>Церковь основал Сам Господь Иисус Христос. Он прямо сказал: «создам Церковь Мою, и врата ада не одолеют её» ([[Мф 16:18]]). Он приготовил её всей Своей проповедью, избранием апостолов и установлением таинств, приобрёл Своею Кровью ([[Деян 20:28]]) и оживотворил сошествием Святого Духа в Пятидесятницу.</p>
   <p>Отсюда важнейшее следствие: Церковь — не человеческое учреждение, которое можно по своему усмотрению «переустроить», отменить или создать заново, а Божие создание с богоустановленным строем.</p>
   <p>И отсюда же — уверенность в её несокрушимости: раз она основана на Христе, «врата ада не одолеют её», и она пребудет до конца века, как ни колебали бы её гонения, ереси и немощи людей.</p>`, s:SRC.sim},
  {q:"Каковы признаки истинной Церкви?",
   a:`<p>Символ веры называет четыре признака: Церковь <em>едина, свята, соборна (кафолична) и апостольна</em>. Эти четыре свойства принадлежат истинной Церкви Христовой и служат мерилом, по которому её можно узнать среди множества сообществ, называющих себя христианскими.</p>
   <p>Они не случайны, а вытекают из самой её природы как Тела Христова: она едина, потому что един Христос; свята, потому что свят освящающий её Дух; соборна, потому что объемлет полноту истины для всех; апостольна, потому что хранит апостольскую веру и преемство.</p>
   <p>Единство её апостол выражает так: «одно тело и один дух… один Господь, одна вера, одно крещение» ([[Еф 4:4]]). Остальные три признака раскрываются в следующих вопросах.</p>`, s:SRC.dog},
  {q:"Почему Церковь едина?",
   a:`<p>Церковь едина, потому что един её Глава — Христос, един оживляющий её Святой Дух, едина истинная вера и едины таинства. Множество поместных Церквей и множество верующих не нарушают этого единства, как множество членов не разделяет единого живого тела.</p>
   <p>Единство Церкви — предмет прямой молитвы Христовой на Тайной вечере: «да будут все едино, как Ты, Отче, во Мне, и Я в Тебе, так и они да будут в Нас едино» ([[Ин 17:21]]). Единство это — не внешнее и не административное только, а таинственное единство жизни во Христе.</p>
   <p>Поэтому расколы и разделения глубоко противны самой природе Церкви, и апостол умоляет верующих «сохранять единство духа в союзе мира» ([[Еф 4:3]]).</p>`, s:SRC.sim},
  {q:"Почему Церковь свята, если в ней есть грешники?",
   a:`<p>Церковь свята не безгрешностью всех своих членов, а святостью своего Главы — Христа, святостью живущего в ней Духа, святостью её вероучения и таинств, которые освящают людей. «Христос возлюбил Церковь и предал Себя за неё, чтобы освятить её… чтобы она была свята и непорочна» ([[Еф 5:25]]).</p>
   <p>Присутствие в Церкви грешников не отменяет её святости, потому что Церковь — не собрание уже достигших совершенства, а врачебница, исцеляющая приходящих кающихся. Господь уподобил её полю, где до жатвы растут вместе пшеница и плевелы ([[Мф 13:30]]), и неводу, захватившему рыб всякого рода.</p>
   <p>Грешники в Церкви — не доказательство её нечистоты, а те, кто призван и врачуется; отпадают же от неё по существу лишь упорствующие во грехе и в ереси без покаяния.</p>`, s:SRC.dog},
  {q:"Что значит «соборная» (кафолическая) Церковь?",
   a:`<p>Соборность, или кафоличность (от греч. «кат-холон» — «по всему», «согласно целому»), означает полноту и всеобщность Церкви. Она не привязана к одному народу, месту, языку или времени, объемлет верующих всех стран и эпох и хранит всю полноту истины и благодати, а не частицу её.</p>
   <p>Церковь послана научить и крестить «все народы» ([[Мф 28:19]]) — в этом её вселенский размах. Но кафоличность — не только количественная всемирность, но и качественная полнота: в каждой православной общине, собранной вокруг епископа и Евхаристии, присутствует не «часть», а вся полнота Церкви.</p>
   <p>Проявляется соборность и в самом способе жизни и решений: не по воле одного лица, а в согласии всей Церкви, руководимой Духом, особенно на соборах.</p>`, s:SRC.sim},
  {q:"Что значит «апостольская» Церковь?",
   a:`<p>Церковь апостольская в двух неразрывных смыслах. Во-первых, по <em>вере</em>: она хранит неповреждённым то учение, которое приняла от апостолов, ничего не убавляя и не прибавляя к нему по своеволию. Во-вторых, по <em>преемству</em>: в ней сохраняется непрерывная передача благодатного служения, идущая от апостолов через рукоположение епископов.</p>
   <p>Она «утверждена на основании апостолов и пророков, имея Самого Иисуса Христа краеугольным камнем» ([[Еф 2:20]]).</p>
   <p>Апостольство — надёжный признак подлинности: истинна не та община, что заново «изобретает» веру, а та, что учит тому же, чему учили апостолы, и восходит к ним по непрерывному преемству.</p>`, s:SRC.dog},
  {q:"Что такое апостольское преемство?",
   a:`<p>Апостольское преемство — это непрерывная, из рода в род, передача благодати священства и полномочий учить и совершать таинства, идущая от апостолов к их преемникам-епископам через рукоположение (возложение рук). Благодаря ему нынешние епископы связаны с апостолами живой, непрерванной цепью.</p>
   <p>Основание его — в Писании: апостолы поставляли епископов и пресвитеров по церквам ([[Деян 14:23]]) и заповедали им поставлять достойных преемников: «что слышал от меня… передай верным людям, которые были бы способны и других научить» ([[2 Тим 2:2]]).</p>
   <p>Уже священномученик Ириней Лионский во II веке указывал на это преемство как на надёжный признак истинной Церкви против еретиков: истину хранят там, где сохранилось непрерывное преемство от апостолов.</p>`, s:SRC.dog+" · "+SRC.ist},
  {q:"Зачем в Церкви иерархия?",
   a:`<p>Церковная иерархия установлена не людьми, а Самим Христом, Который избрал апостолов и дал им власть учить, священнодействовать и пасти стадо; через них это служение передаётся дальше. Иерархия — не «начальствование» ради власти и не сословная привилегия, а служение ради спасения других.</p>
   <p>Апостол напоминает пастырям: «Дух Святый поставил вас блюстителями, пасти Церковь Господа и Бога» ([[Деян 20:28]]) — то есть их власть от Духа и для служения. Сам Господь заповедал: «кто хочет между вами быть большим, да будет вам слугою» ([[Мф 20:26]]).</p>
   <p>Иерархия хранит единство Церкви, чистоту веры, порядок в таинствах и преемство от апостолов. Существуют три богоустановленные степени священства — епископ, пресвитер и диакон.</p>`, s:SRC.dog},
  {q:"Чем различаются епископ, пресвитер и диакон?",
   a:`<p><em>Епископ</em> — высшая степень священства, обладающая всей его полнотой. Только епископ имеет право рукополагать (поставлять пресвитеров и диаконов) и управляет поместной Церковью (епархией); он — средоточие её единства и хранитель преемства.</p>
   <p><em>Пресвитер</em> (священник) совершает все таинства, кроме рукоположения, но не самовластно, а в подчинении своему епископу и по его благословению: крестит, исповедует, совершает Евхаристию в своём приходе.</p>
   <p><em>Диакон</em> служит при богослужении и таинствах, помогает епископу и пресвитеру, возглашает ектеньи и читает Евангелие, но сам таинств не совершает. Это трёхстепенное устройство восходит к апостольскому веку и неизменно хранится в Церкви.</p>`, s:SRC.dog},
  {q:"Как решаются спорные вопросы в Церкви?",
   a:`<p>Важнейшие вопросы веры и церковного порядка решаются соборно — не единоличной властью, а согласием епископов, выражающим разум всей Церкви, руководимой Духом Святым. Соборность — не голосование большинства ради победы партии, а совместное искание и исповедание истины.</p>
   <p>Образец дан ещё апостолами на Иерусалимском соборе, разрешившем первый крупный спор в Церкви; его определение начиналось знаменательными словами: «угодно Святому Духу и нам» ([[Деян 15:28]]) — сначала Духу, потом собравшимся.</p>
   <p>Высший авторитет в вопросах вероучения принадлежит Вселенским соборам, чьи догматические определения Церковь принимает как непогрешимое выражение своей веры.</p>`, s:SRC.ist},
  {q:"Что такое Вселенские соборы?",
   a:`<p>Вселенские соборы — собрания епископов всей Церкви (или их полномочных представителей) для решения важнейших вопросов веры и осуждения ересей. Их вероучительные определения (догматы) и правила (каноны) Церковь принимает как выражение своей веры, а не как частные мнения.</p>
   <p>Православная Церковь признаёт семь Вселенских соборов (325–787 гг.). Они соборно раскрыли и оградили учение о Святой Троице (Первый и Второй), о едином Лице и двух природах Христа (Третий–Шестой) и о почитании икон (Седьмой).</p>
   <p>Догматические определения этих соборов Церковь исповедует непогрешимыми и неизменными — не потому что епископы сами по себе непогрешимы, а потому что в согласном исповедании всей Церкви действует обещанный ей Дух истины.</p>`, s:SRC.ist},
  {q:"Как относиться к Священному Преданию?",
   a:`<p>Священное Предание — это живая передача веры в Церкви от апостолов доныне. Оно включает Писание, вероопределения соборов, творения святых отцов, богослужение, каноны, иконопись — всё, чем Дух Святой хранит, передаёт и раскрывает истину из поколения в поколение.</p>
   <p>Предание и Писание неразделимы: Писание есть записанная, важнейшая часть единого Предания, а Предание — тот живой церковный поток, внутри которого Писание было создано и в котором только и понимается верно.</p>
   <p>Апостол прямо велит: «стойте и держите предания, которым вы научены или словом, или посланием нашим» ([[2 Фес 2:15]]). Предание — не «человеческие добавки» к Писанию (их Господь как раз осуждал), а сама апостольская вера в её полноте и жизни.</p>`, s:SRC.dog},
  {q:"Что такое поместная и Вселенская Церковь?",
   a:`<p>Вселенская (Кафолическая) Церковь — единая Церковь Христова во всех местах и временах. Поместные Церкви — её части в отдельных странах и народах (например, Русская, Сербская, Элладская), соединённые единством веры, таинств и канонического общения при равночестии своих епископов.</p>
   <p>Важно, что каждая поместная Церковь — не «кусок» раздробленной Церкви, а полнота Церкви на данном месте: там, где законный епископ и Евхаристия, присутствует вся Церковь Христова. Единство между поместными Церквами — не подчинение одному земному главе, а общение в единой вере и таинствах.</p>
   <p>Этим православное устройство отличается от строя с единым видимым главой над всей Церковью: единая Глава Церкви — Христос, а первенство чести между Церквами не есть власть над ними.</p>`, s:SRC.sim},
  {q:"В чём причины разделения Церквей 1054 года?",
   a:`<p>1054 год — символический рубеж «Великого раскола», разделения христианского мира на Западную (Римско-Католическую) и Восточную (Православную) Церкви. В этом году папские легаты и Константинопольский патриарх обменялись взаимными отлучениями.</p>
   <p>Причины копились веками и были разнородны. <em>Вероучительная</em> — самовольное внесение Западом в общий Символ веры прибавки filioque (об исхождении Духа «и от Сына»). <em>Каноническая</em> — растущие притязания Римского епископа на единоличную власть над всей Церковью, тогда как Восток признавал за ним лишь первенство чести как «первого среди равных». Добавлялись обрядовые различия (опресноки, посты, безбрачие духовенства) и глубокое культурно-политическое отдаление латинского Запада и греческого Востока.</p>
   <p>1054 год лишь обозначил разрыв; окончательным его сделали позднейшие события, в особенности разграбление Константинополя крестоносцами в 1204 году.</p>`, s:SRC.ist},
  {q:"Из чего слагается состав Церкви?",
   a:`<p>Филарет даёт такое определение: Церковь Христова есть общество верующих во Христа, установленное Господом, соединённое словом Божиим, таинствами и священноначалием, под управлением Духа Святого, для вечного спасения.</p>
<p>Такое понятие видно в словах апостола: «вси едино тело есмы: от единаго бо хлеба причащаемся... единем Духом мы вси во едино тело крестихомся... и вси единем Духом напоихомся» ([[1 Кор 10:17]]; [[1 Кор 12:13]]); «внимайте себе и всему стаду, в немже вас Дух Святый постави епископы, пасти Церковь Господа и Бога» ([[Деян 20:28]]).</p>
<p>Как во всяком обществе людей различаем невидимый дух и видимое тело, так и Церковь составляется из духа и тела. И как душа и тело связаны между собою, действуя друг на друга, так и в Церкви невидимый Дух животворно действует на видимый организм, а организм этот то более, то менее благоугодно Духу отправляет свои действия. Поэтому Церковь нельзя свести ни к одной невидимой общине верующих, ни к одному видимому учреждению.</p>`, s:SRC.dog+" · §292"},
  {q:"Что значит, что Христос — Глава Церкви?",
   a:`<p>Господь не только Сам основал Церковь Свою, но Сам же есть и Глава её, оживляя её благодатью Духа Святого.</p>
<p>Он Сам сказал: «Аз есмь пастырь добрый», и всех, кто по гласу Его придёт во двор овчий, наименовал единым стадом Своим ([[Ин 10:11]]; [[Ин 10:16]]). Сам сказал, что не оставит сирыми Своих исповедников, но будет всегда пребывать с ними и подкреплять их ([[Ин 14:18]]; [[Мф 28:20]]), что Его именем они будут преодолевать все препятствия ([[Мк 16:17]]; [[Ин 16:33]]).</p>
<p>Апостолы дознали это опытом и передали как истину Божию: Бог «Того даде главу выше всех Церкви, яже есть Тело Его» ([[Еф 1:22]]; [[Кол 1:18]]). Отсюда следует важное: глава Церкви — не человек и не учреждение; всякое церковное служение есть служение при Главе, а не вместо Неё.</p>`, s:SRC.dog+" · §294"},
  {q:"В чём назначение Церкви?",
   a:`<p>Церковь Христова не может иметь другого назначения, кроме спасения людей грешных — того самого спасения, для которого назначена и сама истина Христова.</p>
<p>Апостол говорит о назначении церковного союза: «истинствующе же в любви, да возрастим в Него всяческая, Иже есть глава, Христос» ([[Еф 4:15]]). И он же учит: «Христос возлюби Церковь, и Себе предаде за ню, да освятит ю» ([[Еф 5:25]]) — следовательно, святость есть цель, которой по воле Господа должна достигать Церковь данными ей средствами.</p>
<p>Указаны и самые средства: «Той дал есть овы убо апостолы, овы же пророки, овы же благовестники, овы же пастыри и учители, к совершению святых, в дело служения, в созидание Тела Христова, дондеже достигнем вси в соединение веры и познания Сына Божия, в мужа совершенна, в меру возраста исполнения Христова» ([[Еф 4:11]]). Цель, таким образом, — полное познание Сына Божия и духовное совершенство человека; средства — определённые Богом строители тайн Божиих.</p>`, s:SRC.dog+" · §295"},
  {q:"Непогрешима ли поместная Церковь?",
   a:`<p>Нет. Непрерывное продолжение святой Церкви и её неуклонность от истины относятся к Церкви Вселенской, но не к церквам частным. Последние изображаются в Апокалипсисе под образом светильников, в которых может оскудевать и свет истины, и елей любви; они могут быть «двинуты от места своего» ([[Откр 2:5]]), то есть исчезнуть там, где существовали. Ходящий посреди светильников златых ([[Откр 2:1]]) может переносить их из одной страны в другую и вновь возжигать свет их.</p>
<p>Точно так же и непогрешимость составляет отличительную принадлежность только Церкви Вселенской. Частная Церковь, каким бы именем она себя ни величала, тогда только по праву называется правоверующею и способною судить правильно, когда строго следует суду Вселенской Церкви.</p>
<p>Отсюда Филарет делает вывод и о конкретном случае: Римская церковь, гордо присвоив себе звание непогрешимой, гордостью доведена была до того, что освятила разные заблуждения. Иными словами, ошибка здесь не только догматическая, но и нравственная — подмена соборного суда самоуверенностью части.</p>`, s:SRC.dog+" · §297–298"},
  {q:"Оскудеет ли вера на земле перед концом мира?",
   a:`<p>Спаситель спрашивает: «Сын Человеческий пришед убо обрящет ли веру на земли?» ([[Лк 18:8]]); апостол предсказывает отступление ([[2 Фес 2:3]]). Недостаток веры при кончине мира, признаёт Филарет, без сомнения будет велик, как не бывало в другое время, — ибо тогда «за умножение беззакония, изсякнет любы многих» ([[Мф 24:12]]).</p>
<p>Но и это последнее потрясение Церкви Христовой ещё не есть уничтожение веры в целой Церкви. Это будет ослабление веры в огромной массе людей, испорченных пороками. Однако «многие», как бы много их ни было, — не то же, что «все»; да и любовь иссякнет, по слову Спасителя, только во многих. Самый тон, каким произнесён вопрос Господа, показывает скорбь о состоянии людей, а не приговор об исчезновении Церкви.</p>
<p>Кроме того, апостол предсказывает перед кончиной мира обращение ко Христу иудеев и язычников ([[Рим 11:25]]), — а это ещё яснее говорит о непрерывном сохранении веры в Церкви Христовой до конца мира.</p>`, s:SRC.dog+" · §298"}
 ]
},

/* ============================ 12. САКРАМЕНТОЛОГИЯ ============================ */
{
 id:"sakramentologiya", title:"Учение о таинствах",
 sub:"Сакраментология: семь таинств Церкви",
 qa:[
  {q:"Что такое таинство?",
   a:`<p>Таинство — это священное действие Церкви, в котором под видимым знаком (вещество, слова, обряд) верующему подаётся невидимая спасительная благодать Святого Духа. В таинстве неразрывно соединены видимое и невидимое, как в Самом Христе — человечество и Божество.</p>
   <p>Существенно, что таинства установлены Самим Богом, а не выдуманы людьми, и совершаются в Церкви законным, преемственно рукоположенным священством. Поэтому они — не просто благочестивые символы или напоминания, а действительные проводники благодати, реально изменяющие человека.</p>
   <p>Таинства охватывают всю жизнь христианина — от рождения (крещение) до болезни и смертного одра (елеосвящение), — освящая её на каждом важнейшем рубеже.</p>`, s:SRC.dog},
  {q:"Сколько таинств в Церкви?",
   a:`<p>Церковь издревле совершала многие священнодействия, но собственно таинствами почитает семь: крещение, миропомазание, евхаристию (причащение), покаяние, священство, брак и елеосвящение. Число семь окончательно закрепилось в церковном сознании.</p>
   <p>Каждое из них подаёт особую благодать на определённом рубеже духовной жизни: рождение в новую жизнь (крещение), укрепление в ней силою Духа (миропомазание), питание Телом и Кровью Христовыми (евхаристия), исцеление от грехов, совершённых по крещении (покаяние), исцеление от болезней (елеосвящение), освящение церковного служения (священство) и семейного союза (брак).</p>
   <p>Так вся полнота человеческой жизни — личной, церковной и семейной — вводится в область благодати.</p>`, s:SRC.dog},
  {q:"Что подаётся в крещении?",
   a:`<p>В крещении человек духовно рождается в новую жизнь, очищается от всех прежних грехов, в том числе от первородного повреждения, и вводится в Церковь как член Тела Христова. Троекратное погружение в воду с призыванием Троицы знаменует смерть для греха и совоскресение со Христом: «мы погреблись с Ним крещением в смерть, дабы… и нам ходить в обновлённой жизни» ([[Рим 6:4]]).</p>
   <p>Сам Господь установил его необходимость в беседе с Никодимом: «если кто не родится от воды и Духа, не может войти в Царствие Божие» ([[Ин 3:5]]). Крещёный «во Христа облекается» ([[Гал 3:27]]), становясь новым творением.</p>
   <p>Таинство это совершается единожды и неповторимо — как единожды рождается человек; потому и не повторяется над теми, кто уже крещён во имя Троицы.</p>`, s:SRC.dog},
  {q:"Почему крестят младенцев?",
   a:`<p>Младенцев крестят по вере родителей и восприемников (крёстных), которые берут на себя обязательство воспитать их в вере. Как дети наследуют повреждённую грехом природу и смертность, так и им нужно духовное возрождение и вхождение в Церковь; нет основания лишать их благодати до некоего «сознательного возраста».</p>
   <p>Господь звал детей к Себе и негодовал на препятствовавших: «пустите детей приходить ко Мне и не препятствуйте им, ибо таковых есть Царствие Божие» ([[Мк 10:14]]). Апостолы крестили целые «дома́» ([[Деян 16:15]]), куда по обычаю входили и дети.</p>
   <p>Древняя Церковь всегда крестила младенцев; это не позднее нововведение, а исконная практика, основанная на том, что спасение — дар Божий, а не награда за собственные заслуги, которых у младенца ещё нет, но нет у него и у взрослого.</p>`, s:SRC.dog},
  {q:"Заменило ли крещение ветхозаветное обрезание?",
   a:`<p>Да, для христиан крещение заступило место ветхозаветного обрезания как знак вступления в завет с Богом и в народ Божий. Апостол Павел прямо связывает их, называя крещение «обрезанием нерукотворенным» — «обрезанием Христовым», совершаемым не над плотью, а над сердцем ([[Кол 2:11]]).</p>
   <p>Но при сходстве знака есть и глубокое различие в силе: обрезание лишь вводило в ветхий завет и было внешним знаком принадлежности к народу, а крещение реально очищает от грехов, возрождает и подаёт благодать — то, чего обрезание не давало.</p>
   <p>Кроме того, крещение, в отличие от обрезания, преподаётся всем — и мужчинам, и женщинам, всякому народу, — что отвечает вселенскому характеру Церкви.</p>`, s:SRC.dog},
  {q:"Что подаётся в миропомазании?",
   a:`<p>В миропомазании новокрещёному подаётся печать дара Святого Духа для укрепления, возрастания и утверждения в новой, благодатной жизни. Соотношение с крещением такое: если в крещении человек рождается, то в миропомазании получает силы Духа для жизни и подвига — как бы «духовное совершеннолетие» и вооружение.</p>
   <p>В апостольское время Дух низводился через возложение рук апостолов ([[Деян 8:17]]). Поскольку они не могли лично возлагать руки на всех, установилось помазание особо освящённым миром, которое совершает священник, произнося: «Печать дара Духа Святаго».</p>
   <p>Основание — в словах апостола: «Утверждающий же нас с вами во Христе и помазавший нас есть Бог, Который и запечатлел нас и дал залог Духа в сердца наши» ([[2 Кор 1:21]]).</p>`, s:SRC.dog},
  {q:"Что такое Евхаристия?",
   a:`<p>Евхаристия (греч. «благодарение»), или Причащение, — важнейшее из таинств, в котором хлеб и вино действием Святого Духа прелагаются (претворяются) в истинные Тело и Кровь Христовы, и верующие причащаются их во оставление грехов и в жизнь вечную.</p>
   <p>Господь установил это таинство на Тайной вечере накануне Своих страданий, подав ученикам хлеб: «приимите, ядите: сие есть Тело Моё», и чашу: «пейте из неё все, ибо сие есть Кровь Моя нового завета, за многих изливаемая во оставление грехов» ([[Мф 26:26]]), и заповедал: «сие творите в Моё воспоминание» ([[Лк 22:19]]).</p>
   <p>Евхаристия — средоточие и вершина всей жизни Церкви: в ней Церковь являет себя как единое Тело Христово и теснее всего соединяется со своим Главой.</p>`, s:SRC.dog},
  {q:"Евхаристия — это только воспоминание Тайной вечери?",
   a:`<p>Нет. Это не просто обряд в память о прошедшем событии и не одно лишь символическое изображение. В Евхаристии верующие действительно причащаются истинных Тела и Крови Христовых. Господь говорил об этом прямо и настойчиво, не смягчая слов даже тогда, когда они соблазнили многих слушателей: «ядущий Мою Плоть и пиющий Мою Кровь имеет жизнь вечную» ([[Ин 6:54]]).</p>
   <p>Вместе с тем Евхаристия есть и <em>воспоминание</em> («сие творите в Моё воспоминание»), и <em>благодарение</em>, и бескровная <em>жертва</em>, в которой приносится и подаётся верным единая Жертва Христова, принесённая однажды на Кресте.</p>
   <p>«Воспоминание» здесь — не просто мысль о далёком прошлом, а таинственное соучастие: спасительное событие делается настоящим и действенным для причащающихся.</p>`, s:SRC.dog},
  {q:"Зачем нужно причащаться?",
   a:`<p>Причащение теснейшим образом соединяет человека со Христом, питает и укрепляет его духовно, очищает грехи, подаёт залог вечной жизни и воскресения и соединяет верующих между собою в одно Тело. «Пребывающий во Мне, и Я в нём, тот приносит много плода» ([[Ин 15:5]]); «один хлеб, и мы многие одно тело; ибо все причащаемся от одного хлеба» ([[1 Кор 10:17]]).</p>
   <p>Без причащения духовная жизнь оскудевает и замирает, поэтому Господь сказал со всей определённостью: «если не будете есть Плоти Сына Человеческого и пить Крови Его, то не будете иметь в себе жизни» ([[Ин 6:53]]).</p>
   <p>Приступать к таинству должно с верой, покаянием, примирением с ближними и должным приготовлением, «испытывая себя», ибо кто причащается недостойно, «тот ест и пьёт осуждение себе» ([[1 Кор 11:28]]).</p>`, s:SRC.dog},
  {q:"Что такое таинство покаяния?",
   a:`<p>Покаяние — таинство духовного исцеления, в котором крещёный, искренне исповедуя свои грехи перед Богом при свидетеле-священнике, получает от Самого Бога прощение и разрешение от грехов. Священник здесь — не судья по своей власти и не «посредник», отбирающий что-то у Бога, а служитель и свидетель, которому Христос дал власть свидетельствовать прощение.</p>
   <p>Господь дал апостолам, а через них Церкви, эту власть по Воскресении: «примите Духа Святаго. Кому простите грехи, тому простятся; на ком оставите, на том останутся» ([[Ин 20:23]]).</p>
   <p>Покаяние возвращает человеку благодать, утраченную в грехах по крещении, потому отцы называют его «вторым крещением» и «крещением слёз».</p>`, s:SRC.dog},
  {q:"Что нужно для истинного покаяния?",
   a:`<p>Для истинного покаяния нужны несколько условий: осознание своих грехов и искреннее сокрушение о них (а не formalное перечисление), откровенное исповедание без самооправдания и утаивания, твёрдая решимость исправиться и оставить грех, и, наконец, вера в милосердие Божие и надежда на прощение.</p>
   <p>Само слово «покаяние» (греч. «метанойя») означает не просто сожаление о прошлом, а <em>перемену ума</em>, поворот всей жизни: «сотворите же достойный плод покаяния» ([[Мф 3:8]]). Без намерения исправиться исповедь остаётся бесплодной.</p>
   <p>При этом никакая тяжесть и множество грехов не должны ввергать в отчаяние: Бог принимает всякого кающегося с радостью, как отец принял блудного сына — ещё издалека, не дав договорить приготовленные слова ([[Лк 15:20]]).</p>`, s:SRC.dog},
  {q:"Что такое таинство священства?",
   a:`<p>Священство (рукоположение, по-гречески хиротония) — таинство, в котором через молитву и возложение рук епископа правильно избранному мужу подаётся благодать Святого Духа для совершения таинств, учительства и пастырского служения в соответствующей степени (епископа, пресвитера или диакона).</p>
   <p>Основание его — в апостольской практике: апостолы поставляли служителей молитвой и возложением рук ([[Деян 6:6]]); апостол Павел напоминает Тимофею о «даровании, которое дано тебе по пророчеству с возложением рук священства» ([[1 Тим 4:14]]) и увещевает «рук ни на кого не возлагать поспешно» ([[1 Тим 5:22]]).</p>
   <p>Совершать это таинство может только епископ, имеющий апостольское преемство, — потому и хранится непрерывная связь нынешнего священства с апостолами.</p>`, s:SRC.dog},
  {q:"Почему брак — таинство?",
   a:`<p>Супружеский союз мужа и жены установлен не людьми и не обществом, а Самим Богом ещё в раю, до грехопадения: «оставит человек отца своего и мать свою и прилепится к жене своей; и будут двое одна плоть» ([[Быт 2:24]]). В Церкви этот союз освящается благодатью, которая соединяет супругов и подаёт им силы нести общую жизнь в любви, верности и взаимном спасении.</p>
   <p>Апостол Павел возводит христианский брак к высочайшему образу — таинственному союзу Христа и Церкви, и именно поэтому называет его «тайной великой»: «тайна сия велика; я говорю по отношению ко Христу и к Церкви» ([[Еф 5:32]]).</p>
   <p>Христос благословил брак Своим присутствием и первым чудом — претворением воды в вино на браке в Кане Галилейской ([[Ин 2:1]]).</p>`, s:SRC.dog},
  {q:"Что такое елеосвящение (соборование)?",
   a:`<p>Елеосвящение — таинство, в котором при помазании больного освящённым елеем и молитве священников подаётся благодать, исцеляющая немощи души и тела и отпускающая грехи, в том числе забытые или нераскаянные по немощи и беспамятству.</p>
   <p>Оно прямо заповедано в Писании апостолом Иаковом: «болен ли кто из вас, пусть призовёт пресвитеров Церкви, и пусть помолятся над ним, помазав его елеем во имя Господне. И молитва веры исцелит болящего, и восставит его Господь; и если он соделал грехи, простятся ему» ([[Иак 5:14]]).</p>
   <p>По числу совершающих его пресвитеров (обычно семи) таинство называют также «соборованием». Оно подаёт не только телесное исцеление (если то полезно для спасения), но прежде всего исцеление и укрепление души.</p>`, s:SRC.dog},
  {q:"Почему крещение совершается троекратным погружением?",
   a:`<p>И самые слова Спасителя, установляющие крещение, и изображения тайной силы крещения показывают, что видимую сторону крещения должно составлять троекратное погружение крещаемого в воду. Таинственная сила крещения состоит в очищении грехов и в возрождении духа, — и погружение в воду точным образом выражает эту невидимую перемену.</p>
<p>На то же указывает и собственное значение греческих слов βάπτω и βαπτίζω ([[Мк 7:4]]; [[Лк 11:38]]), и сравнения крещения с потопом ([[1 Пет 3:20]]), с погребением Христовым ([[Рим 6:4]]; [[Кол 2:12]]), с переходом сквозь воды моря ([[1 Кор 10:2]]). Апостолы при совершении крещения погружали крещавшихся в воду ([[Деян 8:38]]).</p>
<p>На необходимость именно <em>троекратного</em> погружения указывает число Лиц, во имя Которых совершается крещение. Церковь приняла за правило, чтобы крещение всегда совершалось через погружение; святой Киприан признавал допустимым обливание только над больными — то есть как исключение по нужде, а не как равнозначный образ.</p>`, s:SRC.dog+" · §236"},
  {q:"Какие слова обязательно произносятся при крещении?",
   a:`<p>При торжественном установлении крещения ясно определено, какие слова надобно произносить: «научите вся языки, крестяще их во имя Отца и Сына и Святаго Духа» ([[Мф 28:19]]). Совершающий крещение должен произносить: «крещается во имя Отца и Сына и Святаго Духа», — и тем показывать, что отселе всё упование крещаемого есть Триипостасный Бог, а сам крещаемый обязывается быть исповедником этого имени.</p>
<p>Так понимали заповедь Спасителя апостолы. Когда апостол Павел, найдя в Ефесе некоторых учеников Иоанновых, спросил их, приняли ли они Духа Святого, и они отвечали, что даже не слыхали, есть ли Дух Святой, — он спросил: «во что убо крестистеся?» ([[Деян 19:2]]). Своими словами он указывает на произношение при крещении именно тех слов, которые предписаны Спасителем, а поступком своим даёт видеть, что крещения без произнесения этих слов он не признал крещением христианским.</p>
<p>На ту же необходимость указывает и сама таинственная сила крещения: оно вводит крещаемого в права наследия даров, приобретённых Сыном Божиим от Отца и раздаваемых Духом Святым. Апостол выражает это, говоря, что Христос очистил Церковь «банею водною в глаголе» ([[Еф 5:26]]), то есть баня освящает при посредстве произносимого с верою определённого слова веры.</p>`, s:SRC.dog+" · §236"},
  {q:"Что такое «крещение кровью» и заменяет ли оно таинство?",
   a:`<p>Так называли мученическую смерть за Христа, принятую тем, кто не успел принять крещения водою. Основанием служили слова Спасителя о крещении, которым Он Сам должен креститься ([[Лк 12:50]]; [[Мк 10:38]]), и обетование положившему душу свою ([[Ин 15:13]]).</p>
<p>Однако отцы принимали за правило, чтобы исповедники, не успевшие креститься, крестились водою при первом удобном случае. Из этого видно, замечает Филарет, что по учению отцов законную видимую сторону таинства крещения составляет погружение в воде, и что только в случае неизбежной нужды крещение кровавое может заменять собою собственную видимую сторону крещения.</p>
<p>Иначе говоря, «крещение кровью» — не другое таинство и не отмена установленного порядка, а свидетельство милости Божией там, где исполнение установленного порядка стало физически невозможным. Само правило этим не отменяется, а подтверждается.</p>`, s:SRC.dog+" · §238"},
  {q:"Чем миропомазание отличается от крещения?",
   a:`<p>Миропомазание есть таинство, в котором верующему при помазании освящённым миром частей тела подаются дары Святого Духа, возращающие и укрепляющие его в жизни духовной.</p>
<p>От крещения оно существенно отличается тем, что в нём сообщается высшая степень благодати и под другими знамениями, нежели те, под какими и какая сообщается в крещении.</p>
<p>С другой стороны, крещение отличается тем преимуществом перед миропомазанием, что крещение есть дверь в Христову Церковь, которою кто не войдёт, не войдёт и в Царствие Божие ([[Ин 3:5]]); тогда как новорождённый духовный младенец, если бы умер и без благодатного укрепления, остаётся живым для Христа. Различие, таким образом, не в важности, а в назначении: одно вводит в новую жизнь, другое укрепляет в ней.</p>`, s:SRC.dog+" · §250"},
  {q:"Какова видимая сторона миропомазания?",
   a:`<p>Видимым действием, знаменующим невидимую укрепляющую благодать, представляется в Писании то возложение руки, то помазание.</p>
<p>Возложением рук утверждали в благодати апостолы: Пётр и Иоанн — самарян ([[Деян 8:15]]), Павел — учеников Иоанновых ([[Деян 19:6]]), причём в первом случае приготовлением к тайнодействию представляется молитва. О возложении рук писал апостол и как о действии, входящем в состав общеизвестных действий Церкви ([[Евр 6:2]]).</p>
<p>О помазании апостол пишет: «утверждаяй же нас с вами во Христа и помазавый нас Бог, Иже и запечатле нас» ([[2 Кор 1:21]]). Хотя здесь нет сомнения, что говорится о внутреннем действии Божием на сердца верующих, — вероятно, что апостол имел при этом в виду и видимое помазание. Эта вероятность приближается к несомненности потому, что, когда апостол говорит о бане водной, он соединяет мысль о невидимом благодатном очищении с мыслью о видимом омовении водою ([[Тит 3:5]]; [[Еф 5:26]]). Те же мысли следует соединять с [[1 Ин 2:20]], [[Еф 1:13]] и [[Еф 4:30]], тем более что освящение ветхозаветных священников и царей совершалось через помазание.</p>`, s:SRC.dog+" · §246"},
  {q:"Над кем и когда совершается миропомазание?",
   a:`<p>Так как таинственное укрепление в благодати предполагает предшествовавшее участие в благодати, то миропомазание должно быть совершаемо только над теми, кто уже крещён. То же видим в примере и учении апостолов ([[Деян 8:14]]; [[Деян 19:5]]; [[Евр 6:2]]).</p>
<p>Поскольку же нельзя назначить времени, когда бы человек не имел нужды в укрепляющей благодати, — а целые семейства, крещаемые апостолами, вслед за крещением получали через апостолов Духа Святого, — то это показывает, что миропомазание может быть совершаемо как над возрастными, так и над младенцами вслед за крещением.</p>
<p>Апостол заповедует ефесянам не оскорблять Духа Святого, Которым они запечатлены «в день избавления» ([[Еф 4:30]]), то есть в самый день крещения. Так совершалось миропомазание в Церкви с самых первых времён как на востоке, так и на западе: «вышед из купели, мы помазываемся благословенным помазанием», — говорит Тертуллиан. Как духовное запечатление ([[2 Кор 1:22]]), оно не повторяется.</p>`, s:SRC.dog+" · §249"},
  {q:"Зачем нужна устная исповедь, если Бог и так знает грехи?",
   a:`<p>Нужно исповедание, то есть изустное и подробное объяснение грехов со стороны того, кого надобно прощать или не прощать. Если бы достаточно было одного внутреннего сознания грехов, — для чего было бы установлять власть разрешать или не разрешать грешника?</p>
<p>Власть, какою Спаситель облёк служителя Своего над совестью людей, состоит, как видно из Его слов, не в том, чтобы только прощать грехи, но в том, чтобы <em>или</em> прощать, <em>или</em> не прощать грешника ([[Ин 20:23]]). Следовательно, служитель Божий, прежде нежели произнесёт решение, должен верным образом узнать греховное состояние грешника; а для этого необходимо, чтобы грешник пересказал исповедующему дела свои со всеми обстоятельствами, которые могут показать состояние его души.</p>
<p>Филарет добавляет и второе основание: Спаситель, установляя эту власть, показывает людям болезненное состояние душ их, требующее врачевства, и доставляет самое врачевство. Больной телом, желая исцеления, сам рассказывает врачу о действиях и состояниях болезни — иначе лечение невозможно.</p>`, s:SRC.dog+" · §268"},
  {q:"Может ли духовник не разрешить исповедующегося?",
   a:`<p>Да, и это прямо следует из слов Спасителя: служителю тайны дана власть не только прощать грехи, но и удерживать ([[Ин 20:23]]; [[Мф 18:18]]). Причём разрешение должно быть выражено в словах: Сам Господь во всех случаях, когда освобождал грешника от грехов, на словах выражал прощение — «прощаются ти греси твои» ([[Мф 9:2]]; [[Лк 7:48]]).</p>
<p>Но власть эта дана для спасения грешника, и отсюда два ограничения. Во-первых, решение служителя тайны ни в каком случае не должно зависеть от одного только произвола. Во-вторых, оно должно основываться на рассмотрении состояния грешника: грешник иногда неспособен бывает получить прощение по упорному отвержению действий благодати ([[Мф 12:31]]). Впрочем, Господь до самой смерти грешника ожидает обращения его на путь правды.</p>
<p>Образцом такого духовного суда служит суд апостола над коринфским грешником ([[1 Кор 5:1]]). Грех был тяжкий, какого, по слову апостола, не слышно даже у язычников, и однако грешник оставался покоен, а коринфские собратья не обращали на то надлежащего внимания. Решение апостола состояло в исключении грешника из общества христианского — но с целью, чтобы «дух спасся» ([[1 Кор 5:5]]); и когда покаяние совершилось, апостол велел простить и утешить его ([[2 Кор 2:7]]).</p>`, s:SRC.dog+" · §269"},
  {q:"Что требуется от приступающего к таинству покаяния?",
   a:`<p>Прежде всего — принадлежность к Церкви: когда Спаситель учреждал власть прощать или не прощать грехи, Он имел в виду Свою Церковь и сказал: «повеждь Церкви» ([[Мф 18:17]]). Причастниками благодатной силы, действующей через служителей Христовых, могут быть члены Церкви Христовой.</p>
<p>Далее необходимы <b>сокрушение сердца</b> и <b>вера</b>. Сокрушение — искреннее болезнование о содеянных грехах, соединённое с отвращением от них. Для того и установил Господь власть разрешать грехи, чтобы грешники не были более грешниками.</p>
<p>Иначе, рассуждает Филарет, выходит следующее. Исповедь, которая предписана для того, чтобы мы примирились с Богом, оскорблённым нашими грехами, означала бы тайное желание продолжать гибельную вражду против Господа и вместе святотатственный обман пред Богом и Его служителем. Исповедь, которая совершается для того, чтобы служитель тайны подал врачевство, нужное душе, означала бы лицемерие, умышляющее на вящшее расстройство души. И самая душа будет неспособна принять благодать отпущения грехов, когда в ней нет искреннего желания получить эту благодать и искреннего отвращения от греха.</p>`, s:SRC.dog+" · §272"},
  {q:"Прощает ли грехи священник или Бог?",
   a:`<p>Грехи прощает Бог, а священник есть служитель этого прощения. Различение это Церковь проводила твёрдо и с самого начала.</p>
<p>Святитель Василий Великий тем самым, что Дух Святой при посредстве служителя Божия прощает грехи, доказывал Божество Духа Святого, — то есть прощение относил именно к Богу. Блаженный Августин обличал новациан за то, что они соединяли с действием власти, разрешающей грехи, мысль об одной власти человеческой. «Благий Врач, — писал он, — врачевал не только находившихся пред Ним, но и провидел будущих, — тех, которые станут говорить: я отпускаю грехи, я оправдываю... Пусть отвечают еретику: не я делаю, а Христос». И заключал: по Его намерению так надобно понимать, что Духом Святым отпускаются грехи, а не заслугами людей.</p>
<p>Отсюда и форма разрешительной молитвы, в которой священник свидетельствует о прощении, подаваемом Богом, а не о собственной власти прощать. Власть эта дана Церкви ([[Ин 20:22]]), но действует в ней Дух Святой.</p>`, s:SRC.dog+" · §271"},
  {q:"Над кем должно совершаться елеосвящение?",
   a:`<p>Ясные слова апостола показывают это точно: «болит ли кто в вас, да призовет пресвитеры церковныя» ([[Иак 5:14]]). Употреблённое апостолом слово ἀσθενεῖ собственно значит «быть слабым, истощённым в силах»; таково же было состояние Лазаря, близкого к смерти ([[Ин 11:1]]), и таково состояние глубокой старости. Иначе апостол называет своих больных κάμνοντα, что означает людей, утруждённых немощью, тяжко страждущих.</p>
<p>Посему елеопомазание должно совершаться не над здоровыми, но над одержимыми тяжкою болезнью и над дряхлыми старцами, для которых сама старость — болезнь.</p>
<p>Апостол предполагает притом в этих больных столько силы и присутствия духа, чтобы они сами могли призвать пресвитеров, и желает, чтобы они могли сознавать грехи свои. Отсюда видно, что в таинстве не могут участвовать неверующие во имя Христово, а также те, кто не в состоянии ни призвать, ни исповедать.</p>`, s:SRC.dog+" · §278"},
  {q:"Почему при елеосвящении собирают семь пресвитеров?",
   a:`<p>Это древний обычай, а не безусловное правило. Апостол числа не назначил ([[Иак 5:14]]), и Церковь, следуя обыкновению, издавна призывала семерых.</p>
<p>Обычай был настолько устойчив, что в греческой Церкви само таинство именовалось по нему: патриарх Векк в XIII веке писал, что вместе с прочими таинствами принимается последнее помазание, которое по чину совершения именуется «седмисвященством» (ἑπταπάπαδον); тем же словом называет елеосвящение и устав императрицы Ирины начала XII века.</p>
<p>При этом сама Церковь не считала число неизменным. Симеон Солунский пишет: предано обыкновением призывать семь священников, впрочем не нужно с любопытством дознаваться числа, когда число не обозначено. Как апостол не определил, какие именно части тела больного надлежит помазывать, так и Церковь в этом отношении не всегда следовала одному и тому же обыкновению.</p>`, s:SRC.dog+" · §277"},
  {q:"Кто имеет право рукополагать и повторяется ли рукоположение?",
   a:`<p>По свидетельствам Писания, только апостолы рукополагали служителей Церкви и предоставили право рукоположения епископам. Они рукополагали в сан епископа ([[2 Тим 1:6]]), пресвитера ([[Деян 14:23]]), диакона ([[Деян 6:6]]) и то же совершать предоставили епископам ([[Тит 1:5]]; [[1 Тим 5:22]]). Случаи, где бы таинственное рукоположение совершалось не епископом, вовсе неизвестны — на них нет и намёка в Писании. Святитель Иоанн Златоуст говорит: одним правом рукоположения возвышаются епископы, и только в этом состоит преимущество их пред пресвитерами.</p>
<p>Рукоположение не повторяется: благодать, однажды сообщённая, обитает в душе рукоположенного ([[1 Тим 4:14]]; [[2 Тим 1:6]]), и повторять его не должно, невзирая на нравственные перемены лица. Но это, замечает Филарет, не относится к тем, кто поставлен не имеющими права рукополагать: в таком случае благодать и не была сообщаема.</p>
<p>Три степени священства различаются по объёму даруемого. Диакон, не получая благодати совершать таинства, получает благодать быть служителем при совершении таинств; священномученик Игнатий Богоносец пишет о диаконах, что они «не пития и яств служители, а служители Церкви Божией».</p>`, s:SRC.dog+" · §285"},
  {q:"Почему брак есть союз одного мужа и одной жены?",
   a:`<p>В таком виде союз установлен в самом начале: одна жена дана Адаму, и сказано — «прилепится человек к жене своей», а не к жёнам ([[Быт 2:24]]). В таком же виде брак утверждён Спасителем ([[Мф 19:4]]). Апостол учит: «кийждо свою жену да имать... муж своим телом не владеет, но жена» ([[1 Кор 7:2]]) — то есть муж не имеет права отдавать плоть свою другой женщине, кроме своей супруги.</p>
<p>В Ветхом Завете встречаются примеры многожёнства даже в жизни патриархов, но это допускало лишь человеческое, не совсем разумное желание скорее достигнуть исполнения обетования; там же, где многожёнство переходило в сладострастие, оно было явно наказываемо — например, в Соломоне.</p>
<p>В христианской Церкви о многожёнстве никогда не было и слышно. «Пришедший Христос, насаждая добродетель в людях, совсем уничтожил древний обычай», — говорит святитель Иоанн Златоуст; святитель Василий Великий называет многожёнство делом, совершенно несвойственным человеческому роду.</p>`, s:SRC.dog+" · §290"},
  {q:"Как Церковь смотрит на второй брак, брак с иноверными и брак в близком родстве?",
   a:`<p><b>Второй брак.</b> Христианский закон о единожёнстве не заключает в себе запрещения вступать в новый брак в случае смерти одной половины, как не заключает и запрещения оставаться безбрачным. Апостол учит: жена связана законом, доколе жив муж её; если же муж умрёт, свободна выйти, за кого хочет, «точию о Господе»; и прибавляет, что «лучше есть женитися, нежели разжизатися» ([[1 Кор 7:39]]; [[1 Кор 7:9]]). Отцы Церкви второго брака не запрещали, хотя считали его снисхождением к человеческой немощи и недостатком совершенства.</p>
<p><b>Брак с иноверными.</b> Господь постановил: «дщери своея не даси сыну его... отвратит бо сына твоего от Мене» ([[Втор 7:3]]). Апостол не расторгает союза верного с неверною — при той мысли, что дети святы и воспитываются в вере, и в надежде на обращение неверующей половины ([[1 Кор 7:14]]). Церковь не дозволяет заключать брачный союз со всяким еретиком, но допускает смешанный брак с условием, чтобы дети воспитывались в православной вере.</p>
<p><b>Близкое родство.</b> Такие браки Церковь не дозволяет и расторгает. Основание Филарет приводит и нравственное, и опытное: следствием их бывает не размножение людей, а уменьшение — опытами дознано, что дети сочетавшихся в близком родстве бывают то немыми и глухими, то расслабленными и калеками. Вступать в брак в близком родстве значит идти наперекор самой цели брака и брать на себя ответственность за страдания несчастных детей.</p>`, s:SRC.dog+" · §290"}
 ]
},

/* ============================ 13. ЛИТУРГИКА И МОЛИТВА ============================ */
{
 id:"liturgika", title:"Богослужение и молитва",
 sub:"Литургика: молитва, праздники, пост",
 qa:[
  {q:"Что такое молитва?",
   a:`<p>Молитва — это живое общение человека с Богом, возношение к Нему ума и сердца. По содержанию она бывает славословием (прославлением Бога за то, что Он есть), благодарением (за Его благодеяния), покаянием (сокрушением о грехах) и прошением (о своих и чужих нуждах).</p>
   <p>Молитва — дыхание духовной жизни: без неё вера охладевает и замирает, как тело без дыхания. Поэтому Господь заповедал «всегда молиться и не унывать» ([[Лк 18:1]]), а апостол — «непрестанно молитесь» ([[1 Фес 5:17]]).</p>
   <p>Молиться можно и установленными Церковью словами (в них — выверенный опыт святых), и своими; вслух и в тайне сердца; в храме и всюду. Важнее слов — внимание, вера и смирение.</p>`, s:SRC.dog},
  {q:"Какая молитва — главная?",
   a:`<p>Главная христианская молитва — «Отче наш», которую дал Сам Господь в ответ на прямую просьбу учеников научить их молиться ([[Мф 6:9]]). Потому её называют молитвой Господней — она дана не человеком, а Богом.</p>
   <p>В ней кратко, но полно собрано всё главное и в верном порядке: сначала о Божием (прославление имени Отца, желание пришествия Его Царства и исполнения Его воли), затем о человеческом (прошение о насущном хлебе, о прощении грехов — в ту меру, в какую мы сами прощаем, — и об избавлении от искушения и от лукавого).</p>
   <p>Поэтому «Отче наш» — не одна из молитв в ряду прочих, а образец и мерило всякой молитвы, которому святые учили сверять свои прошения.</p>`, s:SRC.pis},
  {q:"Что такое Божественная литургия?",
   a:`<p>Литургия (греч. «общее дело», «общественное служение») — главное богослужение Церкви, за которым совершается таинство Евхаристии. В её стройном чинопоследовании воспоминается всё домостроительство спасения — от ветхозаветных пророчеств через воплощение, Крест и Воскресение до ожидания Второго пришествия, — и приносится бескровная жертва.</p>
   <p>Она совершается во исполнение прямой заповеди Господа: «сие творите в Моё воспоминание» ([[Лк 22:19]]). За литургией земная Церковь таинственно соединяется с небесной, и верующие вместе с ангелами приносят Богу единую хвалу.</p>
   <p>В Православной Церкви чаще всего совершаются литургии святителей Иоанна Златоуста и (в определённые дни) Василия Великого.</p>`, s:SRC.dog},
  {q:"Зачем нужны храм и общая молитва?",
   a:`<p>Храм — место особого, благодатного присутствия Божия, дом молитвы и совершения таинств, где Церковь собирается воедино как одно тело. Хотя молиться можно и должно везде, общая церковная молитва имеет особую силу и особое обетование.</p>
   <p>Господь обещал: «где двое или трое собраны во имя Моё, там Я посреди них» ([[Мф 18:20]]). Первые христиане «постоянно пребывали в учении апостолов, в общении и преломлении хлеба и в молитвах» ([[Деян 2:42]]) — общая молитва была самой тканью их жизни.</p>
   <p>Она не только испрашивает благодать, но и соединяет верующих между собою, научает любви и выводит человека из замкнутости в себе к жизни в Теле Христовом.</p>`, s:SRC.dog},
  {q:"Что такое церковные праздники?",
   a:`<p>Праздники — установленные Церковью дни воспоминания спасительных событий и прославления Бога, Богородицы и святых. Они не просто память о давнем прошлом, а благодатное соучастие в празднуемом событии: в праздник Церковь вновь переживает его как настоящее.</p>
   <p>Главный праздник — Пасха, Воскресение Христово, «праздников праздник и торжество из торжеств», средоточие всего церковного года. За нею следуют двунадесятые праздники (двенадцать важнейших), посвящённые событиям жизни Спасителя и Божией Матери, и многочисленные памяти святых.</p>
   <p>Череда праздников и постов образует церковный год — как бы годовой круг восхождения к Богу, в котором вся жизнь освящается воспоминанием дел Божиих.</p>`, s:SRC.pred},
  {q:"Зачем нужен пост?",
   a:`<p>Пост — это добровольное воздержание от определённой пищи, а также от развлечений и потакания страстям, ради того чтобы облегчить телу молитву, обуздать плоть и очистить и укрепить душу. При этом телесный пост без духовного — без усиленной молитвы, воздержания от гнева, осуждения и празднословия — бесплоден и даже вреден, если рождает гордость.</p>
   <p>Сам Господь постился в пустыне сорок дней ([[Мф 4:2]]) и учил, что иные искушения и духовные брани побеждаются «только молитвою и постом» ([[Мф 17:21]]).</p>
   <p>Пост — древнейшее установление: постились пророки, апостолы, вся ранняя Церковь. Он готовит душу к великим праздникам, укрепляет волю в господстве над телом и учит человека, что «не хлебом одним будет жить человек» ([[Мф 4:4]]).</p>`, s:SRC.dog},
  {q:"Что такое воскресный день?",
   a:`<p>Воскресенье — «день Господень» ([[Откр 1:10]]), еженедельная малая Пасха, посвящённая воспоминанию Воскресения Христова. Он пришёл на смену ветхозаветной субботе: суббота напоминала о завершении творения и об исходе из Египта, а воскресенье — о новом творении и об избавлении от смерти.</p>
   <p>С апостольских времён христиане собирались именно в первый день недели «для преломления хлеба» — то есть на Евхаристию ([[Деян 20:7]]); так этот день с самого начала стал днём церковного собрания.</p>
   <p>В воскресный день верующие оставляют, насколько возможно, житейскую суету и посвящают его Богу — прежде всего участием в литургии, а также делами милосердия и духовным чтением.</p>`, s:SRC.ist},
  {q:"Что такое крестное знамение?",
   a:`<p>Крестное знамение — это молитвенное изображение на себе креста Христова, которым христианин исповедует сразу две главные истины веры: соединяя три первых перста, он исповедует Святую Троицу, а самим осенением себя крестом — веру в спасительный Крест Христов. Так знамение — краткое исповедание веры, совершаемое телом.</p>
   <p>Крест для христиан — не орудие позора, а сила Божия и знамя победы над злом; апостол хвалится «только крестом Господа нашего Иисуса Христа» ([[Гал 6:14]]).</p>
   <p>Крестным знамением верующий освящает и ограждает себя, начинает и завершает молитву и всякое дело; о древности этого обычая свидетельствуют уже церковные писатели первых веков.</p>`, s:SRC.pred},
  {q:"Можно ли молиться своими словами?",
   a:`<p>Да, и Церковь ценит оба вида молитвы. Установленные молитвы важны тем, что в них запечатлён проверенный опыт и слова святых, ограждающие от заблуждений и научающие, о чём и как правильно молиться; своя же молитва, идущая от сердца, важна живостью и искренностью. Одно не исключает и не заменяет другого.</p>
   <p>Важнее всего не количество и не красота слов, а внимание, вера и сокрушение сердца. Господь прямо предостерёг от «многословия» язычников, думающих быть услышанными за множество слов ([[Мф 6:7]]).</p>
   <p>И Он же принял и поставил в пример коротчайшую, но сокрушённую молитву мытаря: «Боже, будь милостив ко мне, грешнику» ([[Лк 18:13]]), — которая оправдала его больше, чем пространная молитва гордого фарисея.</p>`, s:SRC.dog}
 ]
},

/* ============================ 14. МАРИОЛОГИЯ И ПОЧИТАНИЕ СВЯТЫХ ============================ */
{
 id:"pochitanie", title:"Богородица, святые и иконы",
 sub:"Мариология и почитание святыни",
 qa:[
  {q:"Почему Деву Марию называют Богородицей?",
   a:`<p>Потому что Она родила по плоти Господа Иисуса Христа, Который есть не «простой человек», ставший потом вместилищем Бога, а единое Лицо воплотившегося Сына Божия — истинный Бог. Именование относится не к тому, будто Она родила вечное Божество (Божество не рождается и не начинается), а к тому, что Рождённый от Неё есть Бог по Лицу.</p>
   <p>Наименование «Богородица» (греч. <em>Феотокос</em>) утвердил III Вселенский собор (Ефес, 431 г.) против Нестория, который отвергал его и предлагал звать Марию лишь «Христородицей», тем самым разделяя во Христе Бога и человека. Церковь увидела в этом разрушение единства Христа и потому отстояла именование «Богородица».</p>
   <p>Основание его — уже в Евангелии: праведная Елисавета, исполнившись Духа Святого, назвала Марию «Матерью Господа моего» ([[Лк 1:43]]).</p>`, s:SRC.ist},
  {q:"Почему Богородицу почитают выше всех святых?",
   a:`<p>Как Матерь Божия, добровольным согласием послужившая величайшей тайне — воплощению Сына Божия, — Пресвятая Дева превосходит достоинством и близостью к Богу всех святых и самих ангелов. Церковь именует Её «честнейшей херувим и славнейшей без сравнения серафим».</p>
   <p>Это почитание не есть поклонение Ей как Богу: такое поклонение (латрию) Церковь воздаёт одному Богу. Богородице же и святым воздаётся почитание и любовь как тварям, особо приближённым к Богу; при этом Её почитание — высшее среди всех тварей.</p>
   <p>Само это ублажение предречено в Евангелии Её же пророческими словами: «отныне будут ублажать Меня все роды» ([[Лк 1:48]]). Церковь молитвенно прибегает к Её ходатайству как к первой Заступнице пред Сыном.</p>`, s:SRC.pred},
  {q:"Зачем молиться святым, если есть Христос?",
   a:`<p>Молясь святым, мы не ставим их на место Христа и не считаем их «вторыми спасителями»: единый Искупитель и Ходатай, примиривший нас с Богом, — только Христос ([[1 Тим 2:5]]). Мы просим святых <em>молиться о нас вместе с нами</em>, как просим молитв и у живых, близких по вере людей.</p>
   <p>Основание такой молитвы двойное. Во-первых, святые живы у Бога, ибо Он «Бог не мёртвых, но живых» ([[Мф 22:32]]), и их любовь к собратьям по вере не прекратилась со смертью. Во-вторых, молитва праведника имеет особую силу: «много может усиленная молитва праведного» ([[Иак 5:16]]) — тем более молитва прославленных Богом святых.</p>
   <p>Итак, почитание святых не умаляет Христа, а прославляет Его в Его святых и являет живое единство Церкви земной и небесной.</p>`, s:SRC.dog},
  {q:"Кто такие святые?",
   a:`<p>Святые — это люди, которые благодатью Божией и своим подвигом достигли святости, угодили Богу и прославлены Им, нередко чудесами и нетлением мощей. Церковь различает разные лики святости: апостолы, пророки, мученики, святители (святые епископы), преподобные (святые монахи), праведные (святые миряне), бессребреники (безмездные врачи) и другие.</p>
   <p>Важно понимать, что прославление (канонизация) не «делает» человека святым, а лишь свидетельствует о святости, уже явленной Богом, и включает почитание святого во всей Церкви. Святые — не безгрешные от природы сверхлюди, а те, кто прошёл путём покаяния, борьбы и любви.</p>
   <p>Их пример вдохновляет, а молитвы поддерживают верующих: мы окружены «таким облаком свидетелей» ([[Евр 12:1]]), которые прошли тот же путь прежде нас.</p>`, s:SRC.ist},
  {q:"Кто такие мученики?",
   a:`<p>Мученики (греч. «мартис» — «свидетель») — христиане, претерпевшие страдания и смерть за веру во Христа, не отрёкшись от Него. Их подвиг — высшее свидетельство любви ко Христу и полное уподобление Его крестной смерти; потому мученичество древняя Церковь чтила выше всех подвигов.</p>
   <p>В первые три века гонений мучеников были тысячи. По известному слову Тертуллиана, кровь мучеников стала семенем христиан: гонения не истребляли Церковь, а умножали её, ибо мужество и радость мучеников среди страданий обращали ко Христу самих палачей и зрителей.</p>
   <p>Господь обещал им особую награду: «Будь верен до смерти, и дам тебе венец жизни» ([[Откр 2:10]]).</p>`, s:SRC.ist},
  {q:"Не идолопоклонство ли — почитание икон?",
   a:`<p>Нет. Идолопоклонство — это поклонение ложным богам и обожествление твари вместо Творца. Икона же не бог и не изображение ложного божества, а образ, возводящий ум и сердце к Первообразу — ко Христу, Богородице, святым. По точному слову святых отцов, «честь, воздаваемая образу, восходит к Первообразу».</p>
   <p>Поэтому поклоняются не доске и краскам, а Тому или тем, кто на иконе изображён. Иконопочитание соборно утвердил VII Вселенский собор (787 г.), завершивший долгую борьбу с иконоборчеством. Собор ясно различил <em>поклонение-служение</em> (латрию), подобающее одному Богу, и <em>почитательное поклонение</em>, воздаваемое иконам, кресту, святым и их мощам.</p>
   <p>Иконоборчество, отвергавшее образа, было осуждено Церковью как ересь, а восстановление иконопочитания празднуется как «Торжество Православия».</p>`, s:SRC.ist},
  {q:"Почему можно изображать Христа?",
   a:`<p>Потому что Сын Божий стал истинным человеком, был видим, осязаем и описуем: «о том, что было от начала, что мы слышали, что видели своими очами, что рассматривали и что осязали руки наши, — о Слове жизни» ([[1 Ин 1:1]]). Невидимого Бога изобразить нельзя и запрещено, но Бога, ставшего видимым человеком, — можно и должно.</p>
   <p>Поэтому икона Христа — не просто украшение, а исповедание реальности воплощения. Отсюда глубокий довод отцов против иконоборцев: отвергая возможность изобразить Христа, они по сути отрицали или умаляли и самое воплощение, истинность принятой Им плоти.</p>
   <p>Основание иконы — в том, что «Слово стало плотию» ([[Ин 1:14]]): именно воплощение открыло возможность священного образа.</p>`, s:SRC.ist},
  {q:"Зачем почитают мощи и святыни?",
   a:`<p>Тела святых при жизни были храмами Святого Духа ([[1 Кор 6:19]]) и приобщились Божественной благодати; эта освящённость не исчезает и по смерти, потому мощи святых чтутся и нередко становятся источником исцелений. Почитается при этом не «прах» сам по себе, а действующая через святых сила Божия.</p>
   <p>Само Писание даёт тому свидетельства в обоих Заветах. В Ветхом — от костей пророка Елисея ожил прикоснувшийся к ним мертвец ([[4 Цар 13:21]]). В Новом — от тела апостола Павла брали платки и опоясания, и болезни отступали, и злые духи выходили ([[Деян 19:12]]).</p>
   <p>Церковь издревле чтила гробницы мучеников и совершала на их мощах Евхаристию — обычай, доныне сохранённый в антиминсе с частицей мощей на престоле.</p>`, s:SRC.ist}
 ]
},

/* ============================ 15. ЭСХАТОЛОГИЯ ============================ */
{
 id:"eshatologiya", title:"Последние времена",
 sub:"Эсхатология: смерть, суд, вечная жизнь",
 qa:[
  {q:"Что бывает с душой после смерти?",
   a:`<p>Смерть — это разлучение души с телом; сама душа при этом не умирает и не «засыпает» без сознания, но продолжает жить, сознавать и помнить. По разлучении с телом душа проходит частный суд, определяющий её предначальное состояние — предвкушение блаженства или мучения.</p>
   <p>Это состояние ещё не окончательно: полнота воздаяния наступит лишь после всеобщего суда, когда с душою вновь соединится воскресшее тело, и человек будет судим и прославлен (или осуждён) в своей целостности.</p>
   <p>Для верующего смерть — не уничтожение и не конец, а переход, «исход»; Господь есть «Бог живых» ([[Мф 22:32]]), и умершие в вере живы у Него.</p>`, s:SRC.dog},
  {q:"Что такое частный суд?",
   a:`<p>Частный суд — это определение участи каждой души сразу по её разлучении с телом, задолго до всеобщего суда. «Человекам положено однажды умереть, а потом суд» ([[Евр 9:27]]) — суд следует за смертью, не откладываясь до конца мира.</p>
   <p>По этому суду праведные вводятся в предвкушение блаженства — как разбойник, которому Господь обещал: «ныне же будешь со Мною в раю» ([[Лк 23:43]]); а нераскаянные грешники — в предвкушение мучения, как показывает притча о богаче и Лазаре, где после смерти один утешается, а другой страдает ([[Лк 16:23]]).</p>
   <p>Это состояние — не окончательный приговор, а предначатие его; окончательное же и всеобщее решение произнесётся на Страшном суде.</p>`, s:SRC.dog},
  {q:"Полезны ли молитвы об умерших?",
   a:`<p>Да. Поскольку до всеобщего суда участь души не является окончательной и неизменной, молитва Церкви, милостыня и особенно поминовение на Божественной литургии могут облегчить состояние усопших и испросить им милость Божию — если только они не отошли в состоянии полного, сознательного и ожесточённого отвержения Бога.</p>
   <p>Основание этой практики — древнее. Ещё в Ветхом Завете приносили жертву за умерших, «да разрешатся от греха» (2 Мак. 12:44); христианская Церковь с апостольских времён молится о своих усопших и поминает их за Евхаристией.</p>
   <p>Молитва об усопших — выражение той любви, которая «никогда не перестаёт» ([[1 Кор 13:8]]) и не прерывается смертью, свидетельство единства Церкви живых и умерших.</p>`, s:SRC.dog},
  {q:"Что такое всеобщее воскресение?",
   a:`<p>В конце времён, при Втором пришествии Христа, все умершие воскреснут телесно: душа каждого человека вновь соединится со своим воскрешённым телом. «Наступает время, в которое все, находящиеся в гробах, услышат глас Сына Божия и изыдут» ([[Ин 5:28]]).</p>
   <p>Воскресшее тело будет тем же самым телом человека, но преображённым — нетленным, бессмертным, духовным, свободным от немощей: «сеется в тлении, восстаёт в нетлении… сеется тело душевное, восстаёт тело духовное» ([[1 Кор 15:42]]).</p>
   <p>Образ и залог нашего воскресения — уже совершившееся воскресение тела Христова: Он воскрес «первенцем из умерших», за Которым воскреснут и все.</p>`, s:SRC.dog},
  {q:"Что такое Страшный суд?",
   a:`<p>Страшный (последний, всеобщий) суд — суд Христов над всем родом человеческим при Его Втором пришествии, когда после всеобщего воскресения откроются дела, слова и даже сокровенные помышления каждого, и определится окончательная вечная участь всех.</p>
   <p>Господь изобразил его в притче: «когда же приидет Сын Человеческий во славе Своей… соберутся пред Ним все народы; и отделит одних от других, как пастырь отделяет овец от козлов» ([[Мф 25:32]]). Мерилом суда, по этой притче, будут прежде всего дела любви и милосердия к ближним, в которых оказывается служение Самому Христу.</p>
   <p>Суд этот назван «страшным» не потому, что несправедлив, а потому что окончателен и совершается Всеведущим, от Которого ничто не сокрыто; но для любящих Бога он есть и день оправдания и радости.</p>`, s:SRC.dog},
  {q:"Что такое антихрист?",
   a:`<p>Антихрист — противник Христа, который, по пророчеству апостолов, явится перед самым концом мира, обольстит многих ложными знамениями и чудесами и воздвигнет последнее гонение на верных ([[2 Фес 2:3|2 Фес 2:3-4]]). Само имя двусмысленно и точно: «анти» значит и «против Христа», и «вместо Христа» — он будет выдавать себя за спасителя.</p>
   <p>Его царство будет кратким и обречённым: пришествие Господне мгновенно упразднит его — Господь «убьёт духом уст Своих и истребит явлением пришествия Своего» ([[2 Фес 2:8]]).</p>
   <p>Апостол предупреждал, что «дух антихриста» действует в мире уже и что «появилось много антихристов» ([[1 Ин 4:3]]) — то есть всякий, кто отвергает Христа и противится Ему, отчасти предваряет последнего антихриста.</p>`, s:SRC.dog},
  {q:"Что такое вечная жизнь?",
   a:`<p>Вечная жизнь — не просто бесконечное продолжение существования, а совершенное общение с Богом, полнота блаженства в любви, ведении и созерцании Его. Господь Сам дал ей определение: «Сия же есть жизнь вечная, да знают Тебя, единого истинного Бога, и посланного Тобою Иисуса Христа» ([[Ин 17:3]]).</p>
   <p>В ней прекратятся смерть, болезнь, скорбь и всякое зло; праведные увидят Бога уже не «гадательно», а «лицем к лицу» ([[1 Кор 13:12]]) и уподобятся Ему: «будем подобны Ему, потому что увидим Его, как Он есть» ([[1 Ин 3:2]]).</p>
   <p>Это блаженство превосходит всякое земное воображение: «не видел того глаз, не слышало ухо, и не приходило то на сердце человеку, что приготовил Бог любящим Его» ([[1 Кор 2:9]]).</p>`, s:SRC.dog},
  {q:"Что такое вечная мука и совместима ли она с любовью Божией?",
   a:`<p>Итог суда, по слову Господа, двойствен: «И пойдут сии в муку вечную, а праведники в жизнь вечную» ([[Мф 25:46]]). Мука — это состояние отпадения от Бога, добровольного и окончательного пребывания вне Его любви и света, которое человек сам избрал при жизни и в котором ожесточился.</p>
   <p>С любовью Божией это не противоречит, если понять правильно. Бог никого не творит для погибели и «хочет, чтобы все люди спаслись» ([[1 Тим 2:4]]); Он не «отправляет» на муку из мести. Но любовь по самой природе не может насильно принудить к общению того, кто до конца, свободно и сознательно её отверг, — иначе это была бы уже не любовь.</p>
   <p>Поэтому мука есть не столько внешнее наказание, сколько горький плод и самое существо отвержения Источника жизни: тот же огонь Божией любви для любящих — блаженство, а для отвергших — мучение.</p>`, s:SRC.dog},
  {q:"Одинаково ли блаженство всех праведных?",
   a:`<p>Нет. Блаженство едино по существу — все спасённые пребывают в общении с Богом, — но различно по мере и степени, соответственно духовному возрасту, любви и чистоте каждого. Бог воздаёт по правде, и всякий вмещает столько, сколько способен вместить.</p>
   <p>Господь сказал: «В доме Отца Моего обителей много» ([[Ин 14:2]]) — обителей разных, по мере каждого. Апостол поясняет образом светил: «иная слава солнца, иная слава луны, иная звёзд; и звезда от звезды разнится в славе. Так и при воскресении мёртвых» ([[1 Кор 15:41]]).</p>
   <p>При этом различие мер не рождает ни зависти, ни ущерба: каждый будет исполнен блаженства до края своей вместимости и совершенно счастлив.</p>`, s:SRC.dog},
  {q:"Что будет с миром в конце?",
   a:`<p>Мир не будет уничтожен в небытие, но преображён и обновлён, освобождён от тления, зла и смерти. «И увидел я новое небо и новую землю, ибо прежнее небо и прежняя земля миновали» ([[Откр 21:1]]); само творение «освобождено будет от рабства тлению в свободу славы детей Божиих» ([[Рим 8:21]]).</p>
   <p>Тогда Бог «отрёт всякую слезу с очей их, и смерти не будет уже; ни плача, ни вопля, ни болезни уже не будет» ([[Откр 21:4]]), и настанет полнота Царства, где «будет Бог всё во всём» ([[1 Кор 15:28]]).</p>
   <p>К этому окончательному обновлению — «новому небу и новой земле» — и устремлена вся история спасения; это её цель и завершение.</p>`, s:SRC.dog},
  {q:"Каково состояние праведных душ до всеобщего суда?",
   a:`<p>Писание показывает, что праведные вслед за исходом из этой жизни награждаются блаженством. Спаситель говорит ученикам: «иду уготовати место вам... паки прииду и поиму вы к Себе, да идеже есмь Аз, и вы будете» ([[Ин 14:2]]) — и речь здесь не о втором пришествии на суд, ибо не говорится ни об общем воскресении, ни об обновлении мира. Апостол Павел желает «разрешитися и со Христом быти» ([[Флп 1:23]]) и говорит: «благоволим паче отыти от тела и внити ко Господу» ([[2 Кор 5:8]]).</p>
<p>Однако это ещё не полное воздаяние. Апостол пишет о венце правды, который даст ему Господь «в день он», и не ему только, но и всем возлюбившим явление Его ([[2 Тим 4:8]]), — значит, полное прославление святых последует после всеобщего суда.</p>
<p>Итог таков: святые вслед за исходом награждаются блаженством по мере заслуг ([[1 Кор 3:8]]); но это ещё не полное воздаяние ([[2 Кор 5:10]]; [[Кол 3:4]]); а состояние их до всеобщего суда есть состояние покоя и радости ([[Евр 4:9]]; [[Откр 6:11]]) — при котором полнота славы ещё впереди.</p>`, s:SRC.dog+" · §314"},
  {q:"Где пребывают святые души до всеобщего суда?",
   a:`<p>Здесь Филарет прямо отмечает, что у отцов не было единого решения. Все учители Церкви признавали блаженное состояние святых по смерти, но когда касались вопроса о самом <em>месте</em> их пребывания до всеобщего суда, ответы были неодинаковы.</p>
<p>По мнению большей части, святые находятся в раю на небе. По мнению некоторых, восход на небо для них ещё не доступен, и они пребывают в особом покойном отделении невидимого места, как бы в преддверии к Царству.</p>
<p>В последнем мнении, замечает Филарет, несомненно верна только та мысль, что святые ожидают полного прославления от времени суда и воскресения; и эта мысль была общей уверенностью всех вообще учителей Церкви. Такова здесь мера церковного знания: несомненно — <em>что</em> с ними (покой, близость ко Христу, ожидание полноты), не определено — <em>где</em> именно.</p>`, s:SRC.dog+" · §316"},
  {q:"Каково состояние грешных душ до суда?",
   a:`<p>Основное изображение даёт притча о богаче и Лазаре ([[Лк 16:22]]). Из неё видно: низведённый во ад терпит страдания, мучится заботами о себе и о братьях; место мучения отделено от места покоя праведных «пропастью великой», так что и для самих праведников невозможно облегчить мучения страждущих.</p>
<p>По общему суду Церкви грешники, исполнившие меру беззаконий и умершие без раскаяния, вскоре по смерти переходят к мукам, оставаясь впрочем в ожидании ещё более грозной участи. Священномученик Игнатий Богоносец говорит, что развративший веру злым учением, будучи нечист, перейдёт в огонь неугасимый. Святитель Ефрем Сирин поучал, что грешник оставляет сладости этой жизни, которыми думал вечно наслаждаться. Святитель Иоанн Златоуст: души по отшествии отсюда уводятся в некую страну и, уже не имея возможности возвратиться оттуда в мир сей, ожидают страшного оного дня.</p>
<p>Вместе с тем Филарет делает тонкое замечание: ответом Авраама притча показывает невозможность найти помощь <em>за гробом</em> для проведшего всю жизнь в грехах, но ничего не говорит о возможности или невозможности помощи со стороны <em>живых</em> — чем и не отсекается упование Церкви, молящейся об усопших.</p>`, s:SRC.dog+" · §315–316"},
  {q:"Признаёт ли Православная Церковь чистилище?",
   a:`<p>Нет. Филарет ставит это учение в ряд крайностей, между которыми стоит православное исповедание.</p>
<p>С одной стороны, латиняне даже на соборах Флорентийском и Тридентском освятили для себя чистилище с очистительным огнём. С другой — протестанты, по отвращению к чистилищу, настаивали только на двояком состоянии умерших: на состоянии полной славы святых и на полном осуждении грешных, — то есть отсекли всякую надежду на перемену участи и вместе с нею молитву за усопших.</p>
<p>Православное учение не совпадает ни с тем, ни с другим: состояние душ до всеобщего суда не окончательно, и молитва Церкви об усопших имеет силу, — но никакого «места очищения» с вещественным огнём и заранее исчисленными сроками Церковь не знает. Филарет замечает притом, что и Ориген, на которого здесь ссылаются, говорил не о римском чистилище, а о всеобщем очищении при конце мира, и об огне рассуждал не в собственном смысле, нигде не давая понять, что разумеет огонь вещественный.</p>`, s:SRC.dog+" · §316"},
  {q:"Ожидает ли Церковь тысячелетнего царства Христова на земле?",
   a:`<p>Нет; это мнение (хилиазм) Церковь отвергла. Папий, приняв иудейское мнение за апостольское предание, ожидал для святых, прежде воскресения грешников, видимого тысячелетнего царства со Христом на земле, — хотя и не грубо-чувственного, какого ожидали Керинф и евиониты. Мнение Папия разделяли Иустин, Ириней, Тертуллиан, Непот, Лактанций.</p>
<p>Но это мнение с особенным успехом обличал святитель Дионисий Александрийский, и с четвёртого века отцы называли его уже пустою мечтою.</p>
<p>Блаженный Августин, говоря о тысяче лет тайнозрителя ([[Откр 20:2]]), писал, что «тысячу лет» поставил он вместо всех лет сего века — от смерти Христовой до суда, — чтобы полным числом означить полноту времени. Таково и общее понимание Церкви: число это символическое, а не хронологическое.</p>`, s:SRC.dog+" · §316"},
  {q:"Известно ли время второго пришествия Христова?",
   a:`<p>Нет, и знать его не дано. Спаситель прямо сказал, что о дне том и часе не знает никто, ни ангелы небесные, а только Отец ([[Мф 24:36]]). Если и для такого ума, каков ум ангелов, недоступно знание точного времени, то тем более оно недоступно уму человеческому.</p>
<p>Когда апостолы спрашивали воскресшего Господа: «аще в лето сие устрояеши царствие Израилево?» — Он сказал: «несть ваше разумети времена и лета, яже Отец положи во Своей власти» ([[Деян 1:7]]).</p>
<p>Апостолы учат о внезапности: «приидет же день Господень яко тать в нощи» ([[2 Пет 3:10]]); «егда бо рекут: мир и утверждение, тогда внезапу нападет на них всегубительство» ([[1 Фес 5:3]]). Именно поэтому Спаситель внушал ученикам бодрствовать: не вычислять срок, а быть готовыми в любой ([[Мф 24:42]]).</p>`, s:SRC.dog+" · §323"},
  {q:"Все ли будут воскрешены и каковы будут воскресшие тела?",
   a:`<p>Воскрешены будут все. Фарисеи, по свидетельству Иосифа Флавия, думали, что тела возвращены будут только душам праведным; но не таково учение Откровения. Животворящее действие Божие простирается на всех умерших, только не с одинаковыми последствиями: «изыдут сотворшии благая в воскрешение живота, а сотворшии злая в воскрешение суда» ([[Ин 5:29]]); «воскресение хощет быти мертвым, праведником же и грешником» ([[Деян 24:15]]); «якоже бо о Адаме вси умирают, такожде и о Христе вси оживут» ([[1 Кор 15:22]]). Оставшиеся в живых не умрут, но изменятся ([[1 Кор 15:51]]).</p>
<p>Тело будет то же самое, но нетленное. Апостол говорит: «мертвенное сие облечется в безсмертие» ([[1 Кор 15:53]]), и называет тело, имеющее преобразиться, «телом смирения нашего» ([[Флп 3:21]]). Поэтому несправедливо думать, будто будущее тело будет совершенно другое или какое-то «небесное», не земное.</p>
<p>Слова о «здании от Бога, храмине нерукотворённой, вечной на небесех» ([[2 Кор 5:1]]) означают не место, откуда взято будет вещество для будущего тела, а ту причину, которая его устроит. Святитель Ириней поясняет: то, что смертная и тленная плоть будет бессмертною и нетленною, произойдёт не по её природе, а по действию Господа, могущего усвоить смертному бессмертие.</p>`, s:SRC.dog+" · §329–330"},
  {q:"Погибнет ли мир или преобразится?",
   a:`<p>Откровение так тесно соединяет судьбу вещественного мира с историей человека, что уже это заставляет ожидать: с последней решительной переменой участи человека должна соединиться перемена и с вещественным миром.</p>
<p>Ещё в Ветхом Завете было возвещено, что один Бог всегда Тот же, всё же прочее «яко риза обетшают, и яко одежду свиеши я, и изменятся» ([[Пс 101:27]]; [[Евр 1:12]]). Пророк Исаия возвещал: «истают вся силы небесныя, и свиется небо аки свиток» ([[Ис 34:4]]). В Новом Завете Спаситель говорит, что решение участи людей будет соединено с кончиной века ([[Мф 13:39]]), и в беседе о втором пришествии: «небо и земля мимоидет» ([[Мф 24:35]]).</p>
<p>Филарет обращает внимание на выражения «солнце померкнет, луна не даст света своего и звёзды спадут с небесе» ([[Мф 24:29]]). Если признать их только образом потрясающего переворота, остаётся вопрос: с чего взят этот образ? В нынешнем состоянии природы, даже при сильнейшем землетрясении, мы не видим такой действительности. Значит, остаётся принять, что Спаситель представляет действительность будущую — не уничтожение творения, а его преображение ([[Рим 8:21]]; [[Откр 21:1]]).</p>`, s:SRC.dog+" · §332"}
 ]
},

/* ============================ 16. ПАТРОЛОГИЯ И ИСТОРИЯ ЦЕРКВИ ============================ */
{
 id:"istoriya", title:"Отцы и история Церкви",
 sub:"Патрология и церковная история",
 qa:[
  {q:"Кто такие отцы Церкви?",
   a:`<p>Отцы Церкви — святые учители древности, засвидетельствовавшие и изложившие веру Церкви, к которым она относится с особым авторитетом как к своим духовным «отцам». Обычно называют четыре признака отца Церкви: правость учения (православие), святость жизни, признание Церковью и древность.</p>
   <p>Особую силу имеет их <em>согласное</em> свидетельство — «согласие отцов» (лат. <em>consensus patrum</em>): то, в чём отцы разных стран и эпох единодушны, Церковь принимает как надёжное выражение своей веры. Отдельное же частное мнение отца не имеет такого веса.</p>
   <p>Среди величайших восточных отцов — святители Афанасий Великий, Василий Великий, Григорий Богослов, Иоанн Златоуст; на Западе — блаженный Августин. Их творения — драгоценная часть Предания.</p>`, s:SRC.ist},
  {q:"Что такое патрология?",
   a:`<p>Патрология — раздел богословской науки, изучающий жизнь, творения и учение отцов и церковных писателей древности. Она рассматривает, как в разные эпохи и в разных обстоятельствах Церковь раскрывала, формулировала и защищала свою веру.</p>
   <p>Ценность патрологии в том, что она показывает догматы не как внезапные «изобретения», а как всё более точные выражения одной и той же апостольской веры, отчеканенные нередко в борьбе с ересями. Изучая отцов, мы видим живую преемственность и единство церковного предания сквозь века.</p>`, s:SRC.sim},
  {q:"Кто написал первую историю Церкви?",
   a:`<p>Отцом церковной истории по праву считается Евсевий, епископ Кесарии Палестинской (около 260–340 гг.). Его труд «Церковная история» в десяти книгах охватывает время от апостолов до эпохи Константина Великого и стал образцом для всех последующих церковных историков.</p>
   <p>Особая ценность его сочинения в том, что Евсевий обильно приводит выдержки из древних документов, посланий и сочинений, многие из которых иначе были бы полностью утрачены. Благодаря ему мы знаем множество свидетельств о ранней Церкви, о мучениках, о преемстве епископов и о первых ересях. Он же составил хронологию и списки епископов главных кафедр.</p>`, s:SRC.ist},
  {q:"На какие периоды делят историю Церкви?",
   a:`<p>Историю Церкви обычно делят по важнейшим рубежам. Первый большой период — от начала Церкви (Пятидесятница, около 30 г.) до Миланского эдикта (313 г.): это эпоха апостолов, распространения веры и гонений, время Церкви гонимой. Второй — от Миланского эдикта до разделения Церквей (1054 г.): эпоха Вселенских соборов, свободного устроения церковной жизни и вероучения.</p>
   <p>После 1054 года истории христианского Востока и Запада во многом расходятся, и каждую рассматривают отдельно. Существуют и другие, более дробные деления, но именно эти рубежи — 313 и 1054 годы — самые значимые.</p>
   <p>Такая периодизация помогает видеть внутреннюю логику истории: от гонимой апостольской общины — к вселенскому соборному раскрытию веры.</p>`, s:SRC.sim},
  {q:"Как начиналась Церковь?",
   a:`<p>Церковь родилась в Иерусалиме в день Пятидесятницы, когда на апостолов сошёл Святой Дух, и апостол Пётр своей первой проповедью обратил ко Христу около трёх тысяч человек ([[Деян 2:41]]). Первая община жила в удивительном единодушии, в учении апостолов, общей молитве, преломлении хлеба и общности имущества.</p>
   <p>Из Иерусалима вера начала распространяться — сначала по Иудее и Самарии, а затем, особенно трудами апостола Павла в его путешествиях, по городам всей Римской империи, среди иудеев и язычников.</p>
   <p>Так исполнялось последнее повеление Христа апостолам: быть Ему свидетелями «в Иерусалиме и во всей Иудее и Самарии и даже до края земли» ([[Деян 1:8]]).</p>`, s:SRC.ist},
  {q:"Как и почему гнали первых христиан?",
   a:`<p>Сначала христиан преследовали иудейские власти — так пострадали первомученик Стефан и апостол Иаков. Затем, на протяжении почти трёх веков, Церковь терпела гонения от Римской империи. При Нероне (в 60-е годы) в Риме приняли мученическую смерть апостолы Пётр и Павел.</p>
   <p>Причины гонений были и религиозные, и государственные: христиане отказывались приносить жертвы языческим богам и обожествлённому императору, что власть считала преступлением против государства и «безбожием». Гонения то вспыхивали с новой силой (при Деции, Диоклетиане), то затихали.</p>
   <p>Несмотря на казни, вера не ослабевала, а росла: стойкость и радость мучеников среди страданий были живой проповедью, обращавшей ко Христу самих гонителей и зрителей.</p>`, s:SRC.ist},
  {q:"Что изменил Константин Великий?",
   a:`<p>При императоре Константине Великом положение Церкви изменилось коренным образом. Миланским эдиктом (313 г.) христианство получило свободу и законное признание, трёхвековые гонения прекратились, и Церковь перешла от преследований к союзу с государством.</p>
   <p>Константин созвал и Первый Вселенский собор в Никее (325 г.), положив начало эпохе Вселенских соборов, на которых Церковь соборно оградила свою веру. При нём же новой столицей стал Константинополь, будущий центр восточного христианства.</p>
   <p>Его царствование стало историческим рубежом — гранью между эпохой гонимой Церкви катакомб и эпохой Церкви, свободно устрояющей свою жизнь, богослужение и вероучение.</p>`, s:SRC.ist},
  {q:"Где и когда принят Символ веры?",
   a:`<p>Основу Символа веры составили отцы Первого Вселенского собора в Никее (325 г.), оградив словом «единосущный» веру в истинное Божество Сына против арианства. Второй Вселенский собор (Константинополь, 381 г.) дополнил его, подробнее раскрыв учение о Святом Духе и о Церкви.</p>
   <p>Поэтому полный Символ называется Никео-Цареградским. Он содержит краткое, но полное исповедание всей христианской веры — о Боге Отце и творении, о Христе и спасении, о Святом Духе, о Церкви, о крещении и о вечной жизни.</p>
   <p>С тех пор Символ остаётся неизменным: именно как соборно установленный, он не подлежит односторонним изменениям — что и стало одной из причин спора о западной прибавке filioque.</p>`, s:SRC.ist},
  {q:"Сколько было Вселенских соборов и против чего они?",
   a:`<p>Церковь признаёт семь Вселенских соборов, и каждый ограждал веру против определённой ереси. <em>Первый</em> (Никея, 325) — против Ария, утвердил Божество Сына и слово «единосущный». <em>Второй</em> (Константинополь, 381) — против духоборцев, о Божестве Святого Духа. <em>Третий</em> (Ефес, 431) — против Нестория, о единстве Лица Христа и о именовании «Богородица». <em>Четвёртый</em> (Халкидон, 451) — против монофизитства, о двух природах во Христе.</p>
   <p><em>Пятый</em> (Константинополь, 553) — по поводу споров, связанных с несторианством и оригенизмом. <em>Шестой</em> (Константинополь, 680–681) — против монофелитства, о двух волях и действиях Христа. <em>Седьмой</em> (Никея, 787) — против иконоборчества, утвердил иконопочитание.</p>
   <p>Так на протяжении почти пяти веков соборно и всё точнее раскрывалось учение о Святой Троице и о Богочеловеке Христе — сердцевина христианской веры.</p>`, s:SRC.ist},
  {q:"Кто такой святитель Афанасий Великий?",
   a:`<p>Святитель Афанасий (около 296–373), архиепископ Александрийский, — главный защитник православия в арианских спорах IV века. Ещё юным диаконом он участвовал в Никейском соборе (325 г.), а затем всю жизнь неустанно отстаивал единосущие Сына Отцу, за что пять раз был изгоняем со своей кафедры и провёл в изгнаниях около двадцати лет.</p>
   <p>Церковь именует его «отцом православия». Известны его слова, кратко выражающие смысл воплощения: Сын Божий стал человеком, чтобы человека сделать богом по благодати.</p>
   <p>Его несокрушимая стойкость в пору, когда арианство временно возобладало и при поддержке власти («Афанасий против всего мира»), сохранила Церкви никейскую веру — и потому его значение для истории догмата огромно.</p>`, s:SRC.ist},
  {q:"Что такое ереси и как Церковь на них отвечала?",
   a:`<p>Ересь — это упорное, сознательное искажение какого-либо догмата веры, отделяющее человека от Церкви. В первые века Церковь встретила множество ересей: гностицизм, арианство (о Сыне), несторианство и монофизитство (о Христе), иконоборчество и другие.</p>
   <p>Отвечала Церковь на них соборно — определениями Вселенских соборов — и трудами отцов, которые точно формулировали веру там, где еретики её искажали. Именно необходимость защитить истину заставляла давать ей всё более ясные выражения (как слово «единосущный»).</p>
   <p>Блаженный Августин заметил, что многое в вероучении раскрылось яснее именно тогда, когда истину пришлось оборонять от заблуждений. Так ереси, будучи злом, невольно послужили более точному и полному исповеданию веры.</p>`, s:SRC.dog+" · "+SRC.ist},
  {q:"Как распространялось христианство у славян?",
   a:`<p>В IX веке святые равноапостольные братья Кирилл (в миру Константин) и Мефодий, «первоучители славянские», создали славянскую азбуку и перевели на понятный славянам язык Священное Писание и богослужебные книги. Это открыло славянским народам путь к вере на родном языке, а не на чужой латыни или греческом.</p>
   <p>Плодом их дела и трудов их учеников стало принятие христианства болгарами, сербами, моравами, а в 988 году — Русью при святом князе Владимире.</p>
   <p>Так славянские народы вошли в семью христианских народов и восприняли византийскую православную традицию вместе с письменностью и книжностью, что определило всю их последующую культуру.</p>`, s:SRC.ist},
  {q:"В чём причины разделения Церквей 1054 года?",
   a:`<p>Причины «Великого раскола» копились веками и были разнородны. <em>Вероучительная</em> — самовольное внесение на Западе в общий Символ веры прибавки filioque (об исхождении Духа «и от Сына»), которую Восток не мог принять ни по существу, ни как одностороннее изменение соборного Символа.</p>
   <p><em>Каноническая и церковно-политическая</em> — растущие притязания Римского епископа на единоличную власть над всей Церковью, тогда как Восток признавал за ним лишь первенство чести как за «первым среди равных» патриархов. Добавлялись обрядовые различия (опресноки в Евхаристии, посты, безбрачие духовенства) и глубокое отдаление латинского Запада от греческого Востока по языку и культуре.</p>
   <p>Формальным рубежом стали взаимные отлучения 1054 года; но подлинно необратимым разрыв сделали позднейшие события, особенно разграбление Константинополя латинскими крестоносцами в 1204 году.</p>`, s:SRC.ist}
 ]
},

/* ============================ 17. ХРИСТИАНСКАЯ ЭТИКА ============================ */
{
 id:"etika", title:"Христианская жизнь",
 sub:"Нравственное богословие: заповеди и добродетели",
 qa:[
  {q:"В чём главная заповедь христианина?",
   a:`<p>Главная заповедь — о любви к Богу и к ближнему. На вопрос законника о наибольшей заповеди Господь ответил: «Возлюби Господа Бога твоего всем сердцем твоим и всею душою твоею и всем разумением твоим: сия есть первая и наибольшая заповедь; вторая же подобная ей: возлюби ближнего твоего, как самого себя» ([[Мф 22:37]]).</p>
   <p>На этих двух заповедях, по слову Господа, «утверждается весь закон и пророки» — то есть в них корень и цель всех прочих заповедей. Любовь есть исполнение всего закона ([[Рим 13:10]]).</p>
   <p>И именно любовь Господь назвал отличительным признаком Своих учеников: «по тому узнают все, что вы Мои ученики, если будете иметь любовь между собою» ([[Ин 13:35]]).</p>`, s:SRC.pis},
  {q:"Каковы главные христианские добродетели?",
   a:`<p>Высшие, «богословские» добродетели — вера, надежда и любовь, ибо они непосредственно связуют человека с Богом. Из них, по слову апостола, «любовь больше» ([[1 Кор 13:13]]), потому что вера и надежда пребывают лишь до встречи с Богом лицом к лицу, а любовь не прекращается вовек.</p>
   <p>К ним примыкают «естественные» (кардинальные) добродетели, известные и языческим мудрецам: рассудительность, мужество, воздержание и справедливость. В христианстве они очищаются и возводятся к своей вершине любовью.</p>
   <p>Все истинные добродетели — плод действия благодати в свободном человеке; и без любви даже самые великие дела и дарования оказываются пусты: «если раздам всё имение моё… а любви не имею, нет мне в том никакой пользы» ([[1 Кор 13:3]]).</p>`, s:SRC.dog},
  {q:"Что такое Заповеди блаженства?",
   a:`<p>Заповеди блаженства — девять изречений, которыми Христос открыл Нагорную проповедь ([[Мф 5:3]]), начертав путь к истинному счастью в Боге. Они рисуют возрастающий образ христианина: нищета духа (смирение, сознание своей нужды в Боге), плач о грехах, кротость, алкание правды, милосердие, чистота сердца, миротворчество, терпение гонений за правду и за Христа.</p>
   <p>Каждой из них обещано блаженство — не земное благополучие, а близость к Богу и Царство Небесное; причём обещанное часто противоположно тому, что мир считает счастьем (миру блаженны богатые и сильные, а Христу — нищие духом и кроткие).</p>
   <p>Заповеди блаженства не отменяют десяти ветхозаветных заповедей, а возводят нравственную жизнь от запрета зла к вершине — к уподоблению Христу, Который Сам есть их живой образ.</p>`, s:SRC.pis},
  {q:"Как относиться к врагам?",
   a:`<p>По прямой и, быть может, самой поразительной заповеди Христа — с любовью, благословением и молитвой: «любите врагов ваших, благословляйте проклинающих вас, благотворите ненавидящим вас и молитесь за обижающих вас и гонящих вас» ([[Мф 5:44]]). Это одна из самых отличительных черт христианства, неведомая прежним учениям.</p>
   <p>Любовь к врагам не означает одобрения зла, лжи или несправедливости и не запрещает защищать других от насилия; она означает не воздавать злом за зло, не питать ненависти и желать самому обидчику добра и спасения. «Не будь побеждён злом, но побеждай зло добром» ([[Рим 12:21]]).</p>
   <p>Цель этой заповеди — уподобление Отцу Небесному, Который благ и к неблагодарным, и разрыв самой цепи зла, которую иначе месть продолжала бы без конца.</p>`, s:SRC.pis},
  {q:"Что такое смирение и почему оно так важно?",
   a:`<p>Смирение — это правдивое видение себя перед Богом: сознание своей немощи, зависимости от Бога и того, что всё доброе в нас — от Него. Это не самоуничижение, не притворство и не слабость характера, а трезвая правда о себе, свобода от гордости, тщеславия и самопревозношения.</p>
   <p>Отцы считали смирение основанием всех добродетелей, потому что без него даже добрые дела отравляются гордостью. Христос дал совершенный образ смирения и прямо призвал подражать Ему: «научитесь от Меня, ибо Я кроток и смирен сердцем, и найдёте покой душам вашим» ([[Мф 11:29]]).</p>
   <p>Смирение привлекает благодать, а гордость отгоняет её: «Бог гордым противится, а смиренным даёт благодать» ([[Иак 4:6]]). Гордость низвергла с неба денницу; смирение же возводит человека к Богу.</p>`, s:SRC.dog},
  {q:"Как христианину относиться к богатству?",
   a:`<p>Богатство само по себе не грех, и Писание знает праведных богачей (Авраам, Иов); грешно порабощение богатством, сребролюбие и жестокосердие. Опасность в том, что богатство легко становится идолом, занимающим в сердце место Бога: «не можете служить Богу и маммоне» ([[Мф 6:24]]).</p>
   <p>От имеющих достаток требуется нестяжательность (свобода сердца от привязанности к имуществу), благодарность Богу и щедрость к нуждающимся. Апостол предупреждает: «корень всех зол есть сребролюбие» ([[1 Тим 6:10]]).</p>
   <p>Истинное же сокровище христианин собирает на небесах, «где ни моль, ни ржа не истребляют» ([[Мф 6:20]]); земным богатством он призван распоряжаться как доверенным от Бога управитель, служа им ближним, а не себе одному.</p>`, s:SRC.pis},
  {q:"Что такое милостыня и дела милосердия?",
   a:`<p>Милостыня — это деятельная любовь к нуждающимся: помощь голодному, больному, заключённому, страннику, всякому в беде. Это не «необязательное дополнение» к вере, а прямое её требование, по которому, как показал Господь, будет вершиться суд.</p>
   <p>Господь таинственно отождествляет Себя с нуждающимися: «так как вы сделали это одному из сих братьев Моих меньших, то сделали Мне» ([[Мф 25:40]]) — значит, служа человеку в нужде, мы служим Самому Христу.</p>
   <p>Дела милосердия — вернейшее свидетельство живой веры и путь уподобления милосердному Богу; но творить их следует не напоказ и не ради похвалы, а в тайне, «чтобы левая рука не знала, что делает правая» ([[Мф 6:3]]).</p>`, s:SRC.pis},
  {q:"Как относиться к власти и государству?",
   a:`<p>Христианин повинуется законной власти и добросовестно исполняет гражданский долг во всём, что не противоречит вере и совести. Господь установил само это правило: «отдавайте кесарево кесарю, а Божие Богу» ([[Мф 22:21]]), разграничив области государства и Бога.</p>
   <p>Апостол Павел учит, что «нет власти не от Бога» ([[Рим 13:1]]) — то есть сам порядок власти, ограждающий общество от беззакония, установлен Богом ради общего блага, и потому повиновение ей — дело совести, а не только страха.</p>
   <p>Однако послушание властям не безусловно. Когда власть требует греха, идолопоклонства или отречения от Бога, действует высший закон, провозглашённый апостолами: «должно повиноваться больше Богу, нежели человекам» ([[Деян 5:29]]). Так первые христиане чтили императора и молились о нём, но отказывались поклоняться ему как богу — и шли за это на смерть.</p>`, s:SRC.pis},
  {q:"В чём смысл страдания в христианской жизни?",
   a:`<p>Страдание вошло в мир через грех и само по себе не есть благо. Но, принятое с верой, терпением и без ропота, оно приносит добрый плод: очищает душу, смиряет гордость, отрывает сердце от привязанности к земному и таинственно соединяет человека с крестом Христовым. Христос не устранил страдание из жизни, но Сам прошёл через него и наполнил его смыслом и надеждой.</p>
   <p>Апостол Павел, много страдавший, свидетельствует: «нынешние временные страдания ничего не стоят в сравнении с той славою, которая откроется в нас» ([[Рим 8:18]]).</p>
   <p>Поэтому христианин несёт скорби не с отчаянием и не с показным бесчувствием, а с надеждой, зная, что «любящим Бога, призванным по Его изволению, всё содействует ко благу» ([[Рим 8:28]]).</p>`, s:SRC.dog},
  {q:"К чему призван каждый христианин?",
   a:`<p>Каждый христианин, а не только монахи, подвижники и духовенство, призван к святости и совершенству в любви. Это призвание всеобще и не знает исключений: «по примеру призвавшего вас Святаго, и сами будьте святы во всех поступках; ибо написано: будьте святы, потому что Я свят» ([[1 Пет 1:16]]); «воля Божия есть освящение ваше» ([[1 Фес 4:3]]).</p>
   <p>Святость достигается не обязательно бегством от мира, а прежде всего верным исполнением заповедей на своём месте — в семье, в труде, в служении ближним, — через живую веру, участие в таинствах, молитву и дела любви.</p>
   <p>Путь этот, начатый в крещении, завершается в вечном общении с Богом, для которого человек и был сотворён; и потому святость — не удел избранных, а норма и цель христианской жизни.</p>`, s:SRC.dog}
 ]
},
];
